def _run_command(command: list[str]) -> str:
    try:
        completed = _run_subprocess_hidden(command, capture_output=True, text=True, timeout=1.5)
        if completed.returncode == 0:
            return completed.stdout.strip().strip("'").strip('"')
    except Exception:
        return ""
    return ""


def _make_path_writable(path: Path | str) -> None:
    try:
        os.chmod(path, stat.S_IWRITE | stat.S_IREAD | stat.S_IEXEC)
    except Exception:
        pass


def _rmtree_retry_writable(func, path: str, _exc_info) -> None:
    _make_path_writable(path)
    try:
        func(path)
    except Exception:
        pass


def _rmtree_onexc_retry_writable(func, path: str, _exc) -> None:
    _make_path_writable(path)
    try:
        func(path)
    except Exception:
        pass


def _remove_path_robust(path: Path) -> bool:
    """Remove files/trees robustly, including read-only AppData artifacts."""
    try:
        if not path.exists() and not path.is_symlink():
            return False
        _make_path_writable(path)
        if path.is_dir() and not path.is_symlink():
            try:
                shutil.rmtree(path, onexc=_rmtree_onexc_retry_writable)  # type: ignore[call-arg]
            except TypeError:
                shutil.rmtree(path, onerror=_rmtree_retry_writable)
        else:
            path.unlink(missing_ok=True)
        return True
    except Exception:
        return False


def _cleanup_temp_root(root: Path) -> int:
    """Delete one disposable Prompt Guide runtime root and return removed entries."""
    removed = 0
    if not root.exists():
        return removed
    try:
        for child in list(root.iterdir()):
            if _remove_path_robust(child):
                removed += 1
        try:
            root.rmdir()
        except OSError:
            pass
    except Exception:
        return removed
    return removed


def default_start_worktree_dir() -> Path:
    """Safe default for the Start-tab working tree.

    The Start tab is the evidence/source tree for existing-project feature mode.
    Using `.` as its initial value is risky because it depends on the GUI launch
    location. A dedicated temp folder keeps the initial scan/app state isolated
    until the user explicitly chooses a real project root.
    """
    root = prompt_guide_runtime_root() / "start-worktree"
    root.mkdir(parents=True, exist_ok=True)
    return root.resolve()


def cleanup_create_preview_temp_roots() -> int:
    """Remove stale Create preview sessions on program startup.

    Create previews are disposable review/temp clones. Keeping them across app
    launches causes stale context and confusing exports, so startup always starts
    from a clean session root.
    """
    removed = _cleanup_temp_root(prompt_guide_runtime_root() / "create-preview")
    removed += _cleanup_temp_root(Path(tempfile.gettempdir()) / "prompt-guide-create-preview")
    return removed


def default_export_temp_root() -> Path:
    """Shared disposable root for Worktree and Create exports."""
    root = prompt_guide_runtime_root() / "export"
    root.mkdir(parents=True, exist_ok=True)
    return root.resolve()


def default_worktree_export_dir() -> Path:
    """Disposable parent for normal Worktree export runs."""
    root = default_export_temp_root() / "worktree-export"
    root.mkdir(parents=True, exist_ok=True)
    return root.resolve()


def default_create_export_dir() -> Path:
    """Disposable parent for Create-export runs."""
    root = default_export_temp_root() / "create-export"
    root.mkdir(parents=True, exist_ok=True)
    return root.resolve()


def cleanup_create_export_temp_roots() -> int:
    """Remove stale Worktree/Create export artifacts on program startup."""
    return _cleanup_temp_root(default_export_temp_root())


def cleanup_patch_temp_roots() -> int:
    """Remove stale Patch-tab staging/version-control sessions on startup."""
    removed = _cleanup_temp_root(prompt_guide_runtime_root() / "patch-work")
    removed += _cleanup_temp_root(Path(tempfile.gettempdir()) / "prompt-guide-patch-work")
    return removed


def cleanup_prompt_guide_appdata_session_files() -> int:
    """Remove/recreate Prompt Guide AppData runtime artifacts on startup.

    If AppData/TEMP was manually deleted, treat it as a cold cache: recreate
    app-owned runtime folders and continue. The selected source repository,
    export folder, Git data and settings are never touched.
    """
    runtime_root = prompt_guide_runtime_root()
    removed = 0
    for name in ("create-preview", "export", "patch-work", "session", "terminal", "tmp"):
        removed += _cleanup_temp_root(runtime_root / name)
    removed += _cleanup_temp_root(PROMPT_GUIDE_PYCACHE_ROOT)
    try:
        PROMPT_GUIDE_PYCACHE_ROOT.mkdir(parents=True, exist_ok=True)
    except Exception:
        pass
    prompt_guide_ensure_appdata_runtime_dirs()
    return removed


def _colorref_to_hex(value: int) -> str:
    # Windows registry accent values are commonly stored in BGR/COLORREF-like order.
    r = value & 0xFF
    g = (value >> 8) & 0xFF
    b = (value >> 16) & 0xFF
    return f"#{r:02x}{g:02x}{b:02x}"


def detect_system_theme() -> dict[str, str | bool]:
    """Best-effort system color detection for Windows and Linux.

    No external dependency is required. If the platform does not expose a usable
    value, the GUI falls back to a sane light palette.
    """
    system = platform.system().lower()
    result: dict[str, str | bool] = {
        "platform": system or "unknown",
        "mode": "light",
        "is_dark": False,
        "accent": "#3584e4",
        "source": "fallback",
    }

    if system == "windows":
        try:
            import winreg  # type: ignore
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Themes\Personalize")
            apps_use_light, _ = winreg.QueryValueEx(key, "AppsUseLightTheme")
            result["is_dark"] = apps_use_light == 0
            result["mode"] = "dark" if result["is_dark"] else "light"
            result["source"] = "windows_registry"
        except Exception:
            pass
        try:
            import winreg  # type: ignore
            key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\DWM")
            accent_value, _ = winreg.QueryValueEx(key, "AccentColor")
            result["accent"] = _colorref_to_hex(int(accent_value))
        except Exception:
            try:
                import winreg  # type: ignore
                key = winreg.OpenKey(winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Explorer\Accent")
                accent_value, _ = winreg.QueryValueEx(key, "AccentColorMenu")
                result["accent"] = _colorref_to_hex(int(accent_value))
            except Exception:
                pass
        return result

    if system == "linux":
        color_scheme = _run_command(["gsettings", "get", "org.gnome.desktop.interface", "color-scheme"])
        gtk_theme = _run_command(["gsettings", "get", "org.gnome.desktop.interface", "gtk-theme"])
        accent = _run_command(["gsettings", "get", "org.gnome.desktop.interface", "accent-color"])
        combined = f"{color_scheme} {gtk_theme}".lower()
        if "dark" in combined or os.environ.get("COLORFGBG", "").split(";")[-1:] == ["0"]:
            result["is_dark"] = True
            result["mode"] = "dark"
        if accent:
            result["accent"] = SYSTEM_ACCENT_MAP.get(accent.lower(), result["accent"])
        result["source"] = "linux_gsettings" if color_scheme or gtk_theme or accent else "linux_fallback"
        return result

    if system == "darwin":
        mode = _run_command(["defaults", "read", "-g", "AppleInterfaceStyle"])
        if "dark" in mode.lower():
            result["is_dark"] = True
            result["mode"] = "dark"
            result["source"] = "macos_defaults"
        return result

    return result


def palette_from_theme(theme: dict[str, str | bool]) -> dict[str, str]:
    accent = str(theme.get("accent") or "#3584e4")
    if theme.get("is_dark"):
        return {
            "bg": "#1e1f22",
            "panel": "#2b2d31",
            "field": "#151619",
            "fg": "#f2f3f5",
            "muted": "#b8bcc6",
            "accent": accent,
            "select_bg": accent,
            "select_fg": "#ffffff",
        }
    return {
        "bg": "#f6f7f9",
        "panel": "#ffffff",
        "field": "#ffffff",
        "fg": "#1f2328",
        "muted": "#57606a",
        "accent": accent,
        "select_bg": accent,
        "select_fg": "#ffffff",
    }


