        progress_frame = ttk.Frame(root)
        progress_frame.pack(fill="x", pady=(0, 10))
        ttk.Label(progress_frame, textvariable=self.progress_status).pack(side="left")
        self.progress_bar = ttk.Progressbar(progress_frame, variable=self.progress_value, maximum=100, length=360)
        self.progress_bar.pack(side="right", fill="x", expand=True, padx=(12, 0))

        self.notebook = ttk.Notebook(root)
        self.notebook.pack(fill="both", expand=True)

        self.start_tab = ttk.Frame(self.notebook, padding=10)
