        self.schema_tab = ttk.Frame(self.library_notebook, padding=10)
        self.hook_tab = ttk.Frame(self.library_notebook, padding=10)
        self.reference_tab = ttk.Frame(self.library_notebook, padding=10)
        self.micro_tasks_tab = ttk.Frame(self.library_notebook, padding=10)
        self.library_notebook.add(self.schema_tab, text="Schema")
        self.library_notebook.add(self.hook_tab, text="Hooks / Weights")
        self.library_notebook.add(self.reference_tab, text="References / Roles")
        self.library_notebook.add(self.micro_tasks_tab, text="Micro Tasks")
        self.prompt_tab = ttk.Frame(self.notebook, padding=10)
        self.project_tree_tab = ttk.Frame(self.notebook, padding=10)
        self.settings_tab = ttk.Frame(self.notebook, padding=10)
        self.info_tab = ttk.Frame(self.notebook, padding=10)
        self.output_tab = ttk.Frame(self.notebook, padding=10)

        self.notebook.add(self.start_tab, text="Start")
        self.notebook.add(self.generator_tab, text="Generator")
        self.notebook.add(self.create_tab, text="Preview create")
        self.notebook.add(self.patch_tab, text="Patch")
        self.notebook.add(self.library_tab, text="Libraries")
        self.notebook.add(self.prompt_tab, text="Prompt Builder")
        self.notebook.add(self.project_tree_tab, text="Export")
        self.notebook.add(self.settings_tab, text="Settings")
        self.notebook.add(self.info_tab, text="INFO")
        self.notebook.add(self.output_tab, text="Output")

        self._build_start_tab()
        self._build_generator_tab()
        self._build_create_tab()
        self._build_patch_tab()
        self._build_schema_tab()
        self._build_hook_tab()
        self._build_reference_tab()
        self._build_prompt_tab()
        self._build_project_tree_tab()
        self._build_micro_tasks_tab()
        self._build_settings_tab()
        self._build_info_tab()
