    # ---------- Create Tab ----------
    def _create_schema_ids(self, key: str) -> set[str]:
        return {item.get("id", "") for item in self.schema.get(key, []) if isinstance(item, dict) and item.get("id")}

    def _create_supported_ids(self, key: str, ids: list[str]) -> list[str]:
        available = self._create_schema_ids(key)
        return [item_id for item_id in ids if item_id in available]

    def _module_ids_for_stack(self, key: str, stack_node_id: str) -> list[str]:
        stack_id = str(stack_node_id or "").strip()
        if not stack_id:
            return []
        result: list[str] = []
        for item in self.schema.get(key, []):
            if not isinstance(item, dict):
                continue
            if str(item.get("stack_node_id") or "").strip() == stack_id and item.get("id"):
                result.append(str(item.get("id")))
        return result

    def _schema_create_stack_catalog(self) -> dict[str, dict]:
        catalog: dict[str, dict] = {}
        for node in self.schema.get("create_stack_nodes", []):
            if not isinstance(node, dict):
                continue
            label = str(node.get("label") or node.get("id") or "").strip()
            if not label:
                continue
            dependency_groups = node.get("dependency_groups") or {}
            if not dependency_groups and node.get("dependency_group_ids"):
                by_id = {item.get("id"): item for item in self.schema.get("dependency_groups", []) if isinstance(item, dict)}
                for group_id in node.get("dependency_group_ids") or []:
                    group = by_id.get(group_id)
                    if group:
                        dependency_groups[group.get("label", group_id)] = list(group.get("dependencies", [])) + ["manifests: " + ", ".join(group.get("manifest_files", []))]
            catalog[label] = {
                "category": node.get("category", "Schema / Create Node"),
                "path": node.get("path", "./generated"),
                "path_type": node.get("path_type", node.get("build_target", "generated")),
                "ai_target": node.get("ai_target", "Codex"),
                "build_target": node.get("build_target", node.get("path_type", "generated")),
                "file_types": list(node.get("file_types", [])),
                "profiles": list(node.get("profiles", [])),
                "references": list(node.get("references", [])),
                "roles": list(node.get("roles", [])),
                "dependencies": node.get("dependencies", ""),
                "nvm_version": node.get("nvm_version") or node.get("node_version"),
                "node_version": node.get("node_version") or node.get("nvm_version"),
                "gradle_version": node.get("gradle_version") or node.get("android_gradle_version"),
                "dependency_group_ids": list(node.get("dependency_group_ids", [])),
                "dependency_groups": dependency_groups,
                "dependency_abstraction": node.get("dependency_abstraction", []),
                "tree": list(node.get("tree", [])),
                "timeline": list(node.get("timeline", [])),
                "placeholders": dict(node.get("placeholders", {})),
                "artifacts": list(node.get("artifacts", [])),
                "node_id": node.get("id", ""),
                "micro_task_ids": list(node.get("micro_task_ids", [])),
                "keywords": list(node.get("keywords", [])),
                "chain_boilerplate_ids": list(node.get("chain_boilerplate_ids", [])),
                "target_match_module_ids": self._module_ids_for_stack("target_match_boilerplates", node.get("id", "")),
                "feature_module_ids": self._module_ids_for_stack("feature_modules", node.get("id", "")),
                "refactor_module_ids": self._module_ids_for_stack("refactor_modules", node.get("id", "")),
            }
        return catalog

    def _dedupe_create_list(self, values: list | tuple | set | None) -> list:
        result = []
        for value in values or []:
            text = str(value).strip()
            if text and text not in result:
                result.append(text)
        return result

    def _dependency_groups_by_id(self) -> dict[str, dict]:
        return {str(item.get("id")): item for item in self.schema.get("dependency_groups", []) if isinstance(item, dict) and item.get("id")}

    def _dependency_install_token_for_ecosystem(self, ecosystem: str) -> str:
        value = ecosystem.lower().strip()
        if value in {"node", "yesvascript", "typescript", "frontend", "node/browser"}:
            return "{$install_node[dependency_version]}"
        if value in {"python", "pip", "pyproject"}:
            return "{$install_python[dependency_version]}"
        if value in {"conda", "scientific_python"}:
            return "{$install_conda[dependency_version]}"
        if value in {"flutter", "dart", "pub"}:
            return "{$install_flutter[dependency_version]}"
        if value in {"android", "gradle"}:
            return "{$install_android[dependency_version]}"
        if value in {"native", "cpp", "c", "cmake"}:
            return "{$install_native[dependency_version]}"
        return "{$resolve_dependency_manifest}"

    def _dependency_validation_token_for_ecosystem(self, ecosystem: str) -> str:
        value = ecosystem.lower().strip()
        if value in {"node", "yesvascript", "typescript", "frontend", "node/browser"}:
            return "{$npm_run_build}"
        if value in {"python", "pip", "pyproject", "conda", "scientific_python"}:
            return "{$python_compileall}"
        if value in {"flutter", "dart", "pub"}:
            return "{$flutter_test_optional}"
        if value in {"android", "gradle"}:
            return "{$gradle_build_optional}"
        if value in {"native", "cpp", "c", "cmake"}:
            return "{$cmake_build_optional}"
        return "manual_validation_required"

    def _infer_dependency_group_ids(self, label: str, config: dict) -> list[str]:
        text = " ".join([
            str(label),
            str(config.get("category", "")),
            str(config.get("dependencies", "")),
            " ".join(str(item) for item in config.get("file_types", []) or []),
        ]).lower()
        result: list[str] = []
        def add(group_id: str) -> None:
            if group_id not in result:
                result.append(group_id)
        if re.search(r"\bvue\b", text) or re.search(r"\bvite\b", text):
            add("dep_web_vue_vite")
        if re.search(r"\breact\b", text) or re.search(r"\bnext\b", text):
            add("dep_web_react_next")
        if re.search(r"\bsvelte\b", text) or re.search(r"\bsveltekit\b", text):
            add("dep_web_sveltekit")
        if "node" in text:
            add("dep_node_api")
        if "fastapi" in text or "flask" in text or "pydantic" in text or "python" in text or "py" in text:
            add("dep_python_api")
        if "anaconda" in text or "numpy" in text or "pandas" in text or "science" in text:
            add("dep_python_data_ai")
        if "llm" in text or "prompt" in text or "agent" in text:
            add("dep_llm_agent")
        if "android" in text or "gradle" in text or "kotlin" in text:
            add("dep_mobile_android")
        if "flutter" in text or "dart" in text:
            add("dep_mobile_flutter")
        if "three" in text or "webgl" in text or "shader" in text:
            add("dep_graphics_webgl")
        if "scss" in text or "tailwind" in text or "vuetify" in text or "design" in text:
            add("dep_design_system")
        if "c++" in text or "cpp" in text or "cmake" in text or "native" in text:
            add("dep_native_cpp")
        if "docker" in text or "devops" in text or "release" in text:
            add("dep_devops_release")
        if "docs" in text or "documentation" in text or "markdown" in text or "compliance" in text:
            add("dep_docs_compliance")
        if "micro" in text or "project to markdown" in text or "terminal" in text:
            add("dep_python_project_tools")
            add("dep_terminal_timeline")
        if "repository" in text or "management" in text:
            add("dep_repository_prompt_pack")
        add("dep_create_isolated_export")
        return result

    def _dependency_abstraction_layer(self, config: dict) -> list[dict]:
        groups_by_id = self._dependency_groups_by_id()
        result: list[dict] = []
        seen = set()
        for group_id in config.get("dependency_group_ids", []) or []:
            group = groups_by_id.get(str(group_id))
            if not group:
                continue
            ecosystem = str(group.get("ecosystem") or "generic")
            entry = {
                "id": str(group.get("id")),
                "label": str(group.get("label") or group.get("id")),
                "ecosystem": ecosystem,
                "manifest_files": list(group.get("manifest_files", [])),
                "dependencies": list(group.get("dependencies", [])),
                "install_token": self._dependency_install_token_for_ecosystem(ecosystem),
                "validation_token": self._dependency_validation_token_for_ecosystem(ecosystem),
                "swap_policy": str(group.get("lts_policy") or "Use manifest evidence or exact user supplied versions; do not invent package versions."),
                "nvm_version": self._normalize_nvm_version(group.get("nvm_version") or group.get("node_version") or config.get("nvm_version") or config.get("node_version") or "None") or None,
                "gradle_version": self._normalize_gradle_version(group.get("gradle_version") or config.get("gradle_version") or "None") or None,
                "python_version": self._normalize_python_version(config.get("python_version") or self.create_python_version.get() if hasattr(self, "create_python_version") else "") or None,
                "python_path": config.get("python_path") or (self._selected_python_path_text() if hasattr(self, "create_python_path") else "") or None,
            }
            result.append(entry)
            seen.add(entry["id"])
        for entry in config.get("dependency_abstraction", []) or []:
            if not isinstance(entry, dict):
                continue
            entry_id = str(entry.get("id") or entry.get("label") or "dependency_layer").strip()
            if not entry_id or entry_id in seen:
                continue
            ecosystem = str(entry.get("ecosystem") or "generic")
            merged = {
                "id": entry_id,
                "label": str(entry.get("label") or entry_id),
                "ecosystem": ecosystem,
                "manifest_files": list(entry.get("manifest_files", [])),
                "dependencies": list(entry.get("dependencies", [])),
                "install_token": str(entry.get("install_token") or self._dependency_install_token_for_ecosystem(ecosystem)),
                "validation_token": str(entry.get("validation_token") or self._dependency_validation_token_for_ecosystem(ecosystem)),
                "swap_policy": str(entry.get("swap_policy") or "Use manifest evidence or exact user supplied versions; do not invent package versions."),
                "nvm_version": self._normalize_nvm_version(entry.get("nvm_version") or entry.get("node_version") or config.get("nvm_version") or config.get("node_version") or "None") or None,
                "gradle_version": self._normalize_gradle_version(entry.get("gradle_version") or config.get("gradle_version") or "None") or None,
                "python_version": self._normalize_python_version(config.get("python_version") or self.create_python_version.get() if hasattr(self, "create_python_version") else "") or None,
                "python_path": config.get("python_path") or (self._selected_python_path_text() if hasattr(self, "create_python_path") else "") or None,
            }
            result.append(merged)
            seen.add(entry_id)
        if not result and config.get("dependencies"):
            result.append({
                "id": "custom_dependencies",
                "label": "Custom dependencies",
                "ecosystem": "generic",
                "manifest_files": [],
                "dependencies": [item.strip() for item in str(config.get("dependencies", "")).split("|") if item.strip()],
                "install_token": "{$resolve_dependency_manifest}",
                "validation_token": "manual_validation_required",
                "swap_policy": "Resolve against the selected stack manifest or exact user supplied versions; do not guess versions.",
                "nvm_version": self._normalize_nvm_version(config.get("nvm_version") or config.get("node_version") or "None") or None,
                "gradle_version": self._normalize_gradle_version(config.get("gradle_version") or "None") or None,
                "python_version": self._normalize_python_version(config.get("python_version") or self.create_python_version.get() if hasattr(self, "create_python_version") else "") or None,
                "python_path": config.get("python_path") or (self._selected_python_path_text() if hasattr(self, "create_python_path") else "") or None,
            })
        return result

    def _normalize_create_stack_config(self, label: str, config: dict) -> dict:
        config = dict(config or {})
        config.setdefault("category", "Other")
        config.setdefault("path", "./generated")
        config.setdefault("path_type", config.get("build_target", "generated"))
        config.setdefault("ai_target", "Codex")
        config.setdefault("build_target", config.get("path_type", "generated"))
        config["file_types"] = self._dedupe_create_list(config.get("file_types") or ["json", "md", "shell"])
        config["profiles"] = self._dedupe_create_list((config.get("profiles") or []) + ["Create", "ProfessionalSolutionEngineering"])
        config["references"] = self._dedupe_create_list((config.get("references") or []) + [
            "create_stack_reference",
            "create_project_mapping_reference",
            "dependency_abstraction_layer_reference",
            "create_terminal_timeline_reference",
            "professional_solution_engineering_reference",
        ])
        config["roles"] = self._dedupe_create_list((config.get("roles") or []) + [
            "create_stack_operator",
            "create_project_mapping_operator",
            "dependency_abstraction_layer_operator",
            "create_terminal_timeline_operator",
            "professional_solution_engineering_operator",
        ])
        if not config.get("dependency_group_ids"):
            config["dependency_group_ids"] = self._infer_dependency_group_ids(label, config)
        dependency_layer = self._dependency_abstraction_layer(config)
        config["dependency_abstraction"] = dependency_layer
        if not config.get("dependencies") and dependency_layer:
            config["dependencies"] = " | ".join(
                dep for group in dependency_layer for dep in group.get("dependencies", [])[:6]
            )
        if not config.get("dependency_groups") and dependency_layer:
            config["dependency_groups"] = {group["label"]: group.get("dependencies", []) for group in dependency_layer}
        config["tree"] = self._dedupe_create_list(config.get("tree") or [config.get("path", "./generated")])
        timeline = self._dedupe_create_list(config.get("timeline") or [])
        if not any("{$create_target" in item for item in timeline):
            timeline.insert(0, f"{{$create_target[{config.get('build_target', 'generated')}]}}")
        required_tokens = ["{$write_temp_project_tree}", "{$apply_temp_tree_to_working_path}", "{$write_project_mapping}", "{$write_dependency_layer}", "{$compiler_run}", "{$write_handoff_index}"]
        for token in required_tokens:
            if token not in timeline:
                if "{$write_handoff_index}" in timeline and token != "{$write_handoff_index}":
                    timeline.insert(timeline.index("{$write_handoff_index}"), token)
                else:
                    timeline.append(token)
        config["timeline"] = timeline
        placeholders = dict(config.get("placeholders") or {})
        placeholders.setdefault("{$write_temp_project_tree}", "compile editable temp preview tree without modifying the working path")
        placeholders.setdefault("{$apply_temp_tree_to_working_path}", "copy checked temp preview tree into the Create working path on Run")
        placeholders.setdefault("{$write_project_mapping}", "skip removed project mapping sidecar")
        placeholders.setdefault("{$write_dependency_layer}", "skip removed dependency sidecar")
        placeholders.setdefault("{$compiler_run}", "run boilerplate-aligned compiler/test tasks when the required manifests or tools exist")
        placeholders.setdefault("{$write_handoff_index}", "write compact handoff index")
        config["placeholders"] = placeholders
        config["artifacts"] = self._dedupe_create_list((config.get("artifacts") or []) + [
            "CREATE_PREVIEW_TREE.json",
            "USER_PROMPT.txt",
        ])
        config["micro_task_ids"] = self._dedupe_create_list((config.get("micro_task_ids") or []) + [
            "task_terminal_auto_join",
            "task_project_mapping_refresh",
            "task_temp_preview_tree",
            "task_boilerplate_dependency_crud",
            "task_timeline_checkbox_control",
            "task_dependency_abstraction_layer",
        ])
        config["label"] = label
        return config

