        def _small_path_entry(parent: ttk.Frame, variable: tk.StringVar) -> ttk.Frame:
            # Tk entry width is normally measured in characters. The user asked
            # for compact 80px path boxes, so the entry sits inside a fixed-size
            # holder and does not expand across the Config card.
            holder = ttk.Frame(parent, width=80, height=24)
            holder.pack(side="left", padx=(4, 2))
            holder.pack_propagate(False)
            ttk.Entry(holder, textvariable=variable).pack(fill="both", expand=True)
            return holder

        def _runtime_item(title: str, version_var: tk.StringVar | None, path_label: str, path_var: tk.StringVar | None, browse_command, *, clear_command=None) -> ttk.Frame:
            item = ttk.Frame(self.create_runtime_flow)
            item.pack(side="left", anchor="w", padx=(0, 10), pady=2)
            ttk.Label(item, text=title).pack(side="left")
            if version_var is not None:
                ttk.Entry(item, textvariable=version_var, state="readonly", width=8).pack(side="left", padx=(4, 2))
            if path_var is not None:
                ttk.Label(item, text=path_label).pack(side="left", padx=(2, 0))
                _small_path_entry(item, path_var)
                ttk.Button(item, text="Browse", command=browse_command).pack(side="left", padx=(0, 2))
            if clear_command is not None:
                ttk.Button(item, text="Clear", command=clear_command).pack(side="left")
            return item

