    def _folder_name_as_project_name(self, path: Path) -> str:
        name = Path(path).expanduser().name.strip()
        if name and name not in {".", ".."}:
            return re.sub(r"[^A-Za-z0-9_.-]+", "-", name).strip("-") or name
        return ""

    def _set_project_name_from_folder(self, path: Path, *, allow_temp: bool = False) -> None:
        """Use the selected/imported project folder name as project name.

        Synthetic startup temp roots are ignored unless a Create action explicitly
        asks for temp-derived naming. User-selected Start or Create project
        folders remain authoritative.
        """
        try:
            candidate = Path(path).expanduser().resolve()
            if not allow_temp and self._path_is_under_system_temp(candidate):
                return
            if not allow_temp and self._path_is_synthetic_project_root(candidate):
                return
            name = self._folder_name_as_project_name(candidate)
            if name:
                self.project_name.set(name)
        except Exception:
            pass

    def _path_entry_value_for_project(self, path: Path) -> str:
        base = Path(self.output_base.get() or ".").expanduser().resolve()
        try:
            return path.expanduser().resolve().relative_to(base).as_posix()
        except Exception:
            return str(path)

    def _resolve_create_path(self, raw_value: str, fallback: str = ".") -> Path:
        base = Path(self.output_base.get() or ".").expanduser().resolve()
        raw = str(raw_value or fallback or ".").strip()
        candidate = Path(raw).expanduser()
        if not candidate.is_absolute():
            candidate = base / candidate
        return candidate.resolve()

    def _path_is_inside_start_worktree(self, path: Path, base: Path | None = None) -> bool:
        try:
            base_resolved = Path(base or self.output_base.get() or ".").expanduser().resolve()
            candidate = Path(path).expanduser().resolve()
            candidate.relative_to(base_resolved)
            return True
        except Exception:
            return False

    def _export_temp_root(self) -> Path:
        return default_export_temp_root().resolve()

    def _safe_export_root(self, base: Path | None = None) -> Path:
        # Normal Worktree exports are disposable review artifacts. They live under
        # the same Temp/export-prompt-guide-start-worktree root as Create exports,
        # never inside the inspected working tree.
        return (self._export_temp_root() / "worktree-export").resolve()

    def _resolve_export_path(self, raw_value: str, fallback_name: str = "worktree-export") -> Path:
        safe_root = self._safe_export_root()
        raw = str(raw_value or "").strip()
        if not raw:
            return safe_root
        normalized = raw.replace("\\", "/").strip("/")
        if normalized in {"output", "output/export", "./output/export", "export", "worktree-export"}:
            return safe_root
        candidate = Path(raw).expanduser()
        if not candidate.is_absolute():
            candidate = safe_root / candidate
        return candidate.resolve()

    def _export_project_slug(self) -> str:
        return re.sub(r"[^A-Za-z0-9_.-]+", "_", self.project_name.get().strip() or "project")[:48].strip("._-") or "project"

    def _export_run_id(self, source: str) -> str:
        stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
        project = self._export_project_slug()
        digest = hashlib.sha1(f"{source}|{project}|{time.time_ns()}".encode("utf-8", errors="ignore")).hexdigest()[:8]
        return f"{project}_{source}_{stamp}_{digest}"

    def _stable_export_id(self, source: str) -> str:
        return f"{self._export_project_slug()}_{source}_stable"

    def _next_worktree_export_path(self) -> Path:
        parent = self._resolve_export_path(self.export_dir.get(), "worktree-export")
        if bool(self.overwrite.get()):
            return (parent / self._stable_export_id("worktree")).resolve()
        return (parent / self._export_run_id("worktree")).resolve()

    def _next_create_export_path(self) -> Path:
        parent = self._resolve_create_export_path(self.create_export_dir.get())
        if bool(self.overwrite.get()):
            return (parent / self._stable_export_id("create")).resolve()
        return (parent / self._export_run_id("create")).resolve()

    def _create_working_dir(self) -> Path:
        raw = self.create_working_path.get().strip() or self.create_target_path.get().strip() or "."
        return self._resolve_create_path(raw, ".")

    def _resolve_create_export_path(self, raw_value: str = "") -> Path:
        # Create exports intentionally share the same Custom Export Path as normal Worktree exports.
        return self._resolve_export_path(raw_value or self.export_dir.get(), "custom-export")

    def _create_export_path(self) -> Path:
        return self._resolve_export_path(self.export_dir.get(), "custom-export")

    def _display_create_working_path(self) -> str:
        return self._path_entry_value_for_project(self._create_working_dir())

    def _display_create_export_dir(self) -> str:
        return str(self._create_export_path())

    def _create_path_binding_signature(self) -> str:
        try:
            return json.dumps({
                "start_root": str(self._normalize_start_working_tree().resolve()),
                "target_path": str(self.create_target_path.get() or ""),
                "working_path": str(self.create_working_path.get() or ""),
            }, sort_keys=True, ensure_ascii=False)
        except Exception:
            return f"{self.output_base.get()}|{self.create_target_path.get()}|{self.create_working_path.get()}"

    def _on_create_path_binding_changed(self, reason: str = "path_changed") -> None:
        signature = self._create_path_binding_signature()
        previous = str(getattr(self, "_create_last_path_binding_signature", "") or "")
        self._create_last_path_binding_signature = signature
        if previous and previous != signature:
            # A manual Create working/target path change must not keep a stale temp
            # preview root from a previous Project Root. Clear only the temp pointer;
            # Start-tab source evidence remains available for the next refresh/clone.
            self._create_tree_temp_root = None
            self._create_tree_temp_signature = ""
            try:
                self.create_temp_preview_dir.set("")
            except Exception:
                pass
            self._create_last_scope_sync_signature = None
        self._schedule_create_worktree_refresh(reason)
        self._schedule_create_preview_refresh()

    def _browse_create_target_path(self) -> None:
        selected = filedialog.askdirectory(title="Choose Create target path", initialdir=str(self._resolve_create_path(self.create_target_path.get(), ".")))
        if selected:
            self.create_target_path.set(self._path_entry_value_for_project(Path(selected)))
            self._set_project_name_from_folder(Path(selected))
            self._schedule_create_preview_refresh()

    def _browse_create_working_path(self) -> None:
        selected = filedialog.askdirectory(title="Choose Create-only working path", initialdir=str(self._create_working_dir()))
        if selected:
            self.create_working_path.set(self._path_entry_value_for_project(Path(selected)))
            self._set_project_name_from_folder(Path(selected))
            self._invalidate_project_tree_cache("create_working_dir_changed")
            if self._use_create_working_dir_for_project_tree():
                self._refresh_project_tree(force_scan=True, reason="create_working_dir_changed")
            self._schedule_create_preview_refresh()

    def _browse_create_export_dir(self) -> None:
        self._browse_export_dir()
        self._schedule_create_preview_refresh()

    def _reset_create_export_dir(self) -> None:
        self._reset_export_dir_to_project()
        self._schedule_create_preview_refresh()

    def _selected_nvm_root_path_text(self) -> str:
        """Return the user-selected NVM root or Node version folder, if any."""
        return str(getattr(self, "create_nvm_root_path", tk.StringVar(value="")).get() or "").strip()

    def _selected_nvm_root_path(self) -> Path | None:
        raw = self._selected_nvm_root_path_text()
        if not raw:
            return None
        try:
            return Path(os.path.expandvars(raw)).expanduser()
        except Exception:
            return None

    def _has_user_selected_nvm_path(self) -> bool:
        """Return True when the user explicitly pinned an NVM/Node path.

        A pinned path is authoritative. Automatic APPDATA/NVM_HOME probing may
        only run as a fallback when this field is empty. This prevents stack
        changes or background probes from silently replacing a custom setup such
        as C:/node or C:/node/v24.16.0 with C:/Users/.../AppData/Roaming/nvm.
        """
        return bool(self._selected_nvm_root_path_text())

    def _browse_create_nvm_root_path(self) -> None:
        initial = self._selected_nvm_root_path() or self._windows_nvm_home_for_runtime() or Path.home()
        selected = filedialog.askdirectory(title="Choose NVM root or installed Node version folder", initialdir=str(initial))
        if selected:
            self.create_nvm_root_path.set(str(Path(selected)))

    def _reset_create_nvm_root_path(self) -> None:
        self.create_nvm_root_path.set("")
        self._on_create_nvm_path_changed()

    def _on_create_nvm_path_changed(self) -> None:
        # User-provided NVM path is intentionally persistent across stack changes.
        # Stack changes may hide the field for non-Node boilerplates, but they must
        # not clear this value because many Windows setups use a custom NVM root.
        self._append_create_history_record("nvm_path_selected", {"path": self._selected_nvm_root_path_text() or "unset"})
        if self._stack_contains_node_runtime(self._current_create_config()):
            self._sync_nvm_version_from_stack_switch(self._current_create_config(), "nvm_path_changed")
        self._schedule_create_preview_refresh()

    def _set_packed_runtime_control_visible(self, widget: object, visible: bool, **pack_options) -> None:
        """Show/hide runtime widgets regardless of pack/grid manager.

        Older code used this for packed runtime controls. The Create header now
        grids runtime rows, so using pack_forget() on a gridded widget silently
        left controls visible. grid_remove() keeps the original grid options so
        the row can reappear when the matching schema/boilerplate is selected.
        """
        if widget is None:
            return
        try:
            manager = widget.winfo_manager()
        except Exception:
            return
        try:
            if visible:
                if manager == "":
                    try:
                        widget.grid()
                    except Exception:
                        widget.pack(**pack_options)
                return
            if manager == "grid":
                widget.grid_remove()
            elif manager == "pack":
                widget.pack_forget()
            elif manager:
                try:
                    widget.grid_remove()
                except Exception:
                    try:
                        widget.pack_forget()
                    except Exception:
                        pass
        except Exception:
            pass

    def _create_project_tree_base_if_available(self) -> Path | None:
        """Return the current read-only Create export tree base, if one exists.

        The Export tab source switch is only a view/export-mode selector. It may
        inspect a completed Build or an already mounted Create clone, but it must
        never allocate a new temp path, clone, reset, unmount, or heal Create
        state by side effect.
        """
        if str(getattr(self, "_create_clone_required_reason", "") or ""):
            return None
        completed = self._completed_create_build_root_for_current_stack()
        if completed is not None and completed.exists():
            return completed.resolve()
        try:
            root = self._known_create_temp_root()
            if root is None or not root.exists():
                return None
            root = root.resolve()
            manifest_path = root / "CREATE_SOURCE_CLONE_MANIFEST.json"
            loaded_signature = str(getattr(self, "_create_source_loaded_signature", "") or "")
            mount_signature = str(getattr(self, "_create_source_mount_signature", "") or "")
            if not loaded_signature or not mount_signature:
                return None
            manifest = getattr(self, "_create_source_clone_manifest", None)
            if isinstance(manifest, dict):
                manifest_signature = str(manifest.get("source_mount_signature") or "")
                if not manifest_signature or manifest_signature == loaded_signature:
                    return root
            if manifest_path.exists():
                raw_manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
                if str(raw_manifest.get("source_mount_signature") or "") == loaded_signature:
                    self._create_source_clone_manifest = raw_manifest
                    return root
        except Exception:
            return None
        return None

    def _project_tree_create_source_available(self) -> bool:
        # Export must expose Create Working Dir only when the Create tab already
        # has a valid completed Build or mounted clone. The check is read-only:
        # it never creates, deletes, clones or resets anything.
        return self._create_project_tree_base_if_available() is not None

    def _project_tree_source_values(self) -> list[str]:
        """Return user-selectable Export tree sources that are valid right now.

        Synchronization means stale Create Working Dir entries disappear after
        Unmount/Project Root reset, and reappear only after Create has a valid
        clone or Build.complete. It does not mean forcing the user's selection:
        when both sources are valid the user may freely choose Normal Worktree
        or Create Working Dir.
        """
        values = ["normal_working_tree"]
        if self._project_tree_create_source_available():
            values.append("create_working_dir")
        return values

    def _refresh_project_tree_source_options(self) -> None:
        values = self._project_tree_source_values()
        box = getattr(self, "project_tree_source_box", None)
        if box is not None:
            try:
                box.configure(values=values)
            except Exception:
                pass
        current = str(self.project_tree_source_mode.get() or "normal_working_tree")
        if current not in values or (current == "create_working_dir" and self._effective_project_tree_source_mode(sync_var=False) != "create_working_dir"):
            try:
                self.project_tree_source_mode.set("normal_working_tree")
            except Exception:
                pass
            self._set_progress("Export/Prompt tree source: stale Create Working Dir removed; Normal Worktree selected", 1, 1)
        self._refresh_export_settings_visibility()

    def _auto_select_create_working_dir_once(self, reason: str = "create_source_ready") -> None:
        """Select Create Working Dir exactly once after a new Create source appears.

        This is the only automatic Export tree-source switch. It is a handoff
        convenience after Create clone / Build.complete, not a lifecycle command:
        it must not clone, clean, reset or mutate Create state. After this one
        handoff, the user may freely switch back to Normal Worktree.
        """
        try:
            create_base = self._create_project_tree_base_if_available()
            if create_base is None:
                return
            record = self._active_successful_create_build_for_current_stack()
            record_id = str(record.get("id") or "") if isinstance(record, dict) else ""
            generation = str(int(getattr(self, "_create_clone_session_generation", 0) or 0))
            key = f"{reason}:{create_base.resolve()}:{record_id}:{generation}"
            if key == str(getattr(self, "_project_tree_last_auto_create_source_key", "") or ""):
                return
            self._refresh_project_tree_source_options()
            if "create_working_dir" not in self._project_tree_source_values():
                return
            self._project_tree_last_auto_create_source_key = key
            if str(self.project_tree_source_mode.get() or "") != "create_working_dir":
                self.project_tree_source_mode.set("create_working_dir")
            self._refresh_export_settings_visibility()
            # Programmatic StringVar changes do not emit <<ComboboxSelected>>.
            # Keep this handoff view-only: no automatic Project Tree scan here,
            # otherwise Build.complete can collide with an active Timeline/scan.
            self._set_progress("Export/Prompt tree source: Create Working Dir selected once after Create source became ready", 1, 1)
        except Exception:
            pass

    def _on_project_tree_source_mode_changed(self, _event=None) -> None:
        requested = str(self.project_tree_source_mode.get() or "normal_working_tree")
        self._refresh_project_tree_source_options()
        selected = str(self.project_tree_source_mode.get() or "normal_working_tree")
        self._refresh_export_settings_visibility()
        self._refresh_create_export_button_visibility()
        self._refresh_create_context_variable_menu()
        try:
            self._refresh_prompt_builder_context_variable_menu()
        except Exception:
            pass
        if requested == "create_working_dir" and selected != "create_working_dir":
            self._update_project_tree_status()
            self._set_progress("Project Tree: Create Working Dir is not available; Normal Export remains selected", 1, 1)
            return
        # Source switching is a read-only Export-tab view/mode switch. It must
        # not mutate Create state, select Build.complete, reset Project Root, or
        # schedule Create preview/materialization. It only re-renders the tree
        # from the chosen readable base so Include Imports and Selected Scope use
        # the user's selected Export source.
        self._refresh_project_tree(force_scan=False, reason="export_tree_source_view_selected")
        self._refresh_export_settings_visibility()
        try:
            self._schedule_prompt_builder_flow_refresh()
        except Exception:
            pass
        label = "Create Export" if self._use_create_working_dir_for_project_tree() else "Normal Export"
        self._set_progress(f"Project Tree: {label} source selected by user", 2, 2)

    def _main_dependency_summaries_for_config(self, config: dict | None = None) -> list[str]:
        """Return user-facing main dependency rows for the selected schema/boilerplate.

        Node/NVM and Gradle keep their dedicated controls. This summary covers
        the other main ecosystems so the Config header only shows dependency
        information when the chosen Stack/Schema/Boilerplate actually declares it.
        """
        config = config or self._current_create_config()
        ecosystem_labels = {
            "python": "Python",
            "pip": "Python",
            "pyproject": "Python",
            "conda": "Conda",
            "scientific_python": "Conda/Python",
            "pub": "Flutter/Dart",
            "flutter": "Flutter/Dart",
            "dart": "Dart",
            "native": "C/C++ Toolchain",
            "cpp": "C/C++ Toolchain",
            "c": "C Toolchain",
            "cmake": "CMake",
            "ops": "Docker/DevOps",
            "docker": "Docker",
            "documentation": "Software Docs",
            "prompt_engineering": "Prompt/Eval Pack",
            "mixed": "Mixed/LLM Tooling",
            "cross_platform_shell": "Terminal/Shell",
        }
        hidden = {"node", "yesvascript", "typescript", "frontend", "node/browser", "android", "gradle", "export", "create", "generic"}
        result: list[str] = []
        seen: set[str] = set()
        for entry in self._dependency_abstraction_layer(config):
            if not isinstance(entry, dict):
                continue
            ecosystem = str(entry.get("ecosystem") or "generic").strip().lower()
            if ecosystem in hidden:
                continue
            label = ecosystem_labels.get(ecosystem, ecosystem.replace("_", " ").title())
            manifests = [str(item) for item in entry.get("manifest_files", []) or [] if str(item).strip()]
            deps = [str(item) for item in entry.get("dependencies", []) or [] if str(item).strip()]
            detail = ", ".join(manifests[:2]) or ", ".join(deps[:2]) or str(entry.get("label") or "")
            runtime_hint = self._runtime_hint_label_for_ecosystem(ecosystem)
            if runtime_hint:
                detail = f"{detail}; {runtime_hint}" if detail else runtime_hint
            text = f"{label}: {detail}" if detail else label
            if text not in seen:
                result.append(text)
                seen.add(text)
        return result

    def _runtime_hint_label_for_ecosystem(self, ecosystem: object) -> str:
        value = str(ecosystem or "").strip().lower()
        hints = getattr(self, "_create_ecosystem_runtime_hints", {}) if isinstance(getattr(self, "_create_ecosystem_runtime_hints", {}), dict) else {}
        if value in {"python", "pip", "pyproject", "conda", "scientific_python"}:
            version = self._normalize_python_version(self.create_python_version.get())
            path = self._selected_python_path_text()
            parts = []
            if version:
                parts.append(f"Python {version}")
            if path:
                parts.append(f"path={path}")
            return ", ".join(parts)
        lookup = {"flutter": "Flutter", "dart": "Dart", "pub": "Flutter", "dotnet": ".NET", "go": "Go", "rust": "Rust", "yesva": "Java", "maven": "Java/Maven", "native": "Native", "cpp": "Native", "cmake": "CMake", "docker": "Dockerfile", "ops": "Dockerfile"}
        key = value
        if value in {"dart", "pub"}:
            key = "flutter"
        if value == "maven":
            key = "yesva"
        data = hints.get(key) or {}
        version = str(data.get("version") or "").strip()
        label = lookup.get(value, lookup.get(key, ""))
        if key == "docker":
            dockerfile = str(data.get("dockerfile_path") or self._selected_runtime_path_text("docker") or "").strip()
            return f"Dockerfile {Path(dockerfile).name}" if dockerfile else ("Dockerfile" if data.get("detected") else "")
        return f"{label} {version}".strip() if version and label else (label if label and data.get("detected") else "")

    def _refresh_create_main_dependency_controls(self, config: dict | None = None) -> None:
        rows = self._main_dependency_summaries_for_config(config)
        frame = getattr(self, "create_main_dependency_controls", None)
        label = getattr(self, "create_main_dependency_label", None)
        if label is not None:
            try:
                label.configure(text=" | ".join(rows[:3]) + (f" | +{len(rows)-3} more" if len(rows) > 3 else ""))
            except Exception:
                pass
        self._set_packed_runtime_control_visible(frame, bool(rows), side="left", padx=(0, 8))

    def _refresh_create_runtime_field_visibility(self, config: dict | None = None) -> None:
        """Show runtime controls only for stacks that actually use them.

        The backing variables are not reset when a group is hidden. In particular
        a manually selected NVM path survives switching to Python/Gradle/etc. and
        reappears unchanged when the user returns to a Node stack.
        """
        config = config or self._current_create_config()
        show_node = self._stack_contains_node_runtime(config)
        show_gradle = self._stack_contains_gradle_runtime(config)
        hints = getattr(self, "_create_ecosystem_runtime_hints", {}) or {}
        show_python = self._stack_contains_ecosystem_runtime(config, {"python", "pip", "pyproject", "conda", "scientific_python"}) or bool(hints.get("python", {}).get("detected")) or bool(self._selected_runtime_path_text("python"))
        show_ecosystems = bool(hints)
        self._set_packed_runtime_control_visible(getattr(self, "create_nvm_controls", None), show_node, side="left", padx=(0, 8))
        self._set_packed_runtime_control_visible(getattr(self, "create_gradle_controls", None), show_gradle or bool(hints.get("gradle", {}).get("detected")) or bool(self._selected_runtime_path_text("gradle")), side="left", padx=(0, 12))
        self._set_packed_runtime_control_visible(getattr(self, "create_python_controls", None), show_python, side="left", padx=(0, 8))
        extra_box = getattr(self, "create_extra_runtime_controls", None)
        extra_any = False
        for eco, _label, _version_var, _path_var in self._extra_runtime_control_specs():
            visible = bool(hints.get(eco, {}).get("detected")) or self._stack_contains_ecosystem_runtime(config, {eco}) or bool(self._selected_runtime_path_text(eco))
            row = getattr(self, "create_extra_runtime_rows", {}).get(eco) if hasattr(self, "create_extra_runtime_rows") else None
            if row is not None:
                self._set_packed_runtime_control_visible(row, visible, side="left", anchor="w", padx=(0, 10), pady=2)
            extra_any = extra_any or visible
        # The Compiler path lives in the same horizontal runtime/path flow and is
        # intentionally always available; it is a user override, not an
        # ecosystem-only field.
        self._set_packed_runtime_control_visible(getattr(self, "create_compiler_path_controls", None), True, side="left", anchor="w", padx=(0, 10), pady=2)
        runtime_grid_visible = show_node or show_gradle or show_python or extra_any or True
        self._set_packed_runtime_control_visible(extra_box, runtime_grid_visible)
        self._set_packed_runtime_control_visible(getattr(self, "create_ecosystem_runtime_controls", None), show_ecosystems, side="left", padx=(0, 8))
        self._refresh_create_main_dependency_controls(config)

    def _effective_project_tree_source_mode(self, *, sync_var: bool = False) -> str:
        """Return the actually usable Export/Prompt tree source.

        `project_tree_source_mode` is the user's selector. The effective source
        is create_working_dir only when the selector requests it and the Create
        tab has a valid completed Build or mounted clone. All Export, Prompt,
        Include-Imports and Selected-Scope features use this resolver so stale
        Create paths cannot leak into workers while the UI still remains user
        selectable whenever both sources are valid.
        """
        try:
            var = getattr(self, "project_tree_source_mode", None)
            value = var.get() if var is not None else "normal_working_tree"
            requested = str(value or "normal_working_tree").strip()
        except Exception:
            requested = "normal_working_tree"
        if requested == "create_working_dir" and self._project_tree_create_source_available():
            return "create_working_dir"
        if requested == "create_working_dir" and sync_var:
            try:
                self.project_tree_source_mode.set("normal_working_tree")
            except Exception:
                pass
        return "normal_working_tree"

    def _use_create_working_dir_for_project_tree(self) -> bool:
        return self._effective_project_tree_source_mode(sync_var=False) == "create_working_dir"

    def _active_project_tree_base(self) -> Path:
        if self._use_create_working_dir_for_project_tree():
            # Create Working Dir is only a readable Export source when Create has
            # already produced a completed Build or mounted clone. Do not fall
            # back to a synthetic create_working_path here, because that is how
            # source switching used to produce missing-path errors or implicit
            # resets. If the source is stale, read the normal worktree instead;
            # _refresh_project_tree_source_options() will remove the stale option
            # from the combobox.
            create_base = self._create_project_tree_base_if_available()
            if create_base is not None:
                return create_base
        return self._normalize_start_working_tree().resolve()

    def _active_project_tree_export_dir(self, base: Path | None = None) -> Path:
        # View/index helper only. Actual export buttons use explicit worktree/create
        # export paths so switching the preview source cannot silently change the
        # export mode.
        if self._use_create_working_dir_for_project_tree():
            return self._create_export_path().resolve()
        return self._worktree_export_dir(base or self._active_project_tree_base()).resolve()

    def _worktree_export_base(self) -> Path:
        return self._normalize_start_working_tree().resolve()

    def _worktree_export_dir(self, base: Path | None = None) -> Path:
        return self._current_export_dir(base or self._worktree_export_base()).resolve()

    def _create_placeholder_map(self) -> dict[str, str]:
        result: dict[str, str] = {}
        for line in self._editable_text_lines("create_placeholder_text", {}):
            if "=" not in line:
                continue
            key, value = line.split("=", 1)
            key = key.strip()
            value = value.strip()
            if key:
                result[key] = value
        return result

    def _shell_join(self, args: list[str | Path]) -> str:
        values = [str(arg) for arg in args]
        if platform.system().lower().startswith("win"):
            return subprocess.list2cmdline(values)
        return shlex.join(values)

    def _python_runtime_executable(self, target: object = "") -> str:
        """Return a CLI Python for generated timeline scripts.

        In frozen GUI builds sys.executable is the app executable; using it from
        create_timeline_run.cmd with ``-c`` reopens the main process.
        """
        selected = self._selected_python_path_text()
        return safe_python_executable(selected)

    def _normalize_nvm_version(self, value: object) -> str:
        version = str(value or "").strip()
        # No Auto state: runtime is either a concrete detected/selected version,
        # None, or a force version declared by the boilerplate.
        if version.lower() in {"", "none", "null", "false", "0", "off", "n/a", "auto", "current", "node", "lts", "lts/*"}:
            return ""
        return version.lstrip("v")

    def _normalize_gradle_version(self, value: object) -> str:
        version = str(value or "").strip()
        if version.lower() in {"", "none", "null", "false", "0", "off", "n/a"}:
            return ""
        return version

    def _runtime_major(self, value: object) -> int | None:
        """Return the major runtime version, or None for unresolved values."""
        text = str(value or "").strip().lower().lstrip("v")
        if text in {"", "none", "null", "auto", "current", "node", "lts", "lts/*"}:
            return None
        match = re.search(r"(?<!\d)(\d+)", text)
        return int(match.group(1)) if match else None

    def _runtime_version_at_least(self, value: object, minimum: object) -> bool:
        """Return True when value's major version satisfies the minimum major."""
        min_major = self._runtime_major(minimum)
        if min_major is None:
            return True
        value_major = self._runtime_major(value)
        return value_major is not None and value_major >= min_major

    def _resolve_min_runtime_version(self, candidate: object, minimum: object, normalizer) -> str:
        """Resolve a selected/detected runtime against a boilerplate minimum."""
        minimum_value = normalizer(minimum)
        candidate_value = normalizer(candidate)
        if minimum_value:
            if candidate_value and self._runtime_version_at_least(candidate_value, minimum_value):
                return candidate_value
            return minimum_value
        return candidate_value

    def _resolve_node_runtime_version(self, candidate: object = "", config: dict | None = None) -> str:
        return self._resolve_min_runtime_version(candidate, self._boilerplate_node_version(config), self._normalize_nvm_version)

    def _resolve_gradle_runtime_version(self, candidate: object = "", config: dict | None = None) -> str:
        return self._resolve_min_runtime_version(candidate, self._boilerplate_gradle_version(config), self._normalize_gradle_version)

    def _normalize_generic_version(self, value: object) -> str:
        text = str(value or "").strip()
        if not text or text.lower() in {"none", "auto", "unknown", "not found"}:
            return ""
        match = re.search(r"(?<!\d)(\d+(?:\.\d+){0,3})", text)
        return match.group(1) if match else ""

    def _normalize_python_version(self, value: object) -> str:
        text = str(value or "").strip()
        if not text or text.lower() in {"none", "auto", "unknown"}:
            return ""
        match = re.search(r"(?<!\d)(3(?:\.\d+){0,2}|2\.7(?:\.\d+)?)", text)
        return match.group(1) if match else ""

    def _selected_python_path_text(self) -> str:
        raw = str(getattr(self, "create_python_path", tk.StringVar(value="")).get() or "").strip()
        return raw

    def _extra_runtime_control_specs(self) -> list[tuple[str, str, tk.StringVar | None, tk.StringVar]]:
        return [
            ("flutter", "Flutter", self.create_flutter_version, self.create_flutter_path),
            ("dotnet", ".NET", self.create_dotnet_version, self.create_dotnet_path),
            ("go", "Go", self.create_go_version, self.create_go_path),
            ("rust", "Rust", self.create_rust_version, self.create_rust_path),
            ("yesva", "Java", self.create_yesva_version, self.create_yesva_path),
            ("native", "CMake", self.create_cmake_version, self.create_cmake_path),
            ("docker", "Dockerfile", None, self.create_dockerfile_path),
        ]

    def _runtime_path_var_for_ecosystem(self, ecosystem: str) -> tk.StringVar | None:
        mapping = {
            "python": self.create_python_path,
            "gradle": self.create_gradle_runtime_path,
            "flutter": self.create_flutter_path,
            "dotnet": self.create_dotnet_path,
            "go": self.create_go_path,
            "rust": self.create_rust_path,
            "yesva": self.create_yesva_path,
            "native": self.create_cmake_path,
            "cmake": self.create_cmake_path,
            "docker": self.create_docker_path,
        }
        return mapping.get(str(ecosystem or "").strip().lower())

    def _runtime_version_var_for_ecosystem(self, ecosystem: str) -> tk.StringVar | None:
        mapping = {
            "python": self.create_python_version,
            "gradle": self.create_gradle_version,
            "flutter": self.create_flutter_version,
            "dotnet": self.create_dotnet_version,
            "go": self.create_go_version,
            "rust": self.create_rust_version,
            "yesva": self.create_yesva_version,
            "native": self.create_cmake_version,
            "cmake": self.create_cmake_version,
            "docker": self.create_docker_version,
        }
        return mapping.get(str(ecosystem or "").strip().lower())

    def _selected_runtime_path_text(self, ecosystem: str) -> str:
        var = self._runtime_path_var_for_ecosystem(ecosystem)
        return str(var.get() or "").strip() if var is not None else ""

    def _runtime_hint_detected(self, ecosystem: str) -> bool:
        data = (getattr(self, "_create_ecosystem_runtime_hints", {}) or {}).get(str(ecosystem or "").strip().lower())
        return isinstance(data, dict) and bool(data.get("detected"))

    def _ecosystem_aliases_for_probe(self, ecosystem: str) -> set[str]:
        value = str(ecosystem or "").strip().lower()
        aliases = {value}
        if value in {"node", "yesvascript", "typescript", "frontend", "node/browser"}:
            aliases |= {"node", "yesvascript", "typescript", "frontend", "node/browser"}
        elif value in {"python", "pip", "pyproject", "conda", "scientific_python"}:
            aliases |= {"python", "pip", "pyproject", "conda", "scientific_python"}
        elif value in {"gradle", "android"}:
            aliases |= {"gradle", "android"}
        elif value in {"native", "cmake", "cpp", "c"}:
            aliases |= {"native", "cmake", "cpp", "c"}
        elif value in {"flutter", "dart", "pub"}:
            aliases |= {"flutter", "dart", "pub"}
        return aliases

    def _ecosystem_probe_payload_from_config(self, config: dict | None = None, reason: str = "stack_changed") -> dict:
        """Build runtime probe intent from the selected Stack/Boilerplate config.

        The existing tree scanner remains the source of project markers. This
        payload adds the stack-required ecosystems so installed/stageable tools
        such as Python/Conda are probed even when the project has no version pin.
        """
        config = config or self._current_create_config()
        ecosystems: dict[str, dict] = {}
        def add(eco: str, source: str) -> None:
            key = str(eco or "").strip().lower()
            mapping = {
                "yesvascript": "node",
                "typescript": "node",
                "frontend": "node",
                "node/browser": "node",
                "pip": "python",
                "pyproject": "python",
                "conda": "python",
                "scientific_python": "python",
                "android": "gradle",
                "dart": "flutter",
                "pub": "flutter",
                "cmake": "native",
                "cpp": "native",
                "c": "native",
            }
            key = mapping.get(key, key)
            if key in {"node", "gradle", "python", "flutter", "dotnet", "go", "rust", "yesva", "native", "docker"}:
                ecosystems.setdefault(key, {"detected": True, "sources": []})
                ecosystems[key].setdefault("sources", []).append(source)
        text_parts = [str(config.get(k) or "") for k in ("label", "category", "dependencies", "path_type", "build_target")]
        text_parts.extend(str(x) for x in config.get("timeline", []) if isinstance(x, (str, int, float)))
        text = " ".join(text_parts).lower()
        keyword_map = {
            "node": ("node", "npm", "pnpm", "yarn", "vite", "vue", "react", "next", "frontend", "package.json"),
            "python": ("python", "pyproject", "pip", "conda", "fastapi", "flask", "dyesngo", "requirements.txt", "pytest"),
            "gradle": ("gradle", "android", "kotlin", "gradlew"),
            "flutter": ("flutter", "dart", "pubspec"),
            "dotnet": ("dotnet", ".net", "csproj", "sln"),
            "go": ("golang", "go.mod"),
            "rust": ("rust", "cargo"),
            "yesva": ("yesva", "maven", "pom.xml"),
            "native": ("cmake", "c++", "cpp", "native"),
            "docker": ("docker", "dockerfile", "compose"),
        }
        for eco, needles in keyword_map.items():
            if any(needle in text for needle in needles):
                add(eco, "stack_text")
        try:
            for row in self._effective_dependency_rows(config):
                add(str(row.get("ecosystem") or ""), "dependency_row")
                manifest = str(row.get("manifest") or "").lower()
                if "package.json" in manifest:
                    add("node", "dependency_manifest")
                if any(name in manifest for name in ("pyproject.toml", "requirements", "environment.yml", "pipfile")):
                    add("python", "dependency_manifest")
                if "gradle" in manifest:
                    add("gradle", "dependency_manifest")
                if "pubspec" in manifest:
                    add("flutter", "dependency_manifest")
        except Exception:
            pass
        # Preserve already detected markers; stack switching should refresh them.
        for eco, data in (getattr(self, "_create_ecosystem_runtime_hints", {}) or {}).items():
            if isinstance(data, dict) and data.get("detected"):
                add(eco, "project_marker")
        return {"reason": reason, "ecosystems": ecosystems}

    def _schedule_stack_required_ecosystem_probes(self, config: dict | None = None, reason: str = "stack_changed") -> None:
        payload = self._ecosystem_probe_payload_from_config(config, reason)
        try:
            self._schedule_create_ecosystem_runtime_probes(payload, reason=reason)
        except Exception as exc:
            self._append_create_history_record("ecosystem_runtime_probe_schedule_failed", {"reason": reason, "error": str(exc)})

    def _resolve_runtime_selection_path(self, ecosystem: str, selected: str) -> Path:
        """Accept both files and folders for runtime Browse controls.

        For Docker the stored value is a Dockerfile/Compose file, never a docker
        executable path. If the user selects a folder, pick the first known build
        file in that folder.
        """
        eco = str(ecosystem or "").strip().lower()
        path = Path(os.path.expandvars(str(selected or ""))).expanduser()
        if eco == "docker" and path.is_dir():
            for name in ("Dockerfile", "dockerfile", "docker-compose.yml", "docker-compose.yaml", "compose.yml", "compose.yaml"):
                candidate = path / name
                if candidate.exists() and candidate.is_file():
                    return candidate
        return path

    def _browse_create_runtime_path(self, ecosystem: str) -> None:
        eco = str(ecosystem or "").strip().lower()
        var = self._runtime_path_var_for_ecosystem(eco)
        if var is None:
            return
        current = str(var.get() or "").strip()
        initial = Path(current).parent if current and Path(current).suffix else (Path(current) if current else self._active_project_tree_base())
        title = "Choose Dockerfile / Compose file" if eco == "docker" else f"Choose {eco} runtime executable or file"
        selected = filedialog.askopenfilename(title=title, initialdir=str(initial))
        if not selected:
            folder_title = "Choose folder containing Dockerfile / Compose" if eco == "docker" else f"Choose {eco} runtime folder"
            selected_dir = filedialog.askdirectory(title=folder_title, initialdir=str(initial))
            selected = selected_dir or ""
        if selected:
            resolved = self._resolve_runtime_selection_path(eco, selected)
            var.set(str(resolved))
            self._append_create_history_record("runtime_path_selected", {"ecosystem": eco, "path": str(resolved), "selected": selected})
            self._schedule_create_ecosystem_runtime_probes(reason=f"{eco}_path_selected")
            self._schedule_create_preview_refresh()

    def _runtime_marker_catalog(self) -> dict[str, set[str]]:
        return {
            "node": {".nvmrc", ".node-version", "package.json", "pnpm-lock.yaml", "yarn.lock", "package-lock.json"},
            "gradle": {"settings.gradle", "settings.gradle.kts", "build.gradle", "build.gradle.kts", "gradlew", "gradlew.bat", "gradle-wrapper.properties"},
            "python": {".python-version", "pyproject.toml", "requirements.txt", "requirements-dev.txt", "setup.py", "setup.cfg", "Pipfile", "poetry.lock", "runtime.txt", "environment.yml", "environment.yaml", "conda.yml", "tox.ini", "pytest.ini"},
            "flutter": {"pubspec.yaml", "pubspec.lock", ".metadata"},
            "dotnet": {"global.json", ".csproj", ".fsproj", ".vbproj", ".sln"},
            "rust": {"Cargo.toml", "Cargo.lock", "rust-toolchain", "rust-toolchain.toml"},
            "go": {"go.mod", "go.sum"},
            "yesva": {"pom.xml", "mvnw", "mvnw.cmd", ".yesva-version"},
            "native": {"CMakeLists.txt", "Makefile", "configure.ac", "meson.build"},
            "docker": {"Dockerfile", "docker-compose.yml", "docker-compose.yaml", "compose.yml", "compose.yaml", ".devcontainer.json"},
        }

    def _runtime_marker_bucket_for_name(self, name: str) -> list[str]:
        lower = str(name or "").lower()
        buckets = []
        for ecosystem, names in self._runtime_marker_catalog().items():
            if lower in {item.lower() for item in names}:
                buckets.append(ecosystem)
        if lower.endswith((".csproj", ".fsproj", ".vbproj", ".sln")):
            buckets.append("dotnet")
        if lower == "dockerfile" or lower.endswith(".dockerfile"):
            buckets.append("docker")
        return sorted(set(buckets))

    def _runtime_marker_parent_dir(self, rel: object) -> str:
        value = str(rel or "").replace("\\", "/").strip("/")
        if "/" not in value:
            return "."
        return value.rsplit("/", 1)[0] or "."

    def _looks_like_gradle_command(self, command: str) -> bool:
        start = str(command or "").strip().split(" ", 1)[0].lower().strip('"')
        return start in {"gradle", "gradlew", "gradlew.bat", "./gradlew"} or " gradle " in f" {str(command).lower()} "

    def _looks_like_node_command(self, command: str) -> bool:
        start = str(command or "").strip().split(" ", 1)[0].lower().strip('"')
        return start in {"npm", "npx", "pnpm", "yarn", "node"} or " npm " in f" {str(command).lower()} "


    def _runtime_marker_rel_allowed(self, rel: object, max_dirs: int = 2) -> bool:
        """Return True for bounded runtime marker paths.

        Depth contract: root marker files, first-level folders such as
        frontend/package.json or backend/build.gradle, and second-level folders
        such as apps/web/package.json are allowed. Gradle wrapper metadata is a
        known nested marker and is allowed one structural level deeper because
        its canonical path is gradle/wrapper/gradle-wrapper.properties.
        """
        value = str(rel or "").replace("\\", "/").strip("/")
        if not value:
            return False
        parts = [part for part in value.split("/") if part]
        lowered_parts = [part.lower() for part in parts]
        blocked = {".git", "node_modules", ".venv", "venv", "dist", "build", ".next", "coverage", "__pycache__"}
        if any(part in blocked for part in lowered_parts[:-1]):
            return False
        if len(parts) <= max_dirs + 1:
            return True
        if lowered_parts[-3:] == ["gradle", "wrapper", "gradle-wrapper.properties"] and len(parts) <= max_dirs + 3:
            return True
        return False

    def _runtime_marker_scope_paths(self, scope: dict | None = None, max_dirs: int = 2) -> dict[str, list[str]]:
        """Return bounded ecosystem marker paths from the already loaded scope."""
        active_scope = scope if isinstance(scope, dict) else (self._create_project_scope_snapshot if isinstance(getattr(self, "_create_project_scope_snapshot", None), dict) else {})
        file_refs = active_scope.get("file_references") if isinstance(active_scope, dict) else []
        markers: dict[str, set[str]] = {key: set() for key in self._runtime_marker_catalog()}
        for ref in file_refs or []:
            if not isinstance(ref, dict):
                continue
            rel = str(ref.get("path") or ref.get("id") or "").replace("\\", "/").strip("/")
            if not rel or not self._runtime_marker_rel_allowed(rel, max_dirs=max_dirs):
                continue
            name = rel.rsplit("/", 1)[-1]
            for bucket in self._runtime_marker_bucket_for_name(name):
                markers.setdefault(bucket, set()).add(rel)
        return {key: sorted(value) for key, value in markers.items()}

    def _bounded_runtime_marker_paths_from_root(self, root: Path | None = None, max_dirs: int = 2) -> dict[str, list[str]]:
        """Small fallback marker lookup for Create roots across ecosystems."""
        try:
            base = Path(root or self._create_terminal_work_dir()).resolve()
        except Exception:
            return {key: [] for key in self._runtime_marker_catalog()}
        if not base.exists() or not base.is_dir():
            return {key: [] for key in self._runtime_marker_catalog()}
        blocked = {".git", "node_modules", ".venv", "venv", "dist", "build", ".next", "coverage", "__pycache__", ".pytest_cache", ".gradle"}
        markers: dict[str, set[str]] = {key: set() for key in self._runtime_marker_catalog()}
        dirs: list[Path] = [base]
        frontier = [base]
        for _depth in range(max_dirs):
            next_frontier: list[Path] = []
            for current in frontier:
                try:
                    children = list(current.iterdir())
                except Exception:
                    continue
                for child in children:
                    if not child.is_dir():
                        continue
                    if child.name.lower() in blocked:
                        continue
                    dirs.append(child)
                    next_frontier.append(child)
            frontier = next_frontier
        for directory in dirs:
            try:
                rel_dir = directory.relative_to(base)
            except Exception:
                rel_dir = Path(".")
            for child in (directory.iterdir() if directory.exists() else []):
                try:
                    if not child.exists() or child.is_dir() and child.name.lower() not in {"gradle"}:
                        continue
                    rel = str((rel_dir / child.name) if str(rel_dir) != "." else Path(child.name)).replace("\\", "/")
                    if not self._runtime_marker_rel_allowed(rel, max_dirs=max_dirs):
                        continue
                    for bucket in self._runtime_marker_bucket_for_name(child.name):
                        markers.setdefault(bucket, set()).add(rel)
                except Exception:
                    continue
            props = directory / "gradle" / "wrapper" / "gradle-wrapper.properties"
            if props.is_file():
                rel = str((rel_dir / "gradle" / "wrapper" / "gradle-wrapper.properties") if str(rel_dir) != "." else Path("gradle/wrapper/gradle-wrapper.properties")).replace("\\", "/")
                markers.setdefault("gradle", set()).add(rel)
        return {key: sorted(value) for key, value in markers.items()}

    def _create_scope_contains_node_runtime(self, scope: dict | None = None) -> bool:
        markers = self._runtime_marker_scope_paths(scope, max_dirs=2)
        if markers.get("node"):
            return True
        try:
            root = self._create_temp_root() if self._create_source_clone_ready() else self._create_project_source_base
        except Exception:
            root = None
        return bool(self._bounded_runtime_marker_paths_from_root(Path(root), max_dirs=2).get("node")) if root else False

    def _create_scope_contains_gradle_runtime(self, scope: dict | None = None) -> bool:
        markers = self._runtime_marker_scope_paths(scope, max_dirs=2)
        if markers.get("gradle"):
            return True
        try:
            root = self._create_temp_root() if self._create_source_clone_ready() else self._create_project_source_base
        except Exception:
            root = None
        return bool(self._bounded_runtime_marker_paths_from_root(Path(root), max_dirs=2).get("gradle")) if root else False

    def _stack_contains_ecosystem_runtime(self, config: dict | None = None, ecosystems: set[str] | None = None) -> bool:
        config = config or self._current_create_config()
        wanted = {str(item).lower() for item in (ecosystems or set())}
        text_parts = [
            str(config.get("label") or ""),
            str(config.get("category") or ""),
            str(config.get("build_target") or ""),
            " ".join(map(str, config.get("file_types", []) or [])),
            "\n".join(map(str, config.get("tree", []) or [])),
            str(config.get("dependencies") or ""),
        ]
        for entry in self._dependency_abstraction_layer(config):
            ecosystem = str(entry.get("ecosystem") or "").lower()
            if ecosystem in wanted:
                return True
            text_parts.extend([
                ecosystem,
                " ".join(map(str, entry.get("manifest_files", []) or [])),
                " ".join(map(str, entry.get("dependencies", []) or [])),
            ])
        text = "\n".join(text_parts).lower()
        marker_by_ecosystem = {
            "python": {"python", "pyproject.toml", "requirements.txt", "pip", "conda", "pytest", "fastapi", "flask"},
            "flutter": {"flutter", "dart", "pubspec.yaml"},
            "dotnet": {"dotnet", ".net", "csproj", "sln"},
            "go": {"go.mod", "golang"},
            "rust": {"cargo.toml", "rust"},
            "yesva": {"yesva", "maven", "pom.xml"},
            "native": {"cmake", "cmakelists.txt", "cpp", "c++", "native"},
            "docker": {"docker", "dockerfile", "compose"},
        }
        aliases = {
            "pip": "python", "pyproject": "python", "conda": "python", "scientific_python": "python",
            "dart": "flutter", "pub": "flutter", "maven": "yesva", "cmake": "native", "cpp": "native", "c": "native", "ops": "docker",
        }
        for item in wanted:
            key = aliases.get(item, item)
            if any(marker in text for marker in marker_by_ecosystem.get(key, {key})):
                return True
            if (getattr(self, "_create_ecosystem_runtime_hints", {}) or {}).get(key, {}).get("detected"):
                return True
        return False

    def _stack_contains_node_runtime(self, config: dict | None = None) -> bool:
        """Return True when the selected Create stack actually contains Node work.

        This is used on stack/category changes. NVM probing should only run for
        Node-capable stacks; Python, Unity, docs, native, etc. must keep the
        Create Node version field at None.
        """
        config = config or self._current_create_config()
        text_parts = [
            str(config.get("label") or ""),
            str(config.get("category") or ""),
            str(config.get("build_target") or ""),
            " ".join(map(str, config.get("file_types", []) or [])),
            "\n".join(map(str, config.get("tree", []) or [])),
            str(config.get("dependencies") or ""),
        ]
        for entry in self._dependency_abstraction_layer(config):
            text_parts.extend([
                str(entry.get("ecosystem") or ""),
                " ".join(map(str, entry.get("manifest_files", []) or [])),
                " ".join(map(str, entry.get("dependencies", []) or [])),
            ])
        text = "\n".join(text_parts).lower()
        node_markers = {
            "package.json", "node", "npm", "npx", "pnpm", "yarn",
            "yesvascript", "typescript", "frontend", "vite", "vue", "react",
            "next", "nuxt", "svelte", "webgl", "three", "eslint", "vitest",
        }
        return any(marker in text for marker in node_markers) or self._create_scope_contains_node_runtime()

    def _stack_contains_gradle_runtime(self, config: dict | None = None) -> bool:
        config = config or self._current_create_config()
        text_parts = [
            str(config.get("label") or ""),
            str(config.get("category") or ""),
            str(config.get("build_target") or ""),
            " ".join(map(str, config.get("file_types", []) or [])),
            "\n".join(map(str, config.get("tree", []) or [])),
            str(config.get("dependencies") or ""),
        ]
        for entry in self._dependency_abstraction_layer(config):
            text_parts.extend([
                str(entry.get("ecosystem") or ""),
                " ".join(map(str, entry.get("manifest_files", []) or [])),
                " ".join(map(str, entry.get("dependencies", []) or [])),
            ])
        text = "\n".join(text_parts).lower()
        return any(marker in text for marker in {"gradle", "android", "kotlin", "build.gradle", "settings.gradle", "gradlew"}) or self._create_scope_contains_gradle_runtime()

    def _parse_nvm_version_output(self, output: object) -> str:
        """Normalize NVM output into a Node/NVM runtime version.

        Important Windows detail: `nvm version` returns the version of the NVM
        tool itself, not the selected Node runtime. Therefore this parser only
        accepts modern Node-looking versions and prefers active/starred entries
        from `nvm current` / `nvm list` output.
        """
        text = str(output or "").strip()
        if not text:
            return ""
        lowered = text.lower()
        if any(bad in lowered for bad in ["not found", "not recognized", "not installed", "no current", "none", "system"]):
            return ""
        # Prefer the active line from nvm-windows list output:
        #   * 20.11.1 (Currently using 64-bit executable)
        #     18.20.4
        active_patterns = [
            r"(?im)^\s*\*\s*v?((?:1[02468]|2[02468]|[3-9][0-9])(?:\.\d+){0,2})(?![\d.])",
            r"(?im)^\s*v?((?:1[02468]|2[02468]|[3-9][0-9])(?:\.\d+){0,2})(?![\d.]).*currently using",
            r"(?im)^\s*current(?:ly)?\s*[:=]?\s*v?((?:1[02468]|2[02468]|[3-9][0-9])(?:\.\d+){0,2})(?![\d.])",
        ]
        for pattern in active_patterns:
            match = re.search(pattern, text)
            if match:
                return match.group(1).lstrip("v")
        if "lts/*" in lowered:
            return "lts/*"
        if re.search(r"(?<![a-z])node(?![a-z])", lowered):
            return "node"
        # Fallback: pick the first plausible installed Node version. Do not parse
        # single-digit versions such as nvm-windows 1.1.12.
        match = re.search(r"(?<![\d.])v?((?:1[02468]|2[02468]|[3-9][0-9])(?:\.\d+){0,2})(?![\d.])", text, re.IGNORECASE)
        return match.group(1).lstrip("v") if match else ""

    def _windows_nvm_roots(self) -> list[Path]:
        """Known fast roots for Nvm for Windows.

        When the user selected an NVM/Node path, return only that path. APPDATA,
        NVM_ROOT and NVM_HOME are fallback candidates, not competing defaults.
        This keeps a custom runtime path stable across stack changes.
        """
        roots: list[Path] = []
        selected = self._selected_nvm_root_path_text()
        if selected:
            raw_values = [selected]
        else:
            appdata = os.environ.get("APPDATA")
            localappdata = os.environ.get("LOCALAPPDATA")
            userprofile = os.environ.get("USERPROFILE")
            home = Path.home()
            raw_values = [
                os.path.join(appdata, "nvm") if appdata else None,
                os.path.expandvars(r"%APPDATA%\nvm"),
                str(home / "AppData" / "Roaming" / "nvm"),
                os.path.join(userprofile, "AppData", "Roaming", "nvm") if userprofile else None,
                os.environ.get("NVM_ROOT"),
                os.environ.get("NVM_HOME"),
                os.path.join(localappdata, "nvm") if localappdata else None,
                os.path.expandvars(r"%LOCALAPPDATA%\nvm"),
                str(home / "AppData" / "Local" / "nvm"),
                os.path.join(os.environ.get("ProgramFiles", ""), "nvm") if os.environ.get("ProgramFiles") else None,
                os.path.join(os.environ.get("ProgramFiles(x86)", ""), "nvm") if os.environ.get("ProgramFiles(x86)") else None,
            ]
        seen: set[str] = set()
        for raw in raw_values:
            if not raw:
                continue
            try:
                path = Path(os.path.expandvars(str(raw))).expanduser()
            except Exception:
                continue
            # Ignore unresolved %APPDATA% placeholders on non-Windows/test hosts.
            if "%" in str(path):
                continue
            key = str(path).lower()
            if key not in seen:
                seen.add(key)
                roots.append(path)
        return roots

    def _is_windows_nvm_home(self, root: Path) -> bool:
        """Return True only for real Nvm for Windows roots, not Node symlinks."""
        try:
            root = Path(root)
            if (root / "nvm.exe").exists() or (root / "settings.txt").exists():
                return True
            return bool(self._installed_windows_nvm_versions(root))
        except Exception:
            return False

    def _windows_nvm_candidates(self) -> list[str]:
        """Return fast NVM command/path candidates for Windows UI subprocesses.

        Prefer explicit Nvm for Windows locations such as APPDATA/nvm/nvm.exe.
        Avoid broad `where nvm`/filesystem scans during stack changes.
        """
        candidates: list[str] = []
        for base in self._windows_nvm_roots():
            for name in ("nvm.exe", "nvm.cmd", "nvm.bat"):
                path = Path(base) / name
                if path.exists():
                    candidates.append(str(path))
        found = shutil.which("nvm")
        if found:
            candidates.append(found)
        # Plain command last and only as a timed fallback.
        candidates.append("nvm")
        result: list[str] = []
        seen: set[str] = set()
        for item in candidates:
            key = item.lower()
            if key not in seen:
                seen.add(key)
                result.append(item)
        return result

    def _read_windows_nvm_settings(self) -> dict[str, str]:
        """Read nvm-windows settings.txt from known roots without spawning a process."""
        for root in self._windows_nvm_roots():
            path = Path(root) / "settings.txt"
            if not path.exists():
                continue
            settings: dict[str, str] = {}
            try:
                for line in path.read_text(encoding="utf-8", errors="ignore").splitlines():
                    if ":" not in line:
                        continue
                    key, value = line.split(":", 1)
                    key = key.strip().lower()
                    value = value.strip()
                    if key and value:
                        settings[key] = value
                if settings:
                    # Preserve the folder where settings.txt was actually read.
                    # The file's own `path:` value is the Node symlink and must
                    # never be treated as the NVM home/version store.
                    settings["nvm_home"] = str(root)
                    settings["settings_file"] = str(path)
                    settings.setdefault("root", str(root))
                    return settings
            except Exception:
                continue
        return {}

    def _installed_windows_nvm_versions(self, root: Path) -> list[str]:
        """Return installed Node versions from an nvm-windows root folder."""
        versions: list[str] = []
        try:
            for child in Path(root).iterdir():
                if not child.is_dir():
                    continue
                name = child.name.lstrip("v")
                version = self._parse_nvm_version_output(name)
                if version:
                    versions.append(version)
        except Exception:
            pass

        def version_key(value: str) -> tuple[int, int, int, str]:
            parts = [int(p) for p in re.findall(r"\d+", value)[:3]]
            while len(parts) < 3:
                parts.append(0)
            return (parts[0], parts[1], parts[2], value)

        return sorted(set(versions), key=version_key, reverse=True)

    def _probe_windows_nvm_from_files(self) -> str:
        """Fast file-based nvm-windows detection before subprocess probing.

        If the NVM Path field is set, probe only that path. APPDATA/Roaming is
        allowed as fallback only while the field is empty.
        """
        selected_root = self._selected_nvm_root_path()
        if selected_root:
            direct_node = selected_root / "node.exe"
            if direct_node.exists():
                try:
                    proc = _run_subprocess_hidden([str(direct_node), "-v"], capture_output=True, text=True, timeout=0.7)
                    version = self._parse_nvm_version_output((proc.stdout or "") + "\n" + (proc.stderr or ""))
                    if version:
                        return version
                except Exception:
                    pass
            versions = self._installed_windows_nvm_versions(selected_root)
            if versions:
                return versions[0]
            return ""

        settings = self._read_windows_nvm_settings()
        roots: list[Path] = []
        if settings.get("nvm_home"):
            roots.append(Path(settings["nvm_home"]))
        if settings.get("root") and self._is_windows_nvm_home(Path(settings["root"])):
            roots.append(Path(settings["root"]))
        roots.extend(self._windows_nvm_roots())

        # If the active nvm symlink path contains node.exe, its node -v is the
        # most faithful current version for nvm-windows.
        symlink_values = [settings.get("path"), os.environ.get("NVM_SYMLINK")]
        for raw in symlink_values:
            if not raw:
                continue
            node_exe = Path(os.path.expandvars(str(raw))).expanduser() / "node.exe"
            try:
                if node_exe.exists():
                    proc = _run_subprocess_hidden([str(node_exe), "-v"], capture_output=True, text=True, timeout=0.7)
                    version = self._parse_nvm_version_output((proc.stdout or "") + "\n" + (proc.stderr or ""))
                    if version:
                        return version
            except Exception:
                continue

        seen: set[str] = set()
        for root in roots:
            try:
                key = str(root).lower()
                if key in seen:
                    continue
                seen.add(key)
                versions = self._installed_windows_nvm_versions(root)
                if versions:
                    return versions[0]
            except Exception:
                continue
        return ""

    def _run_windows_nvm(self, nvm_command: str, args: list[str], timeout: float = 0.8) -> tuple[int, str]:
        """Deprecated Windows NVM subprocess probe.

        Nvm for Windows can print "should be run from a terminal such as CMD or
        PowerShell" when started from a GUI/piped subprocess. Create therefore
        does not call nvm.exe during stack-change probing anymore. Runtime
        selection is handled inside the generated terminal script by putting the
        selected NVM version folder at the front of PATH.
        """
        return 1, "windows nvm subprocess probing disabled"

    def _probe_current_nvm_version(self) -> str:
        """Fast, bounded NVM probe used by the async stack-change worker."""
        try:
            if platform.system().lower().startswith("win"):
                # File-based only. Do not spawn nvm.exe from the GUI thread or a
                # worker subprocess; Nvm for Windows expects a real console.
                return self._probe_windows_nvm_from_files()
            script = (
                'if command -v nvm >/dev/null 2>&1; then nvm current; '
                'elif [ -s "${NVM_DIR:-$HOME/.nvm}/nvm.sh" ]; then . "${NVM_DIR:-$HOME/.nvm}/nvm.sh" && nvm current; '
                'else exit 127; fi'
            )
            proc = _run_subprocess_hidden(["bash", "-lc", script], capture_output=True, text=True, timeout=1.5)
            version = self._parse_nvm_version_output((proc.stdout or "") + "\n" + (proc.stderr or ""))
            if version:
                return version
            # Fallback: a short list probe when current did not return a runtime.
            script = (
                'if command -v nvm >/dev/null 2>&1; then nvm list; '
                'elif [ -s "${NVM_DIR:-$HOME/.nvm}/nvm.sh" ]; then . "${NVM_DIR:-$HOME/.nvm}/nvm.sh" && nvm list; '
                'else exit 127; fi'
            )
            proc = _run_subprocess_hidden(["bash", "-lc", script], capture_output=True, text=True, timeout=1.5)
            return self._parse_nvm_version_output((proc.stdout or "") + "\n" + (proc.stderr or ""))
        except Exception:
            return ""

    def _append_create_history_record(self, event: str, payload: dict | None = None) -> None:
        """Emit a small Create History Record (CHR) for runtime operations.

        CHR records are lightweight UI/export audit breadcrumbs. They are not a
        validation proof; they just make hidden operations such as NVM probes
        visible and consistent with the global progress bar.
        """
        payload = dict(payload or {})
        payload.setdefault("event", event)
        payload.setdefault("ts", time.strftime("%Y-%m-%dT%H:%M:%S"))
        try:
            self._append_create_terminal(f"[chr] {event}: {json.dumps(payload, ensure_ascii=False, sort_keys=True)}")
        except Exception:
            pass
        try:
            out = self._create_export_path() / "CREATE_HISTORY_RECORD.jsonl"
            out.parent.mkdir(parents=True, exist_ok=True)
            with out.open("a", encoding="utf-8") as fh:
                fh.write(json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n")
        except Exception:
            pass

    def _set_create_nvm_version(self, value: object, source: str = "manual") -> None:
        """Set the Create NVM field without recursively triggering runtime sync."""
        normalized = self._normalize_nvm_version(value) or "None"
        self._create_runtime_sync_lock = True
        try:
            if hasattr(self, "create_nvm_version") and self.create_nvm_version.get() != normalized:
                self.create_nvm_version.set(normalized)
        finally:
            self._create_runtime_sync_lock = False
        try:
            self._append_create_history_record("nvm_field_set", {"source": source, "node_version": normalized})
        except Exception:
            pass

    def _on_create_nvm_input_changed(self, *_args) -> None:
        """React to user NVM select/input changes with boilerplate minimum semantics."""
        if getattr(self, "_create_runtime_sync_lock", False):
            return
        config = self._create_stack_catalog().get(self.create_stack.get(), {})
        minimum = self._boilerplate_node_version(config)
        requested = self._normalize_nvm_version(self.create_nvm_version.get())
        value = self._resolve_min_runtime_version(requested, minimum, self._normalize_nvm_version)
        if value:
            if value != requested:
                self._set_create_nvm_version(value, "boilerplate_min")
            self._propagate_create_nvm_version_to_rows(value, override=True)
            self._append_create_history_record("nvm_manual_select", {"requested": requested or "None", "node_version": value, "minimum": minimum or None})
            self._set_progress((f"NVM selected: {value}" if not minimum or value != minimum else f"NVM min: {value}"), None, 0)
        else:
            self._set_create_nvm_version("None", "manual_none")
            self._propagate_create_nvm_version_to_rows("None", override=True)
            self._append_create_history_record("nvm_manual_select", {"node_version": "None"})
        self._schedule_create_preview_refresh()

    def _apply_nvm_probe_result(self, generation: int, version: str, status: str, duration_ms: int) -> None:
        if generation != getattr(self, "_create_nvm_probe_generation", 0):
            return
        self._create_nvm_probe_running = False
        config = self._create_stack_catalog().get(self.create_stack.get(), {})
        minimum = self._boilerplate_node_version(config)
        detected = self._normalize_nvm_version(version)
        value = self._resolve_min_runtime_version(detected, minimum, self._normalize_nvm_version) or "None"
        try:
            self._set_create_nvm_version(value, "detected_or_min" if minimum else "detected")
        except Exception:
            pass
        self._propagate_create_nvm_version_to_rows(value, override=True)
        label = f"NVM resolved: {value} (min {minimum})" if minimum and value != "None" else (f"NVM probe: {value}" if value != "None" else "NVM probe: None")
        if hasattr(self, "create_project_mode_status"):
            self.create_project_mode_status.set(label)
        self._append_create_history_record("nvm_probe_done", {"status": status, "node_version": value, "minimum": minimum or None, "detected": detected or None, "duration_ms": duration_ms})
        self._set_progress(label, 1, 1)

    def _apply_gradle_probe_result(self, generation: int, version: str, status: str, duration_ms: int) -> None:
        if generation != getattr(self, "_create_gradle_probe_generation", 0):
            return
        self._create_gradle_probe_running = False
        try:
            config = self._current_create_config()
        except Exception:
            config = {}
        minimum = self._boilerplate_gradle_version(config)
        detected = self._normalize_gradle_version(version)
        value = self._resolve_min_runtime_version(detected, minimum, self._normalize_gradle_version) or detected or minimum or "None"
        try:
            self.create_gradle_version.set(value)
        except Exception:
            pass
        label = f"Gradle resolved: {value} (min {minimum})" if minimum and value != "None" else (f"Gradle probe: {value}" if value != "None" else "Gradle probe: None")
        if hasattr(self, "create_project_mode_status"):
            self.create_project_mode_status.set(label)
        self._append_create_history_record("gradle_probe_done", {"status": status, "gradle_version": value, "minimum": minimum or None, "detected": detected or None, "duration_ms": duration_ms})
        self._set_progress(label, 1, 1)
        self._schedule_create_preview_refresh()

    def _propagate_create_nvm_version_to_rows(self, value: str, override: bool = False) -> None:
        normalized = self._normalize_nvm_version(value)
        if not normalized and not override:
            return
        row_value = normalized or "None"
        node_ecosystems = {"node", "yesvascript", "typescript", "frontend", "node/browser"}
        changed = False
        for row in getattr(self, "_create_dependency_rows", []):
            ecosystem = str(row.get("ecosystem") or "").lower()
            manifest = str(row.get("manifest") or "").lower()
            current = self._normalize_nvm_version(row.get("nvm_version") or "")
            if (ecosystem in node_ecosystems or manifest.endswith("package.json")) and (override or not current):
                row["nvm_version"] = row_value
                changed = True
        for row in getattr(self, "_create_compiler_rows", []):
            command = str(row.get("command") or "")
            current = self._normalize_nvm_version(row.get("nvm_version") or "")
            if self._looks_like_node_command(command) and (override or not current):
                row["nvm_version"] = row_value
                changed = True
        if changed:
            try:
                self._render_dependency_rows()
            except Exception:
                pass
            try:
                self._render_create_compiler_rows()
            except Exception:
                pass
            try:
                self._refresh_create_timeline_checklist(reset_checked=False)
            except Exception:
                pass

    def _boilerplate_node_version(self, config: dict | None = None) -> str:
        """Return the Node version explicitly declared by the selected boilerplate."""
        config = config or self._current_create_config()
        direct = self._normalize_nvm_version(config.get("node_version") or config.get("nvm_version") or "")
        if direct and direct.lower() not in {"auto", "current"}:
            return direct
        for entry in self._dependency_abstraction_layer(config):
            version = self._normalize_nvm_version(entry.get("node_version") or entry.get("nvm_version") or "")
            if version and version.lower() not in {"auto", "current"}:
                return version
        # Built-in fallback: a Node boilerplate owns a runtime version even when
        # older schema files did not declare one explicitly. This makes NVM setup
        # deterministic instead of waiting for a probe to guess the current version.
        if self._stack_contains_node_runtime(config):
            # Current Node boilerplates are authored against Node 24 by default.
            # This is a force version owned by the boilerplate, not an Auto probe.
            return "24"
        return ""

    def _boilerplate_gradle_version(self, config: dict | None = None) -> str:
        """Return the Gradle version explicitly declared by the selected boilerplate."""
        config = config or self._current_create_config()
        direct = self._normalize_gradle_version(config.get("gradle_version") or config.get("android_gradle_version") or "")
        if direct:
            return direct
        for entry in self._dependency_abstraction_layer(config):
            version = self._normalize_gradle_version(entry.get("gradle_version") or "")
            if version:
                return version
        if self._stack_contains_gradle_runtime(config):
            return "8.7"
        return ""

    def _create_runtime_probe_allowed_reason(self, reason: str = "") -> bool:
        """Return True only for real Start/Create project read events.

        Stack/category changes may apply boilerplate minimums, but they must not
        run NVM or Gradle probes. Probes belong to project ingest: Start-tab root
        read, Create-tab mount/scan, or cached Create-source re-read.
        """
        value = str(reason or "").strip().lower()
        allowed = {
            "start_path_changed",
            "working_tree_changed",
            "start_browse",
            "project_root_changed",
            "project_tree_scan",
            "initial",
            "forced",
            "manual_refresh",
            "tree_source_switch",
            "create_working_dir_scan",
            "create_source_cache_ready",
            "create_source_scope",
            "create_tab_mount",
            "create_tab_activated",
            "stack_changed",
            "create_stack_changed",
            "create_clone_ready",
        }
        return value in allowed or value.startswith("create_working_dir") or value.startswith("create_source") or value.startswith("project_tree")

    def _schedule_create_stack_runtime_check(self, reason: str = "create_scan", delay_ms: int = 80) -> None:
        """Run the existing runtime resolver only after real project reads.

        This intentionally does not introduce another crawler. It reuses the
        Stack runtime resolver after Start/Create scans have populated the scope.
        For stack/category UI changes it only applies boilerplate minimums.
        """
        if not self._create_runtime_probe_allowed_reason(reason):
            try:
                self._apply_boilerplate_runtime_versions(self._current_create_config(), reason)
            except Exception:
                pass
            return
        if getattr(self, "_create_stack_runtime_check_after", None):
            try:
                self.after_cancel(self._create_stack_runtime_check_after)
            except Exception:
                pass
            self._create_stack_runtime_check_after = None

        def callback() -> None:
            self._create_stack_runtime_check_after = None
            self._run_create_stack_runtime_check(reason)

        try:
            self._create_stack_runtime_check_after = self.after(max(int(delay_ms), 0), callback)
        except Exception:
            callback()

    def _run_create_stack_runtime_check(self, reason: str = "stack_changed", config: dict | None = None) -> None:
        """Reuse the Stack-change runtime resolver as the single Create runtime hook."""
        try:
            config = config or self._current_create_config()
        except Exception:
            config = {}
        self._apply_boilerplate_runtime_versions(config, reason)
        if not self._create_runtime_probe_allowed_reason(reason):
            self._append_create_history_record("runtime_probe_skipped_not_project_read", {"reason": reason})
            return
        try:
            self._sync_nvm_version_from_stack_switch(config, reason)
        except Exception as exc:
            self._append_create_history_record("nvm_probe_failed_to_start", {"reason": reason, "error": str(exc)})
        try:
            self._sync_gradle_version_from_stack_switch(config, reason)
        except Exception as exc:
            self._append_create_history_record("gradle_probe_failed_to_start", {"reason": reason, "error": str(exc)})
        try:
            self._schedule_stack_required_ecosystem_probes(config, reason)
        except Exception as exc:
            self._append_create_history_record("ecosystem_probe_failed_to_start", {"reason": reason, "error": str(exc)})

    def _apply_boilerplate_runtime_versions(self, config: dict | None = None, reason: str = "stack_changed") -> None:
        """Apply boilerplate-owned minimum runtime versions immediately."""
        config = config or self._current_create_config()
        node_min = self._boilerplate_node_version(config)
        if node_min:
            current = self._normalize_nvm_version(self.create_nvm_version.get())
            node_version = self._resolve_min_runtime_version(current, node_min, self._normalize_nvm_version)
            self._set_create_nvm_version(node_version, "boilerplate_min")
            self._propagate_create_nvm_version_to_rows(node_version, override=True)
            self._append_create_history_record("node_runtime_version_set", {"reason": reason, "node_version": node_version, "minimum": node_min, "source": "boilerplate_min"})
            self._set_progress(f"Node runtime: {node_version} (min {node_min})", 1, 1)
        elif not self._stack_contains_node_runtime(config):
            self._set_create_nvm_version("None", "non_node_stack")
            self._append_create_history_record("nvm_probe_skipped", {"reason": reason, "node_stack": False})

        gradle_min = self._boilerplate_gradle_version(config)
        if gradle_min:
            current_gradle = self._normalize_gradle_version(self.create_gradle_version.get())
            gradle_version = self._resolve_min_runtime_version(current_gradle, gradle_min, self._normalize_gradle_version)
            self.create_gradle_version.set(gradle_version)
            self._append_create_history_record("gradle_runtime_version_set", {"reason": reason, "gradle_version": gradle_version, "minimum": gradle_min, "source": "boilerplate_min"})
            self._set_progress(f"Gradle runtime: {gradle_version} (min {gradle_min})", 1, 1)
        elif not self._stack_contains_gradle_runtime(config):
            self.create_gradle_version.set("None")

    def _sync_nvm_version_from_stack_switch(self, config: dict | None = None, reason: str = "stack_changed") -> str:
        """Resolve NVM/Node version on stack change without blocking the UI.

        Boilerplate-declared Node versions win immediately. Background probing is
        only used when a Node stack has no declared version; Run waits for that
        probe before compiling commands.
        """
        config = config or self._current_create_config()
        minimum = self._boilerplate_node_version(config)
        if minimum:
            try:
                self._set_create_nvm_version(minimum, "boilerplate_min")
            except Exception:
                pass
            self._propagate_create_nvm_version_to_rows(minimum, override=True)
            self._append_create_history_record("nvm_min_set", {"reason": reason, "node_min_version": minimum, "source": "boilerplate"})
            self._set_progress(f"NVM min from boilerplate: {minimum}", 1, 1)
        if not (self._stack_contains_node_runtime(config) or self._runtime_hint_detected("node")):
            try:
                self._set_create_nvm_version("None", "non_node_stack")
            except Exception:
                pass
            self._append_create_history_record("nvm_probe_skipped", {"reason": reason, "node_stack": False, "project_node_marker": False})
            self._set_progress("NVM probe skipped: no Node stack/marker", 1, 1)
            return ""
        self._create_nvm_probe_generation += 1
        generation = self._create_nvm_probe_generation
        self._create_nvm_probe_running = True
        # Keep the boilerplate minimum visible while the async probe checks for
        # a higher active/installed version. Only stacks without a minimum show
        # None during probing.
        if not minimum:
            self._set_create_nvm_version("None", "probe_pending")
        self._append_create_history_record("nvm_probe_start", {"reason": reason, "stack": str(config.get("label") or self.create_stack.get()), "minimum": minimum or None})
        self._set_progress("NVM probe running…", None, 0)
        if hasattr(self, "create_project_mode_status"):
            self.create_project_mode_status.set("NVM probe: running")

        def worker() -> None:
            started = time.monotonic()
            status = "ok"
            version = ""
            try:
                version = self._probe_current_nvm_version()
                if not version:
                    status = "not_found"
            except Exception as exc:
                status = f"error:{exc}"
            duration_ms = int((time.monotonic() - started) * 1000)
            self._task_queue.put(("create_nvm_probe_result", generation, version, status, duration_ms))

        threading.Thread(target=worker, name="create-nvm-probe", daemon=True).start()
        return ""

    def _sync_gradle_version_from_stack_switch(self, config: dict | None = None, reason: str = "stack_changed") -> str:
        """Resolve Gradle using the existing bounded Gradle probe path."""
        config = config or self._current_create_config()
        minimum = self._boilerplate_gradle_version(config)
        if not (self._stack_contains_gradle_runtime(config) or self._runtime_hint_detected("gradle")):
            try:
                self.create_gradle_version.set("None")
            except Exception:
                pass
            self._append_create_history_record("gradle_probe_skipped", {"reason": reason, "gradle_stack": False, "project_gradle_marker": False})
            return ""
        if minimum:
            try:
                self.create_gradle_version.set(minimum)
            except Exception:
                pass
            self._append_create_history_record("gradle_min_set", {"reason": reason, "gradle_min_version": minimum, "source": "boilerplate"})
            self._set_progress(f"Gradle min from boilerplate: {minimum}", 1, 1)
        self._create_gradle_probe_generation += 1
        generation = self._create_gradle_probe_generation
        self._create_gradle_probe_running = True
        try:
            target = self._create_terminal_target_path()
        except Exception:
            target = Path.cwd()
        self._append_create_history_record("gradle_probe_start", {"reason": reason, "stack": str(config.get("label") or self.create_stack.get()), "minimum": minimum or None, "target": str(target)})
        self._set_progress("Gradle probe running…", None, 0)
        if hasattr(self, "create_project_mode_status"):
            self.create_project_mode_status.set("Gradle probe: running")

        def worker() -> None:
            started = time.monotonic()
            status = "ok"
            version = ""
            try:
                version = self._probe_current_gradle_version(Path(target))
                if not version:
                    status = "not_found"
            except Exception as exc:
                status = f"error:{exc}"
            duration_ms = int((time.monotonic() - started) * 1000)
            self._task_queue.put(("create_gradle_probe_result", generation, version, status, duration_ms))

        threading.Thread(target=worker, name="create-gradle-probe", daemon=True).start()
        return ""

    def _node_version_from_spec(self, spec: object) -> str:
        """Return a conservative nvm-compatible version hint from engines/.nvmrc text."""
        value = str(spec or "").strip()
        if not value:
            return ""
        lowered = value.lower().strip()
        if lowered in {"node", "stable", "current", "lts/*", "lts"}:
            return ""
        # Prefer the first major version mentioned in common semver ranges such
        # as >=18, ^20.0.0, 22.x or "20 || 22". Avoid returning the raw range
        # because nvm use does not accept every package.json engine expression.
        match = re.search(r"(?<!\d)(1[02468]|2[02468]|[3-9][0-9])(?:\.\d+)?(?:\.\d+)?", value)
        return match.group(1) if match else ""

    def _node_version_hint_for_target(self, target: object = "", explicit: object = "") -> str:
        """Resolve Node/NVM version for one Create target with minimum semantics.

        The selected boilerplate declares a minimum Node version. Higher user,
        detected, .nvmrc or package.json engine versions are accepted; lower or
        missing versions resolve to the boilerplate minimum. There is no Auto
        state.
        """
        config = self._current_create_config()
        minimum = self._boilerplate_node_version(config)
        explicit_value = self._normalize_nvm_version(explicit)
        if explicit_value:
            return self._resolve_min_runtime_version(explicit_value, minimum, self._normalize_nvm_version)
        try:
            root = self._dependency_target_root_path(str(target or self.create_build_target.get() or "generated"))
        except Exception:
            root = self._create_terminal_target_path()
        for name in (".nvmrc", ".node-version"):
            path = root / name
            try:
                hint = self._node_version_from_spec(path.read_text(encoding="utf-8").strip()) if path.exists() else ""
            except Exception:
                hint = ""
            if hint:
                return self._resolve_min_runtime_version(hint, minimum, self._normalize_nvm_version)
        pkg = root / "package.json"
        try:
            payload = json.loads(pkg.read_text(encoding="utf-8") or "{}") if pkg.exists() else {}
            engines = payload.get("engines") if isinstance(payload, dict) else {}
            hint = self._node_version_from_spec((engines or {}).get("node") if isinstance(engines, dict) else "")
            if hint:
                return self._resolve_min_runtime_version(hint, minimum, self._normalize_nvm_version)
        except Exception:
            pass
        return minimum or ""

    def _nvm_version_for_target(self, target: object = "") -> str:
        target_value = str(target or "").lower().strip()
        global_version = self._normalize_nvm_version(self.create_nvm_version.get() if hasattr(self, "create_nvm_version") else "")
        for row in getattr(self, "_create_dependency_rows", []):
            ecosystem = str(row.get("ecosystem") or "").lower().strip()
            if ecosystem not in {"node", "yesvascript", "typescript", "frontend", "node/browser"}:
                continue
            if target_value and str(row.get("target") or "").lower().strip() != target_value:
                continue
            row_version = self._node_version_hint_for_target(target_value, row.get("nvm_version") or "")
            if row_version:
                return row_version
        if global_version:
            return self._node_version_hint_for_target(target_value, global_version)
        return self._node_version_hint_for_target(target_value, "")

    def _preferred_windows_nvm_command(self) -> str:
        for candidate in self._windows_nvm_candidates():
            if not candidate or candidate == "nvm":
                continue
            try:
                if Path(candidate).exists() or shutil.which(candidate):
                    return candidate
            except Exception:
                continue
        return "nvm"

    def _windows_nvm_home_for_runtime(self) -> Path | None:
        """Return the preferred Nvm for Windows root for generated .cmd scripts."""
        settings = self._read_windows_nvm_settings()
        candidates: list[Path] = []
        if settings.get("nvm_home"):
            candidates.append(Path(settings["nvm_home"]))
        if settings.get("root"):
            candidates.append(Path(settings["root"]))
        candidates.extend(self._windows_nvm_roots())
        seen: set[str] = set()
        for root in candidates:
            try:
                key = str(root).lower()
                if key in seen:
                    continue
                seen.add(key)
                if self._is_windows_nvm_home(root):
                    return root
            except Exception:
                continue
        return None

    def _selected_windows_nvm_version_dir(self, version: object) -> Path | None:
        """Resolve a user-selected NVM root or concrete Node folder for Windows."""
        requested = self._normalize_nvm_version(version)
        selected = self._selected_nvm_root_path()
        if not selected or not requested:
            return None
        try:
            selected = selected.resolve()
        except Exception:
            pass
        candidates = [selected]
        for name in ("v" + requested, requested):
            candidates.append(selected / name)
        req_major = self._runtime_major(requested)
        try:
            for installed in self._installed_windows_nvm_versions(selected):
                if installed == requested or installed.startswith(requested + ".") or installed.startswith(requested) or (req_major is not None and (self._runtime_major(installed) or 0) >= req_major):
                    for name in ("v" + installed, installed):
                        candidates.append(selected / name)
        except Exception:
            pass
        for candidate in candidates:
            try:
                node_exe = candidate / "node.exe"
                if not node_exe.exists():
                    continue
                resolved = self._parse_nvm_version_output(candidate.name)
                if not resolved:
                    try:
                        proc = _run_subprocess_hidden([str(node_exe), "-v"], capture_output=True, text=True, timeout=0.7)
                        resolved = self._parse_nvm_version_output((proc.stdout or "") + "\n" + (proc.stderr or ""))
                    except Exception:
                        resolved = ""
                if not resolved:
                    return candidate
                if resolved == requested or resolved.startswith(requested + ".") or (req_major is not None and (self._runtime_major(resolved) or 0) >= req_major):
                    return candidate
            except Exception:
                continue
        return None

    def _windows_nvm_version_dir(self, version: object) -> Path | None:
        """Find an installed nvm-windows Node version directory.

        Do not invoke nvm.exe from Python/Tk. Nvm for Windows can reject GUI or
        piped subprocesses with "should be run from a terminal such as CMD or
        PowerShell". The Create terminal only needs a process-local runtime, so
        the generated .cmd script prepends the installed Node version directory
        to PATH instead of mutating the global NVM symlink.
        """
        requested = self._normalize_nvm_version(version)
        if not requested:
            return None
        selected_version_dir = self._selected_windows_nvm_version_dir(requested)
        if selected_version_dir:
            return selected_version_dir
        if self._has_user_selected_nvm_path():
            return None
        roots = self._windows_nvm_roots()
        home = self._windows_nvm_home_for_runtime()
        if home:
            roots.insert(0, home)
        seen_roots: set[str] = set()
        for root in roots:
            try:
                root_key = str(root).lower()
                if root_key in seen_roots:
                    continue
                seen_roots.add(root_key)
                versions = self._installed_windows_nvm_versions(root)
                if not versions:
                    continue
                chosen = ""
                lowered = requested.lower()
                if lowered in {"node", "current", "auto", "lts/*", "lts"}:
                    chosen = versions[0]
                else:
                    for installed in versions:
                        if installed == requested or installed.startswith(requested + ".") or installed.startswith(requested):
                            chosen = installed
                            break
                    if not chosen:
                        req_major = self._runtime_major(requested)
                        higher = [v for v in versions if req_major is not None and (self._runtime_major(v) or 0) >= req_major]
                        if higher:
                            chosen = higher[0]
                if not chosen:
                    continue
                for name in ("v" + chosen, chosen):
                    candidate = root / name
                    if (candidate / "node.exe").exists():
                        return candidate
            except Exception:
                continue
        return None

    def _windows_nvm_env_prefix(self, version: object, target: object = "") -> str:
        nvm_version = self._node_version_hint_for_target(target, version)
        if not nvm_version:
            return ""
        version_dir = self._windows_nvm_version_dir(nvm_version)
        if version_dir:
            path = str(version_dir)
            resolved = self._parse_nvm_version_output(version_dir.name) or nvm_version
            # Keep PATH mutation on its own physical .cmd line. If `%PATH%` is
            # expanded inside a chained `set ... && npm ...` line, cmd.exe can
            # hit "Die eingegebene Zeile ist zu lang" on developer machines with
            # very large PATH values. A standalone SET line avoids that.
            return "\n".join([
                f'set "PATH={path};%PATH%"',
                f'echo [create] node runtime via NVM PATH: {resolved} ({path})',
            ])
        selected = self._selected_nvm_root_path()
        if selected:
            return (
                f'echo [create-warn] selected NVM/Node path {selected} does not contain Node {nvm_version}; '
                f'using current node instead of falling back to APPDATA'
            )
        home = self._windows_nvm_home_for_runtime()
        if home:
            return (
                f'echo [create-warn] NVM for Windows root found at {home} but Node {nvm_version} is not installed; '
                f'install it with Nvm for Windows or choose an installed version'
            )
        return f'echo [create-warn] NVM not found; using current node instead of requested {nvm_version}'

    def _nvm_use_shell_prefix(self, version: object, target: object = "") -> str:
        nvm_version = self._node_version_hint_for_target(target, version)
        if not nvm_version:
            return ""
        if platform.system().lower().startswith("win"):
            return self._windows_nvm_env_prefix(nvm_version, target)
        safe = nvm_version.replace("'", "")
        setup = (
            "if command -v nvm >/dev/null 2>&1; then "
            "nvm use " + shlex.quote(nvm_version) + " || (nvm install " + shlex.quote(nvm_version) + " && nvm use " + shlex.quote(nvm_version) + ") || echo '[create-warn] nvm could not activate " + safe + "; using current node'; "
            'elif [ -s "${NVM_DIR:-$HOME/.nvm}/nvm.sh" ]; then '
            '. "${NVM_DIR:-$HOME/.nvm}/nvm.sh" && (nvm use ' + shlex.quote(nvm_version) + " || (nvm install " + shlex.quote(nvm_version) + " && nvm use " + shlex.quote(nvm_version) + ") || echo '[create-warn] nvm could not activate " + safe + "; using current node'); "
            "else echo '[create-warn] nvm not available; using current node'; fi"
        )
        return self._shell_join(["bash", "-lc", setup])

    def _with_nvm(self, command: str, version: object, target: object = "") -> str:
        nvm_version = self._node_version_hint_for_target(target, version)
        command = str(command or "").strip()
        if not command or not nvm_version:
            return command
        if platform.system().lower().startswith("win"):
            prefix = self._windows_nvm_env_prefix(nvm_version, target)
            return (prefix + "\n" + command) if prefix else command
        safe = nvm_version.replace("'", "")
        script = (
            "if command -v nvm >/dev/null 2>&1; then "
            "nvm use " + shlex.quote(nvm_version) + " || (nvm install " + shlex.quote(nvm_version) + " && nvm use " + shlex.quote(nvm_version) + ") || echo '[create-warn] nvm could not activate " + safe + "; using current node'; "
            'elif [ -s "${NVM_DIR:-$HOME/.nvm}/nvm.sh" ]; then '
            '. "${NVM_DIR:-$HOME/.nvm}/nvm.sh" && (nvm use ' + shlex.quote(nvm_version) + " || (nvm install " + shlex.quote(nvm_version) + " && nvm use " + shlex.quote(nvm_version) + ") || echo '[create-warn] nvm could not activate " + safe + "; using current node'); "
            "else echo '[create-warn] nvm not available; using current node'; fi; "
            + command
        )
        return self._shell_join(["bash", "-lc", script])

    def _python_script_command(self, stem: str, code: str) -> str:
        """Write Python code to a sidecar script and return a short command.

        Windows `cmd.exe` has a small command-line limit. Long generated
        payloads, especially dependency layer JSON, can otherwise be treated as
        an invalid executable and fail with messages such as "Das angegebene
        program cannot be executed.". Sidecar scripts keep timeline
        commands short and still run through the same terminal/loadingbar path.
        """
        export_dir = self._create_export_path()
        export_dir.mkdir(parents=True, exist_ok=True)
        safe_stem = re.sub(r"[^A-Za-z0-9_.-]+", "_", str(stem or "create_timeline_step")).strip("._") or "create_timeline_step"
        digest = hashlib.sha1(str(code or "").encode("utf-8", errors="replace")).hexdigest()[:12]
        script = export_dir / f"{safe_stem}_{digest}.py"
        script.write_text(str(code or "").rstrip() + "\n", encoding="utf-8")
        return self._shell_join([self._python_runtime_executable(self.create_build_target.get() if hasattr(self, "create_build_target") else ""), script])

    def _python_inline_command(self, code: str) -> str:
        # Windows cmd cannot safely carry multiline Python snippets or raw
        # backslash paths inside `python -c`. Encode the payload and exec it
        # inside Python so generated .cmd/.sh scripts stay one physical line.
        payload = base64.b64encode(str(code or "").encode("utf-8")).decode("ascii")
        runner = f"import base64; exec(base64.b64decode({payload!r}).decode('utf-8'))"
        command = self._shell_join([self._python_runtime_executable(self.create_build_target.get() if hasattr(self, "create_build_target") else ""), "-c", runner])
        # cmd.exe starts failing around 8191 characters. Keep a safety margin and
        # spill large payloads to sidecar scripts instead of hiding them in one
        # enormous command line inside create_timeline_run.cmd.
        if platform.system().lower().startswith("win") and len(command) > 6500:
            return self._python_script_command("create_timeline_step", str(code or ""))
        if len(command) > 30000:
            return self._python_script_command("create_timeline_step", str(code or ""))
        return command

    def _python_print_command(self, message: object) -> str:
        # Always use repr() for inline Python messages. Windows paths such as
        # C:\Users\... otherwise turn into invalid unicode escapes inside
        # python -c strings.
        return self._python_inline_command(f"print({str(message)!r})")

    def _parse_gradle_version_output(self, output: object) -> str:
        """Extract a Gradle version from `gradle -v` or wrapper metadata."""
        text = str(output or "").strip()
        if not text:
            return ""
        patterns = [
            r"(?im)^\s*Gradle\s+([0-9]+(?:\.[0-9]+){0,2})\b",
            r"gradle-([0-9]+(?:\.[0-9]+){0,2})-(?:bin|all)\.zip",
            r"distributionUrl=.*?gradle-([0-9]+(?:\.[0-9]+){0,2})-",
        ]
        for pattern in patterns:
            match = re.search(pattern, text)
            if match:
                return match.group(1)
        return ""

    def _gradle_wrapper_version_for_target_path(self, target: Path) -> str:
        """Read gradle/wrapper/gradle-wrapper.properties without invoking Gradle."""
        props = Path(target) / "gradle" / "wrapper" / "gradle-wrapper.properties"
        try:
            if props.exists():
                return self._parse_gradle_version_output(props.read_text(encoding="utf-8", errors="ignore"))
        except Exception:
            pass
        return ""

    def _probe_current_gradle_version(self, target: Path | None = None) -> str:
        """Fast Gradle detection: wrapper properties first, then bounded gradle -v."""
        target = Path(target or self._create_terminal_target_path())
        wrapper_version = self._gradle_wrapper_version_for_target_path(target)
        if wrapper_version:
            return wrapper_version
        try:
            gradle = shutil.which("gradle")
            if not gradle:
                return ""
            proc = _run_subprocess_hidden([gradle, "-v"], cwd=str(target), capture_output=True, text=True, timeout=2.0)
            return self._parse_gradle_version_output((proc.stdout or "") + "\n" + (proc.stderr or ""))
        except Exception:
            return ""

    def _gradle_version_for_target(self, target: object = "") -> str:
        value = self._normalize_gradle_version(self.create_gradle_version.get() if hasattr(self, "create_gradle_version") else "")
        return self._resolve_min_runtime_version(value, self._boilerplate_gradle_version(self._current_create_config()), self._normalize_gradle_version)

    def _gradle_build_optional_command(self, target_path: Path | None = None, gradle_version: object = None) -> str:
        target = Path(target_path or self._create_terminal_target_path())
        version = self._normalize_gradle_version(gradle_version or self._gradle_version_for_target(self.create_build_target.get()) or "")
        code = (
            "import re, shutil, subprocess, sys\n"
            "from pathlib import Path\n"
            f"root=Path({str(target)!r})\n"
            f"minimum={version!r}\n"
            "root.mkdir(parents=True, exist_ok=True)\n"
            "is_win=sys.platform.startswith('win')\n"
            "wrapper=root/('gradlew.bat' if is_win else 'gradlew')\n"
            "props=root/'gradle'/'wrapper'/'gradle-wrapper.properties'\n"
            "def parse(text):\n"
            "    m=re.search(r'gradle-([0-9]+(?:\\.[0-9]+){0,2})-(?:bin|all)\\.zip', text or '') or re.search(r'(?im)^\\s*Gradle\\s+([0-9]+(?:\\.[0-9]+){0,2})\\b', text or '')\n"
            "    return m.group(1) if m else ''\n"
            "def major(v):\n"
            "    m=re.search(r'\\d+', str(v or '')); return int(m.group(0)) if m else 0\n"
            "def ok(v): return (not minimum) or (major(v) >= major(minimum))\n"
            "def run(cmd): print('[create-gradle]', ' '.join(map(str, cmd)), 'cwd=', root); return subprocess.call([str(x) for x in cmd], cwd=str(root));\n"
            "wrapper_version=''\n"
            "if props.exists():\n"
            "    wrapper_version=parse(props.read_text(encoding='utf-8', errors='ignore'))\n"
            "    if wrapper_version: print('[create-gradle] wrapper version:', wrapper_version)\n"
            "if wrapper.exists() and ok(wrapper_version):\n"
            "    raise SystemExit(run([wrapper, 'build']))\n"
            "gradle=shutil.which('gradle')\n"
            "if not gradle:\n"
            "    if wrapper.exists():\n"
            "        print('[create-warn] Gradle CLI unavailable; running existing wrapper even though version may be below minimum:', minimum); raise SystemExit(run([wrapper, 'build']))\n"
            "    print('gradle not available; skipped optional gradle build:', root); raise SystemExit(0)\n"
            "detected=''\n"
            "try:\n"
            "    p=subprocess.run([gradle, '-v'], cwd=str(root), capture_output=True, text=True, timeout=5); detected=parse((p.stdout or '')+'\\n'+(p.stderr or ''))\n"
            "except Exception: detected=''\n"
            "if detected: print('[create-gradle] cli version:', detected)\n"
            "if minimum and not ok(wrapper_version):\n"
            "    status=run([gradle, 'wrapper', '--gradle-version', minimum])\n"
            "    if status != 0: raise SystemExit(status)\n"
            "    wrapper=root/('gradlew.bat' if is_win else 'gradlew')\n"
            "    if wrapper.exists(): raise SystemExit(run([wrapper, 'build']))\n"
            "if wrapper.exists(): raise SystemExit(run([wrapper, 'build']))\n"
            "raise SystemExit(run([gradle, 'build']))\n"
        )
        return self._python_inline_command(code)

    def _npm_script_optional_command(self, script: str, target_path: Path | None = None, nvm_version: object = None) -> str:
        target = Path(target_path or self._create_terminal_target_path())
        script_name = str(script or "").strip()
        code = (
            "import json, os, shutil, subprocess, sys; from pathlib import Path; "
            f"root=Path({str(target)!r}); script={script_name!r}; pkg=root/'package.json'; "
            "scripts={}; "
            "\ntry:\n"
            "    data=json.loads(pkg.read_text(encoding='utf-8')) if pkg.exists() else {}\n"
            "    scripts=data.get('scripts') or {}\n"
            "except Exception:\n"
            "    scripts={}\n"
            "\nif script not in scripts:\n"
            "    print(f'npm script missing; skipped: {script} -> {root}')\n"
            "    raise SystemExit(0)\n"
            "\ndef has_node_tests(root):\n"
            "    dirs=[root/'tests', root/'test', root/'__tests__', root/'src'/'__tests__']\n"
            "    for d in dirs:\n"
            "        if d.exists() and any(p.is_file() for p in d.rglob('*')): return True\n"
            "    patterns=['**/*.test.js','**/*.test.jsx','**/*.test.ts','**/*.test.tsx','**/*.spec.js','**/*.spec.jsx','**/*.spec.ts','**/*.spec.tsx','**/*.test.mjs','**/*.spec.mjs','**/*.test.cjs','**/*.spec.cjs','**/*.test.mts','**/*.spec.mts','**/*.test.cts','**/*.spec.cts']\n"
            "    for pattern in patterns:\n"
            "        for path in root.glob(pattern):\n"
            "            parts={p.lower() for p in path.parts}\n"
            "            if 'node_modules' in parts or '.git' in parts or 'dist' in parts or 'build' in parts: continue\n"
            "            if path.is_file(): return True\n"
            "    return False\n"
            "\ndef resolve_npm():\n"
            "    names=['npm.cmd','npm.exe','npm'] if sys.platform.startswith('win') else ['npm']\n"
            "    for name in names:\n"
            "        found=shutil.which(name)\n"
            "        if found: return found\n"
            "    for raw in os.environ.get('PATH','').split(os.pathsep):\n"
            "        if not raw: continue\n"
            "        base=Path(raw.strip(chr(34)))\n"
            "        for name in names:\n"
            "            candidate=base/name\n"
            "            if candidate.exists(): return str(candidate)\n"
            "    return ''\n"
            "\ndef has_vite_build_entry(root):\n"
            "    if (root/'index.html').is_file(): return True\n"
            "    for name in ['vite.config.js','vite.config.mjs','vite.config.ts','vite.config.mts','vite.config.cjs','vite.config.cts']:\n"
            "        cfg=root/name\n"
            "        if not cfg.is_file(): continue\n"
            "        try: text=cfg.read_text(encoding='utf-8', errors='ignore')\n"
            "        except Exception: text=''\n"
            "        if 'build' in text and ('lib' in text or 'rollupOptions' in text or 'input' in text): return True\n"
            "    return False\n"
            "\nscript_command=str(scripts.get(script) or '')\n"
            "\nif script.lower() == 'test' and not has_node_tests(root):\n"
            "    print(f'npm test skipped; no test/spec files in Project Tree: {root}')\n"
            "    raise SystemExit(0)\n"
            "\nif script.lower() in {'build','compile'} and 'vite' in script_command.lower() and 'build' in script_command.lower() and not has_vite_build_entry(root):\n"
            "    print(f'npm build skipped; vite entry index.html/config input missing in Project Tree: {root}')\n"
            "    raise SystemExit(0)\n"
            "\nnpm=resolve_npm()\n"
            "\nif not npm:\n"
            "    print(f'npm unavailable; skipped optional npm script: {script} -> {root}')\n"
            "    raise SystemExit(0)\n"
            "\ncmd=[npm, '--prefix', str(root), 'run', script]\n"
            "print('[create-npm]', ' '.join(cmd))\n"
            "\ntry:\n"
            "    raise SystemExit(subprocess.call(cmd, shell=False))\n"
            "except FileNotFoundError:\n"
            "    if sys.platform.startswith('win'):\n"
            "        raise SystemExit(subprocess.call('\"' + npm + '\" --prefix \"' + str(root) + '\" run ' + script, shell=True))\n"
            "    print(f'npm command could not be started; skipped optional npm script: {script} -> {root}')\n"
            "    raise SystemExit(0)\n"
        )
        return self._with_nvm(self._python_inline_command(code), nvm_version or self._nvm_version_for_target(self.create_build_target.get()), self.create_build_target.get())

    def _python_compileall_command(self, target_path: Path | None = None) -> str:
        target = Path(target_path or self._create_terminal_target_path())
        python_exe = self._python_runtime_executable(self.create_build_target.get())
        ignored = sorted(set(DEPENDENCY_STORAGE_DIR_NAMES))
        code = (
            "import os, py_compile\n"
            "from pathlib import Path\n"
            f"root=Path({str(target)!r})\n"
            f"ignored=set({ignored!r})\n"
            "if not root.exists():\n"
            "    print(f'compile skipped; target missing: {root}')\n"
            "    raise SystemExit(0)\n"
            "checked=0\n"
            "failed=[]\n"
            "for current, dirs, files in os.walk(root):\n"
            "    dirs[:] = [d for d in sorted(dirs) if d not in ignored]\n"
            "    for name in sorted(files):\n"
            "        if not name.endswith('.py'):\n"
            "            continue\n"
            "        path=Path(current)/name\n"
            "        checked += 1\n"
            "        try:\n"
            "            py_compile.compile(str(path), doraise=True)\n"
            "        except Exception as exc:\n"
            "            failed.append((path, exc))\n"
            "            print(f'[compile-error] {path}: {exc}')\n"
            "print(f'[create-python-compile] checked={checked} root={root}')\n"
            "if failed:\n"
            "    raise SystemExit(1)\n"
        )
        return self._python_inline_command(code)

    def _pytest_optional_command(self, target_path: Path | None = None) -> str:
        target = Path(target_path or self._create_terminal_target_path())
        python_exe = self._python_runtime_executable(self.create_build_target.get())
        code = (
            "import subprocess, sys; from pathlib import Path; "
            f"root=Path({str(target)!r}); py={python_exe!r}; "
            "tests=[root/'tests', root/'test']; "
            "has_tests=any(p.exists() for p in tests) or any(root.glob('test_*.py')) or any(root.glob('*_test.py')); "
            "\nif not has_tests:\n"
            "    print(f'pytest skipped; no tests found: {root}'); raise SystemExit(0)\n"
            "\nprobe=subprocess.run([py, '-c', 'import pytest'], cwd=str(root), capture_output=True, text=True)\n"
            "\nif probe.returncode != 0:\n"
            "    print('pytest skipped; pytest is not installed in selected Python runtime'); raise SystemExit(0)\n"
            "\nraise SystemExit(subprocess.call([py, '-m', 'pytest', str(root)]))\n"
        )
        return self._python_inline_command(code)

    def _flutter_test_optional_command(self, target_path: Path | None = None) -> str:
        target = Path(target_path or self._create_terminal_target_path())
        code = (
            "import shutil, subprocess; from pathlib import Path; "
            f"root=Path({str(target)!r}); pubspec=root/'pubspec.yaml'; "
            "\nif not pubspec.exists():\n"
            "    print(f'flutter test skipped; pubspec.yaml missing: {root}'); raise SystemExit(0)\n"
            "\nflutter=shutil.which('flutter')\n"
            "\nif not flutter:\n"
            "    print('flutter test skipped; Flutter SDK unavailable'); raise SystemExit(0)\n"
            "\nraise SystemExit(subprocess.call([flutter, 'test'], cwd=str(root)))\n"
        )
        return self._python_inline_command(code)

    def _cmake_build_optional_command(self, target_path: Path | None = None) -> str:
        target = Path(target_path or self._create_terminal_target_path())
        code = (
            "import shutil, subprocess; from pathlib import Path; "
            f"root=Path({str(target)!r}); cmakelists=root/'CMakeLists.txt'; build=root/'build'; "
            "\nif not cmakelists.exists():\n"
            "    print(f'cmake build skipped; CMakeLists.txt missing: {root}'); raise SystemExit(0)\n"
            "\ncmake=shutil.which('cmake')\n"
            "\nif not cmake:\n"
            "    print('cmake build skipped; cmake unavailable'); raise SystemExit(0)\n"
            "\nstatus=subprocess.call([cmake, '-S', str(root), '-B', str(build)])\n"
            "\nif status != 0: raise SystemExit(status)\n"
            "\nraise SystemExit(subprocess.call([cmake, '--build', str(build)]))\n"
        )
        return self._python_inline_command(code)

    def _create_terminal_work_dir(self) -> Path:
        """Return the isolated temp preview directory used as the live Create terminal cwd.

        This must be a cheap lookup. Re-materializing here creates preview loops
        because status labels, terminal auto-join and export refreshes all ask for
        the cwd repeatedly.
        """
        root = self._restore_completed_create_build_root_for_current_stack() or self._create_temp_root()
        if root.exists():
            return root
        # Keep Run/terminal cwd resolution cheap. A missing preview root is
        # created as an empty temp cwd; timeline tokens create/mount files after
        # the user confirms terminal execution. Never materialize a large tree
        # merely to answer "where should the terminal start?".
        root.mkdir(parents=True, exist_ok=True)
        return root

    def _create_target_relative_path(self) -> Path:
        raw = self.create_target_path.get().strip() or "."
        raw_path = Path(raw).expanduser()
        if raw_path.is_absolute():
            try:
                rel = raw_path.resolve().relative_to(self._create_working_dir())
                return Path(rel)
            except Exception:
                return Path(raw_path.name or ".")
        return Path(str(raw).replace("\\", "/").strip("/") or ".")

    def _create_terminal_target_path(self) -> Path:
        # Create tasks run against the active terminal workdir. After
        # Build.complete this must be the completed abstraction root, not a newly
        # computed preview-clone path.
        rel = self._create_target_relative_path()
        return self._create_materialized_path(self._create_terminal_work_dir(), rel).resolve()

    def _create_target_root_path_for_target(self, target_name: str) -> Path:
        target = str(target_name or "generated").lower().strip()
        role_for_target = {
            "wrapper": "wrapper_root",
            "backend": "backend_root",
            "frontend": "frontend_root",
            "assets": "asset",
            "asset": "asset",
            "generated": "generated",
            "custom": "generated",
        }.get(target, target)
        if hasattr(self, "create_preview_tree"):
            for row in self._create_preview_tree_model():
                if str(row.get("role") or "") == role_for_target and not row.get("ignored"):
                    rel = self._normalize_create_tree_rel(row.get("path") or ".")
                    root = self._create_terminal_work_dir()
                    return self._create_materialized_path(root, rel)
        return self._create_terminal_target_path()

    def _create_target_mkdir_command(self, target_name: str | None = None) -> str:
        target = self._create_target_root_path_for_target(target_name or self.create_build_target.get())
        code = f"from pathlib import Path; p=Path({str(target)!r}); p.mkdir(parents=True, exist_ok=True); print('created target:', p)"
        return self._python_inline_command(code)

    def _create_touch_file_command(self, filename: str, target_name: str | None = None) -> str:
        safe_name = filename.strip().strip("/").strip("\\") or "CREATE_TASK_OUTPUT.txt"
        target = self._create_target_root_path_for_target(target_name or self.create_build_target.get()) / safe_name
        content = self._default_create_file_content(safe_name, None)
        if target.suffix.lower() == ".json":
            code = (
                "import json; from pathlib import Path; "
                f"p=Path({str(target)!r}); p.parent.mkdir(parents=True, exist_ok=True); default={content!r}; "
                "text=p.read_text(encoding='utf-8').strip() if p.exists() else ''; "
                "json.loads(text) if text else p.write_text(default or '{}\\n', encoding='utf-8'); "
                "print('ensured file:', p)"
            )
        else:
            code = (
                "from pathlib import Path; "
                f"p=Path({str(target)!r}); p.parent.mkdir(parents=True, exist_ok=True); default={content!r}; "
                "p.write_text(default, encoding='utf-8') if default and (not p.exists() or not p.read_text(encoding='utf-8', errors='ignore').strip()) else p.touch(exist_ok=True); "
                "print('ensured file:', p)"
            )
        return self._python_inline_command(code)

    def _write_create_handoff_index_command(self) -> str:
        self._progress_callback("Create timeline: handoff index step compacted", None, 0)
        return self._python_print_command("handoff index step compacted; USER_PROMPT.txt is the handoff")

    def _write_create_project_mapping_command(self) -> str:
        """Skip the removed mapping sidecar during terminal timeline execution."""
        self._progress_callback("Create timeline: project mapping sidecar removed", None, 0)
        return self._python_print_command("project mapping sidecar removed; USER_PROMPT.txt carries the handoff")

    def _write_create_dependency_layer_command(self) -> str:
        self._progress_callback("Create timeline: dependency sidecar removed", None, 0)
        return self._python_print_command("dependency sidecar removed; install commands still run from timeline")

    def _write_project_tree_markdown_command(self) -> str:
        workdir = self._create_working_dir()
        output = self._create_export_path() / "PROJECT_TREE.md"
        ignore_names = {".git", "node_modules", "venv", ".venv", "dist", "build", "__pycache__"}
        code = (
            "from pathlib import Path; "
            f"root=Path({str(workdir)!r}); out=Path({str(output)!r}); "
            f"ignore={sorted(ignore_names)!r}; "
            "lines=['# Project Tree', '', f'Root: `{root}`', '']; "
            "paths=[]; "
            "\nfor p in sorted(root.rglob('*')):\n"
            "    rel=p.relative_to(root)\n"
            "    parts=set(rel.parts)\n"
            "    if parts & set(ignore):\n"
            "        continue\n"
            "    prefix='  '*(len(rel.parts)-1)\n"
            "    marker='/' if p.is_dir() else ''\n"
            "    paths.append(f'{prefix}- {p.name}{marker}')\n"
            "lines.extend(paths or ['- <empty>']); out.parent.mkdir(parents=True, exist_ok=True); "
            "out.write_text('\\n'.join(lines) + '\\n', encoding='utf-8'); print('wrote project tree:', out)"
        )
        return self._python_inline_command(code)

    def _looks_like_shell_command(self, value: str) -> bool:
        start = value.strip().split(" ", 1)[0].lower()
        return start in {
            "python", "python3", "py", "pip", "pip3", "pytest", "ruff", "mypy",
            "npm", "npx", "pnpm", "yarn", "node", "vite", "tsc", "eslint",
            "git", "mkdir", "cmake", "make", "gradle", "flutter", "dart", "docker", "uv", "poetry",
        }

    def _compile_create_timeline_commands(self) -> list[dict[str, str]]:
        """Compile only the selected pending timeline lines.

        This function intentionally avoids eager command construction. Older
        versions built a dict for every possible token before the confirmation
        dialog, which triggered temp-tree materialization, compiler scans and
        mapping payload generation even for tokens that were not selected. On
        large project-first trees that can freeze the Tk window and burn CPU for
        minutes before the user even sees the Yes/No terminal prompt.
        """
        self._progress_callback("Create timeline: preparing selected timeline", None, 0)
        config = self._current_create_config()
        target_path = self._create_terminal_target_path()
        placeholders = self._create_placeholder_map()
        pending_lines = self._selected_create_timeline_lines()
        total_lines = max(len(pending_lines), 1)
        compiled: list[dict[str, str]] = []
        for line_index, raw_line in enumerate(pending_lines, start=1):
            self._progress_callback(f"Create timeline: preparing step {line_index}/{total_lines}", line_index, total_lines)
            line = raw_line.strip()
            if not line:
                continue
            token_match = re.search(r"\{\$[^}]+\}", line)
            token = token_match.group(0) if token_match else line
            command = self._create_timeline_command_for_token(token, placeholders, config, target_path)
            replacement = placeholders.get(token, "")
            # Known token resolvers are authoritative. Placeholder prose may only
            # become a command when it already looks like a safe shell command.
            if not command and replacement and self._looks_like_shell_command(replacement) and "<" not in replacement and ">" not in replacement:
                command = replacement
            if command:
                compiled.append({"timeline": line, "command": command, "status": "ready"})
            else:
                compiled.append({"timeline": line, "command": "", "status": "skipped_unresolved_or_non_executable"})
        return compiled

    def _create_timeline_command_for_token(self, token: str, placeholders: dict, config: dict, target_path: Path) -> str:
        """Resolve one timeline token lazily for Run/Compile.

        Keep this resolver cheap. Anything expensive should be returned as a
        terminal-time Python command so the UI reaches the confirmation dialog
        quickly and the loading bar does not hide synchronous CPU work.
        """
        token = str(token or "").strip()
        requirements_path = target_path / "requirements.txt"
        target_commands = {
            "{$create_target[backend]}": lambda: self._create_target_mkdir_command("backend"),
            "{$create_target[frontend]}": lambda: self._create_target_mkdir_command("frontend"),
            "{$create_target[wrapper]}": lambda: self._create_target_mkdir_command("wrapper"),
            "{$create_target[generated]}": lambda: self._create_target_mkdir_command("generated"),
            "{$create_target[assets]}": lambda: self._create_target_mkdir_command("assets"),
            "{$create_target[custom]}": lambda: self._create_target_mkdir_command("custom"),
            "{$python_compileall}": lambda: self._python_compileall_command(target_path),
            "{$pytest_optional}": lambda: self._pytest_optional_command(target_path),
            "{$npm_run_build}": lambda: self._npm_script_optional_command("build", target_path, self._nvm_version_for_target(self.create_build_target.get())),
            "{$npm_run_lint}": lambda: self._npm_script_optional_command("lint", target_path, self._nvm_version_for_target(self.create_build_target.get())),
            "{$npm_run_test_optional}": lambda: self._npm_script_optional_command("test", target_path, self._nvm_version_for_target(self.create_build_target.get())),
            "{$install_node[dependency_version]}": lambda: self._dependency_install_commands_for_ecosystems({"node", "yesvascript", "typescript", "frontend", "node/browser"}, "node", target_path),
            "{$install_python[dependency_version]}": lambda: self._dependency_install_commands_for_ecosystems({"python", "pip", "pyproject", "conda", "scientific_python"}, "python", target_path),
            "{$install_conda[dependency_version]}": lambda: self._dependency_install_commands_for_ecosystems({"conda", "scientific_python"}, "conda", target_path),
            "{$cmake_build_optional}": lambda: self._cmake_build_optional_command(target_path),
            "{$gradle_build_optional}": lambda: self._gradle_build_optional_command(target_path, self._gradle_version_for_target(self.create_build_target.get())),
            "{$flutter_test_optional}": lambda: self._flutter_test_optional_command(target_path),
            "{$write_file[requirements.txt]}": lambda: self._create_touch_file_command("requirements.txt"),
            "{$write_file[package.json]}": lambda: self._create_touch_file_command("package.json"),
            "{$write_temp_project_tree}": self._write_create_temp_tree_command,
            "{$compiler_run}": self._compiler_pipeline_command,
            "{$apply_temp_tree_to_working_path}": self._apply_create_temp_tree_command,
            "{$write_project_mapping}": self._write_create_project_mapping_command,
            "{$write_dependency_layer}": self._write_create_dependency_layer_command,
            "{$write_handoff_index}": self._write_create_handoff_index_command,
            "{$scan_project_scope}": self._write_project_tree_markdown_command,
            "{$write_dependency_inventory}": self._write_create_dependency_layer_command,
            "{$scan_dependency_manifests}": self._write_create_project_mapping_command,
        }
        resolver = target_commands.get(token)
        if resolver is not None:
            return resolver()
        if token.startswith("{$write_file[") and token.endswith("]}"):
            return self._create_touch_file_command(token[len("{$write_file["):-2])
        for row in self._effective_dependency_rows(config):
            if token == self._dependency_row_install_token(row):
                return self._dependency_install_command_for_row(row, target_path)
        if token in set(self._package_control_timeline_tokens(config)):
            return self._package_control_command_for_token(token)
        return ""

    def _append_create_terminal(self, text: str, apply_theme: bool = True) -> None:
        widget = getattr(self, "create_terminal_text", None)
        if widget is None or text is None:
            return
        normalized = str(text)
        if not normalized.endswith("\n"):
            normalized += "\n"
        if apply_theme:
            self._configure_create_terminal_tags()
            self._configure_create_contract_preview_tags()
        for raw_line in normalized.splitlines(True):
            tag = self._terminal_tag_for_line(raw_line.rstrip("\n"))
            try:
                widget.insert("end", raw_line, (tag,))
            except Exception:
                widget.insert("end", raw_line)
        widget.see("end")

    def _compile_create_timeline_terminal(self) -> list[dict[str, str]]:
        # Manual compile previews the selected commands. Do not rescan Start-tab
        # project evidence here; mode is maintained by project load/selection.
        self._set_progress("Create timeline: compiling commands", None, 0)
        compiled = self._compile_create_timeline_commands()
        executable_steps = len([item for item in compiled if item.get("command")])
        self._create_timeline_runtime_step_pending = bool(self._stack_contains_node_runtime(self._current_create_config()))
        self._create_timeline_runtime_completed = False
        self._create_timeline_total_steps = executable_steps + (1 if self._create_timeline_runtime_step_pending else 0)
        self._create_timeline_completed_steps = self._create_timeline_progress_done_count()
        self._set_create_timeline_progress("Create timeline compiled")
        widget = getattr(self, "create_terminal_text", None)
        if widget is not None:
            widget.delete("1.0", "end")
        self._append_create_terminal(f"Temp cwd: {self._create_terminal_work_dir()}")
        self._append_create_terminal(f"Preview target: {self._create_terminal_target_path()}")
        self._append_create_terminal(f"Apply path: {self._create_working_dir()}")
        self._append_create_terminal(f"Export: {self._create_export_path()}")
        self._append_create_terminal("Timeline:")
        for index, item in enumerate(compiled, start=1):
            command = item.get("command") or "<skipped>"
            self._append_create_terminal(f"{index}. [{item.get('status')}] {item.get('timeline')} -> {command}")
        return compiled

    def _create_terminal_shell_command(self) -> list[str]:
        system = platform.system().lower()
        if system.startswith("win"):
            return [os.environ.get("COMSPEC") or "cmd.exe", "/Q", "/K"]
        shell = os.environ.get("SHELL") or "/bin/bash"
        if not Path(shell).exists():
            shell = "/bin/sh"
        if Path(shell).name in {"bash", "zsh", "fish", "sh"}:
            return [shell, "-i"]
        return [shell]

    def _create_terminal_is_running(self) -> bool:
        process = self._create_terminal_process
        return process is not None and process.poll() is None

    def _start_create_terminal_session(self) -> bool:
        with self._create_terminal_lock:
            workdir = self._create_terminal_work_dir()
            if self._create_terminal_is_running():
                current = getattr(self, "_create_terminal_workdir", None)
                try:
                    same_workdir = current is not None and Path(current).resolve() == workdir.resolve()
                except Exception:
                    same_workdir = False
                if same_workdir:
                    self.create_terminal_status.set(f"Term: {workdir}")
                    return True
                process = self._create_terminal_process
                try:
                    if process and process.stdin:
                        process.stdin.write("exit\n")
                        process.stdin.flush()
                except Exception:
                    try:
                        if process:
                            process.terminate()
                    except Exception:
                        pass
                self._create_terminal_process = None
                self._create_terminal_workdir = None
            workdir.mkdir(parents=True, exist_ok=True)
            command = self._create_terminal_shell_command()
            creationflags = getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0) if platform.system().lower().startswith("win") else 0
            self._set_progress("Create terminal: starting hidden process", None, 0)
            try:
                process = _popen_subprocess_hidden(
                    command,
                    cwd=workdir,
                    stdin=subprocess.PIPE,
                    stdout=subprocess.PIPE,
                    stderr=subprocess.STDOUT,
                    text=True,
                    encoding="utf-8",
                    errors="replace",
                    bufsize=1,
                    extra_creationflags=creationflags,
                )
            except Exception as exc:
                messagebox.showerror("Term failed", str(exc))
                self.create_terminal_status.set(f"Term failed: {exc}")
                return False
            self._create_terminal_process = process
            self._create_terminal_workdir = workdir
            self.create_terminal_status.set(f"Term: {workdir}")
            if not getattr(self, "_create_timeline_running", False) and not getattr(self, "_create_timeline_preparing", False):
                self._set_progress("Create terminal: ready", 1, 1)
            self._append_create_terminal(f"\n[term] start: {' '.join(command)}")
            self._append_create_terminal(f"[term] cwd: {workdir}")
            self._append_create_terminal(f"[term] apply: {self._create_working_dir()}")

        def reader() -> None:
            assert process.stdout is not None
            try:
                for line in process.stdout:
                    self._task_queue.put(("create_terminal_output", line.rstrip("\n")))
            except Exception as exc:
                self._task_queue.put(("create_terminal_output", f"[terminal reader error] {exc}"))
            finally:
                exit_code = process.poll()
                if exit_code is None:
                    try:
                        exit_code = process.wait(timeout=0.2)
                    except Exception:
                        exit_code = None
                with self._create_terminal_lock:
                    if self._create_terminal_process is process:
                        self._create_terminal_process = None
                        self._create_terminal_workdir = None
                self._task_queue.put(("create_terminal_status", f"Term stopped" if exit_code is None else f"Term stopped: exit={exit_code}"))
                self._task_queue.put(("create_terminal_output", f"[terminal] stopped exit={exit_code}"))

        threading.Thread(target=reader, name="create-terminal-reader", daemon=True).start()
        return True

    def _restart_create_terminal_session(self) -> bool:
        process = self._create_terminal_process
        if process is not None and process.poll() is None:
            try:
                if process.stdin:
                    process.stdin.write("exit\n")
                    process.stdin.flush()
            except Exception:
                try:
                    process.terminate()
                except Exception:
                    pass
        self._create_terminal_process = None
        self._create_terminal_workdir = None
        return self._start_create_terminal_session()

    def _stop_create_terminal_session(self) -> None:
        process = self._create_terminal_process
        if process is None or process.poll() is not None:
            self.create_terminal_status.set("Term stopped")
            self._create_terminal_workdir = None
            return
        try:
            if process.stdin:
                process.stdin.write("exit\n")
                process.stdin.flush()
        except Exception:
            pass
        self.after(500, self._force_stop_create_terminal_session)

    def _force_stop_create_terminal_session(self) -> None:
        process = self._create_terminal_process
        if process is not None and process.poll() is None:
            try:
                process.terminate()
            except Exception:
                pass

    def _stop_create_timeline_process(self) -> None:
        """Abort the currently running/preparing Create timeline without marking pending steps done."""
        after_id = getattr(self, "_create_timeline_prepare_after", None)
        if after_id:
            try:
                self.after_cancel(after_id)
            except Exception:
                pass
            self._create_timeline_prepare_after = None
        self._create_timeline_preparing = False
        self._create_pending_compiled_timeline = []
        self._create_pending_run_command = ""
        process = self._create_terminal_process
        if process is None or process.poll() is not None:
            self._create_timeline_running = False
            self._create_active_timeline_script = None
            self.create_terminal_status.set("Term stopped")
            self._append_create_terminal("[create] stop requested; no active timeline process")
            self._set_progress("Create timeline stopped", 0)
            return
        self._append_create_terminal("[create] stop requested; aborting active timeline")
        try:
            if platform.system().lower().startswith("win"):
                try:
                    process.send_signal(signal.CTRL_BREAK_EVENT)
                except Exception:
                    process.terminate()
            else:
                process.terminate()
        except Exception:
            try:
                process.kill()
            except Exception:
                pass
        self._create_timeline_running = False
        self._create_active_timeline_script = None
        self.create_terminal_status.set("Timeline stopped")
        self._set_progress("Create timeline stopped; pending steps remain unchecked", 0)
        self.after(700, self._restart_create_terminal_session)

    def _send_create_terminal_command(self, command: str) -> bool:
        command = command.strip()
        if not command:
            return False
        if not self._start_create_terminal_session():
            return False
        process = self._create_terminal_process
        if process is None or process.stdin is None or process.poll() is not None:
            messagebox.showerror("Term stopped", "Create terminal is stopped.")
            return False
        try:
            self._append_create_terminal(f"> {command}")
            if getattr(self, "_create_timeline_running", False) or getattr(self, "_create_timeline_preparing", False):
                self._set_create_timeline_progress("Create timeline: command submitted")
            else:
                self._set_progress("Create terminal: command submitted", 0, 1)
            process.stdin.write(command + "\n")
            process.stdin.flush()
            return True
        except Exception as exc:
            messagebox.showerror("Term write failed", str(exc))
            self.create_terminal_status.set(f"Term write failed: {exc}")
            return False

    def _send_create_terminal_entry(self) -> None:
        command = self.create_terminal_command.get().strip()
        if self._send_create_terminal_command(command):
            self.create_terminal_command.set("")

    def _terminal_status_probe_command(self, index: int) -> str:
        if platform.system().lower().startswith("win"):
            return f"echo [create-task:{index}:exit=%ERRORLEVEL%]"
        return f"printf '[create-task:{index}:exit=%s]\\n' $?"

    def _node_runtime_setup_command(self) -> str:
        """Return a short command that prepares and checks Node runtime for each Run.

        Boilerplate Node version is a minimum. A higher selected/detected version
        is accepted; lower or missing values resolve to the minimum.

        Windows-specific rule: Nvm for Windows must not be invoked from the
        Python/Tk worker or from a piped pseudo-console because it can reject the
        call with "NVM for Windows should be run from a terminal such as CMD or
        PowerShell". The generated .cmd file therefore selects an installed NVM
        Node runtime by prepending the resolved version directory to PATH for
        this Create process only. Linux/macOS still use nvm through bash with
        nvm.sh loaded when available.
        """
        config = self._current_create_config()
        if not self._stack_contains_node_runtime(config):
            return ""
        minimum = self._boilerplate_node_version(config)
        selected = self._normalize_nvm_version(self.create_nvm_version.get())
        version = self._resolve_min_runtime_version(selected, minimum, self._normalize_nvm_version)
        if not version:
            return self._python_print_command("node runtime: None; skipped NVM setup")
        export_dir = self._create_export_path()
        export_dir.mkdir(parents=True, exist_ok=True)
        is_windows = platform.system().lower().startswith("win")
        if is_windows:
            script = export_dir / "create_node_runtime.cmd"
            home = self._windows_nvm_home_for_runtime()
            version_dir = self._windows_nvm_version_dir(version)
            runtime_version = version
            if version_dir:
                resolved_from_dir = self._parse_nvm_version_output(version_dir.name)
                if resolved_from_dir and self._runtime_version_at_least(resolved_from_dir, minimum or version):
                    runtime_version = resolved_from_dir
            lines = [
                "@echo off",
                f'set "REQ_NODE={runtime_version}"',
                f'set "MIN_NODE={minimum or version}"',
                "echo [create-runtime] requested node=%REQ_NODE% min=%MIN_NODE%",
            ]
            selected_root = self._selected_nvm_root_path()
            if home:
                lines.extend([
                    f'set "NVM_HOME={str(home)}"',
                    'echo [create-runtime] Nvm for Windows root=%NVM_HOME%',
                ])
            elif selected_root:
                lines.append(f'echo [create-runtime] custom Node/NVM path={str(selected_root)}')
            else:
                lines.append('echo [create-warn] Nvm for Windows root not found; using current node')
            if version_dir:
                lines.extend([
                    f'set "PATH={str(version_dir)};%PATH%"',
                    f'echo [create-runtime] PATH pinned to NVM Node folder: {str(version_dir)}',
                ])
            else:
                lines.append('echo [create-warn] requested Node version folder not found in NVM root; current node will be checked')
            lines.extend([
                "node -v",
                "if errorlevel 1 (echo [create-error] node runtime check failed & exit /b %ERRORLEVEL%)",
                "node -e \"const v=Number(process.versions.node.split('.')[0]);const m=Number((process.env.MIN_NODE||process.env.REQ_NODE||'0').split('.')[0]);if(m&&v<m){console.error('[create-error] node '+process.version+' < required '+process.env.MIN_NODE);process.exit(1)}console.log('[create-runtime] node '+process.version+' ok >= '+(process.env.MIN_NODE||process.env.REQ_NODE));\"",
                "if errorlevel 1 exit /b %ERRORLEVEL%",
                "echo [create-runtime] node runtime ready",
            ])
            script.write_text("\r\n".join(lines) + "\r\n", encoding="utf-8")
            return "call " + subprocess.list2cmdline([str(script)])

        script = export_dir / "create_node_runtime.sh"
        safe_version = shlex.quote(version)
        safe_minimum = shlex.quote(minimum or version)
        lines = [
            "#!/usr/bin/env bash",
            "set -u",
            f"REQ_NODE={safe_version}",
            f"MIN_NODE={safe_minimum}",
            'echo "[create-runtime] requested node=${REQ_NODE} min=${MIN_NODE}"',
            'if command -v nvm >/dev/null 2>&1; then',
            '  nvm use "${REQ_NODE}" || (nvm install "${REQ_NODE}" && nvm use "${REQ_NODE}") || echo "[create-warn] nvm could not activate ${REQ_NODE}; using current node"',
            'elif [ -s "${NVM_DIR:-$HOME/.nvm}/nvm.sh" ]; then',
            '  . "${NVM_DIR:-$HOME/.nvm}/nvm.sh"',
            '  nvm use "${REQ_NODE}" || (nvm install "${REQ_NODE}" && nvm use "${REQ_NODE}") || echo "[create-warn] nvm could not activate ${REQ_NODE}; using current node"',
            'else',
            '  echo "[create-warn] nvm not available; using current node"',
            'fi',
            'node -v || { echo "[create-error] node runtime check failed"; exit 1; }',
            'node -e "const v=Number(process.versions.node.split(\'.\')[0]);const m=Number((process.env.MIN_NODE||process.env.REQ_NODE||\'0\').split(\'.\')[0]);if(m&&v<m){console.error(\'[create-error] node \'+process.version+\' < required \'+process.env.MIN_NODE);process.exit(1)}console.log(\'[create-runtime] node \'+process.version+\' ok >= \'+(process.env.MIN_NODE||process.env.REQ_NODE));"',
            'echo "[create-runtime] node runtime ready"',
        ]
        script.write_text("\n".join(lines) + "\n", encoding="utf-8")
        try:
            script.chmod(0o755)
        except Exception:
            pass
        return self._shell_join(["bash", script])

    def _python_runtime_setup_command(self) -> str:
        config = self._current_create_config()
        if not (self._stack_contains_ecosystem_runtime(config, {"python", "pip", "pyproject", "conda", "scientific_python"}) or (getattr(self, "_create_ecosystem_runtime_hints", {}) or {}).get("python", {}).get("detected")):
            return ""
        python_exe = self._python_runtime_executable(self.create_build_target.get())
        version = self._normalize_python_version(self.create_python_version.get())
        code = (
            "import subprocess, sys; from pathlib import Path\n"
            f"py={python_exe!r}\n"
            f"expected={version!r}\n"
            "print('[create-runtime] python executable:', py)\n"
            "try:\n"
            "    proc=subprocess.run([py, '-c', 'import sys; print(\".\".join(map(str, sys.version_info[:3])))'], capture_output=True, text=True, timeout=6)\n"
            "except Exception as exc:\n"
            "    print('[create-warn] python runtime check failed:', exc); raise SystemExit(0)\n"
            "if proc.returncode != 0:\n"
            "    print('[create-warn] python runtime unavailable; optional Python setup skipped'); raise SystemExit(0)\n"
            "detected=(proc.stdout or '').strip()\n"
            "print('[create-runtime] python', detected, 'ready')\n"
        )
        return self._python_inline_command(code)

    def _generic_ecosystem_runtime_setup_command(self) -> str:
        hints = getattr(self, "_create_ecosystem_runtime_hints", {}) if isinstance(getattr(self, "_create_ecosystem_runtime_hints", {}), dict) else {}
        rows = []
        for key in ("flutter", "dotnet", "go", "rust", "yesva", "native", "docker"):
            data = hints.get(key) or {}
            version = self._normalize_generic_version(getattr(self, f"create_{'cmake' if key == 'native' else key}_version", tk.StringVar(value="")).get())
            path = self._selected_runtime_path_text(key)
            if data.get("detected") or version or path:
                detail = key
                if version:
                    detail += f" {version}"
                if path:
                    detail += f" @ {path}"
                rows.append(detail)
        if not rows:
            return ""
        return self._python_print_command("runtime ecosystems detected: " + ", ".join(rows))

    def _create_runtime_setup_command(self) -> str:
        commands = [cmd for cmd in (self._node_runtime_setup_command(), self._python_runtime_setup_command(), self._generic_ecosystem_runtime_setup_command()) if cmd]
        if not commands:
            return ""
        return " && ".join(commands)

    def _wrap_create_script_command(self, command: str) -> str:
        command = str(command or "").strip()
        if not command or not platform.system().lower().startswith("win"):
            return command
        if "\n" in command or "\r" in command:
            return command
        lowered = command.lstrip().lower()
        head = lowered.lstrip("@")
        first = head.split(None, 1)[0] if head else ""
        passthrough_tokens = {
            "call",
            "cd",
            "chdir",
            "cls",
            "color",
            "copy",
            "del",
            "dir",
            "echo",
            "erase",
            "exit",
            "for",
            "if",
            "md",
            "mkdir",
            "move",
            "popd",
            "pushd",
            "rd",
            "rem",
            "ren",
            "rename",
            "rmdir",
            "set",
            "shift",
            "start",
            "title",
            "type",
            "ver",
            "verify",
            "vol",
        }
        if head.startswith("::") or first in passthrough_tokens:
            return command
        return f"call {command}"

    def _write_create_terminal_script(self, compiled: list[dict[str, str]]) -> tuple[Path, str]:
        self._create_running_timeline_by_index = {index: str(item.get("timeline", "")) for index, item in enumerate(compiled, start=1)}
        export_dir = self._create_export_path()
        export_dir.mkdir(parents=True, exist_ok=True)
        workdir = self._create_terminal_work_dir()
        apply_dir = self._create_working_dir()
        is_windows = platform.system().lower().startswith("win")
        if is_windows:
            script = export_dir / "create_timeline_run.cmd"
            lines = [
                "@echo off",
                f"cd /d {subprocess.list2cmdline([str(workdir)])}",
                f"echo [create] temp cwd: {workdir}",
                f"echo [create] preview target: {self._create_terminal_target_path()}",
                f"echo [create] apply path: {apply_dir}",
            ]
            runtime_setup = self._create_runtime_setup_command()
            self._create_timeline_runtime_step_pending = bool(runtime_setup)
            self._create_timeline_runtime_completed = False
            self._create_timeline_total_steps = len(compiled) + (1 if runtime_setup else 0)
            if runtime_setup:
                lines.extend([
                    "echo [create-runtime] setup",
                    runtime_setup,
                    "if errorlevel 1 (echo [create-runtime:exit=%ERRORLEVEL%] & exit /b %ERRORLEVEL%)",
                    "echo [create-runtime:exit=0]",
                ])
            for index, item in enumerate(compiled, start=1):
                timeline = str(item.get("timeline", "")).replace("^", "^^").replace("&", "^&").replace("|", "^|").replace(">", "^>").replace("<", "^<")
                lines.extend([
                    f"echo [create-task:{index}] {timeline}",
                    self._wrap_create_script_command(str(item.get("command") or "")),
                    f"if errorlevel 1 (echo [create-task:{index}:exit=%ERRORLEVEL%] & exit /b %ERRORLEVEL%)",
                    f"echo [create-task:{index}:exit=0]",
                ])
            lines.append("echo [create] timeline complete")
            script.write_text("\r\n".join(lines) + "\r\n", encoding="utf-8")
            return script, f"call {subprocess.list2cmdline([str(script)])}"

        script = export_dir / "create_timeline_run.sh"
        lines = [
            "#!/usr/bin/env sh",
            f"cd {shlex.quote(str(workdir))}",
            f"echo '[create] temp cwd: {workdir}'",
            f"echo '[create] preview target: {self._create_terminal_target_path()}'",
            f"echo '[create] apply path: {apply_dir}'",
        ]
        runtime_setup = self._create_runtime_setup_command()
        self._create_timeline_runtime_step_pending = bool(runtime_setup)
        self._create_timeline_runtime_completed = False
        self._create_timeline_total_steps = len(compiled) + (1 if runtime_setup else 0)
        if runtime_setup:
            lines.extend([
                "echo '[create-runtime] setup'",
                runtime_setup,
                "status=$?",
                "echo '[create-runtime:exit='\"$status\"']'",
                "if [ \"$status\" -ne 0 ]; then exit \"$status\"; fi",
            ])
        for index, item in enumerate(compiled, start=1):
            timeline = str(item.get("timeline", "")).replace("'", "'\\''")
            lines.extend([
                f"echo '[create-task:{index}] {timeline}'",
                item["command"],
                "status=$?",
                f"echo '[create-task:{index}:exit='\"$status\"']'",
                "if [ \"$status\" -ne 0 ]; then exit \"$status\"; fi",
            ])
        lines.append("echo '[create] timeline complete'")
        script.write_text("\n".join(lines) + "\n", encoding="utf-8")
        try:
            script.chmod(0o755)
        except Exception:
            pass
        return script, self._shell_join(["sh", script])

    def _wait_for_create_background_tasks(self, reason: str = "run", timeout_s: float = 8.0) -> bool:
        """Deprecated synchronous wait kept for compatibility.

        Button-driven timeline runs use `_wait_for_create_background_tasks_async`
        so Tk never blocks on sleep/update loops.
        """
        if getattr(self, "_create_nvm_probe_running", False) or getattr(self, "_create_gradle_probe_running", False):
            self._set_progress(f"Create timeline: runtime probes laufen vor {reason}", None, 0)
            return False
        return True

    def _create_timeline_wait_reasons(self, reason: str = "run") -> list[str]:
        """Return only short runtime probes that Run should wait for.

        Source clone/materialize jobs can be large and must not hold the Run
        button before the confirmation dialog. They keep their own progress state;
        Run uses the current mounted temp root if available and otherwise starts
        from an empty safe temp cwd. Terminal tasks run only after user approval.
        """
        reasons: list[str] = []
        if getattr(self, "_create_nvm_probe_running", False):
            reasons.append("NVM probe")
        if getattr(self, "_create_gradle_probe_running", False):
            reasons.append("Gradle probe")
        return self._dedupe_create_list(reasons)

    def _ensure_create_source_ready_for_timeline(self) -> bool:
        """Keep Run Timeline non-blocking before the confirmation dialog.

        A large Start project may still be cloning/materializing in the background.
        The Run button must not start or wait for that heavy work. If a mounted
        Create source is already available we reuse it; otherwise the generated
        terminal script starts from a safe temp cwd and writes only temp output.
        """
        if not (self._use_project_first_tree_preview() and self._is_create_tab_active()):
            return True
        if self._active_successful_create_build_for_current_stack():
            self._restore_completed_create_build_root_for_current_stack()
            return True
        if self._create_source_clone_ready():
            return True
        try:
            root = self._create_temp_root()
            root.mkdir(parents=True, exist_ok=True)
            self._append_create_terminal("[create-warn] source clone not ready; Run uses safe temp cwd and will not block before confirmation")
        except Exception:
            pass
        return True

    def _wait_for_create_background_tasks_async(self, reason: str, started_at: float, timeout_s: float, on_ready) -> None:
        """Poll Create preflight jobs without blocking the Tk mainloop."""
        if not getattr(self, "_create_timeline_preparing", False):
            return
        source_ready = self._ensure_create_source_ready_for_timeline()
        wait_reasons = self._create_timeline_wait_reasons(reason)
        if wait_reasons or not source_ready:
            elapsed = time.monotonic() - started_at
            label = ", ".join(wait_reasons) if wait_reasons else "Create Source Mount"
            self._set_progress(f"Create timeline: waiting for {label} before {reason}", None, 0)
            if elapsed >= timeout_s:
                self._create_timeline_preparing = False
                self._create_timeline_running = False
                self._create_timeline_prepare_after = None
                self._append_create_terminal(f"[create-warn] background/preflight tasks timed out before {reason}; run aborted: {label}")
                self._set_progress("Create background/preflight tasks still running; run aborted", 0)
                return
            try:
                self._append_create_history_record("create_background_wait", {"reason": reason, "waiting_for": wait_reasons or ["Create Source Mount"], "elapsed_ms": int(elapsed * 1000)})
            except Exception:
                pass
            self._create_timeline_prepare_after = self.after(160, lambda: self._wait_for_create_background_tasks_async(reason, started_at, timeout_s, on_ready))
            return
        self._create_timeline_prepare_after = None
        self.after(20, on_ready)

    def _run_create_timeline_terminal(self) -> None:
        if getattr(self, "_create_timeline_running", False) or getattr(self, "_create_timeline_preparing", False):
            messagebox.showwarning("Timeline already running", "A Create timeline is already running or preparing. Stop it before starting another one.")
            return
        self._create_timeline_preparing = True
        self._create_timeline_runtime_step_pending = False
        self._create_timeline_runtime_completed = False
        self._create_timeline_completed_steps = self._create_timeline_checked_done_count()
        self._create_timeline_prepare_started_at = time.monotonic()
        self._set_progress("Create timeline: Start angefordert", None, 0)
        # Return to Tk immediately so the loading bar can paint before mode
        # routing, source-mount checks, mapping and command compilation begin.
        self._create_timeline_prepare_after = self.after(30, self._prepare_run_create_timeline_terminal)

    def _prepare_run_create_timeline_terminal(self) -> None:
        if not getattr(self, "_create_timeline_preparing", False):
            return
        self._create_timeline_prepare_after = None
        try:
            self._set_progress("Create timeline: applying mode/target", None, 0)
            # Do not rescan the Start project from the Run button. Mode options are
            # maintained while loading/selecting the project; a fresh evidence scan
            # here can freeze large trees before the confirmation dialog.
            self._set_progress("Create timeline: preparing runtime and boilerplate configuration", None, 0)
            # Run always applies force boilerplate runtime versions first, waits for
            # source clone/probes, then writes a terminal script that sets/checks
            # Node before tasks.
            self._apply_boilerplate_runtime_versions(self._current_create_config(), "run")
        except Exception as exc:
            self._create_timeline_preparing = False
            self._set_progress(f"Create timeline preparation failed: {exc}", 0)
            messagebox.showerror("Create timeline preparation failed", str(exc))
            return
        self._wait_for_create_background_tasks_async("run", self._create_timeline_prepare_started_at, 300.0, self._continue_run_create_timeline_terminal)

    def _continue_run_create_timeline_terminal(self) -> None:
        if not getattr(self, "_create_timeline_preparing", False):
            return
        self._set_progress("Create timeline: compiling timeline, mapping and preview tree", None, 0)
        self.after(20, self._compile_run_create_timeline_terminal)

    def _compile_run_create_timeline_terminal(self) -> None:
        if not getattr(self, "_create_timeline_preparing", False):
            return
        try:
            # Run path must stay fast: do not call _compile_create_timeline_terminal(),
            # because the manual Compile button may perform UI preview refreshes and
            # mode evidence scans. Build only selected commands lazily, then show the
            # confirmation dialog.
            compiled_all = self._compile_create_timeline_commands()
            executable_steps = len([item for item in compiled_all if item.get("command")])
            self._create_timeline_runtime_step_pending = bool(self._stack_contains_node_runtime(self._current_create_config()))
            self._create_timeline_runtime_completed = False
            self._create_timeline_total_steps = executable_steps + (1 if self._create_timeline_runtime_step_pending else 0)
            self._create_timeline_completed_steps = self._create_timeline_progress_done_count()
            self._set_create_timeline_progress("Create timeline: execution prepared")
            compiled = [item for item in compiled_all if item.get("command")]
            if not compiled:
                self._create_timeline_preparing = False
                self._set_progress("Create timeline: no open steps", 1, 1)
                messagebox.showinfo("No steps", "Temp preview compiled. No pending timeline steps remain.")
                return
            self._create_pending_compiled_timeline = compiled
            self._set_progress("Create timeline: preparing working and temp paths", None, 0)
            self.after(20, self._write_run_create_timeline_script)
        except Exception as exc:
            self._create_timeline_preparing = False
            self._create_timeline_running = False
            self._create_active_timeline_script = None
            self._set_progress(f"Create timeline failed during compile/mapping: {exc}", 0)
            messagebox.showerror("Create timeline failed during compile/mapping", str(exc))

    def _write_run_create_timeline_script(self) -> None:
        if not getattr(self, "_create_timeline_preparing", False):
            return
        try:
            compiled = list(getattr(self, "_create_pending_compiled_timeline", []) or [])
            workdir = self._create_working_dir()
            workdir.mkdir(parents=True, exist_ok=True)
            tempdir = self._create_terminal_work_dir()
            self._create_current_run_mode = self.create_mode.get()
            self._create_current_run_stack = self.create_stack.get()
            self._create_current_run_preview_root = tempdir.resolve()
            self._set_progress("Create timeline: writing executable script", None, 0)
            script_path, run_command = self._write_create_terminal_script(compiled)
            self._create_active_timeline_script = script_path
            self._create_pending_run_command = run_command
            total = self._create_timeline_progress_total_count()
            self._set_progress("Create timeline: waiting for user approval", 0, total)
            ok = messagebox.askyesno(
                "Run Create timeline in terminal?",
                f"Run {len(compiled)} pending compiled command(s) through the live Create terminal session.\n\nTemp cwd:\n{tempdir}\n\nApply path:\n{workdir}\n\nScript:\n{script_path}\n\nThis performs real local tasks and stops on the first non-zero exit. Continue?",
            )
            if not ok:
                self._create_timeline_preparing = False
                self._create_active_timeline_script = None
                self._create_pending_compiled_timeline = []
                self._create_pending_run_command = ""
                self._set_progress("Create timeline: run cancelled", 0)
                return
            self._set_progress("Create timeline: starting terminal", 0, total)
            self.after(20, self._start_run_create_timeline_script)
        except Exception as exc:
            self._create_timeline_preparing = False
            self._create_timeline_running = False
            self._create_active_timeline_script = None
            self._set_progress(f"Create timeline failed before start: {exc}", 0)
            messagebox.showerror("Create timeline failed before start", str(exc))

    def _start_run_create_timeline_script(self) -> None:
        if not getattr(self, "_create_timeline_preparing", False):
            return
        try:
            total = self._create_timeline_progress_total_count()
            if not self._start_create_terminal_session():
                self._create_timeline_preparing = False
                self._create_active_timeline_script = None
                self._set_progress("Create timeline: terminal start failed", 0)
                return
            script_path = self._create_active_timeline_script
            run_command = str(getattr(self, "_create_pending_run_command", "") or "")
            self._append_create_terminal(f"\n[create] wrote terminal script: {script_path}")
            self._create_timeline_running = True
            self._create_timeline_preparing = False
            self._set_create_timeline_progress("Create timeline: running script", 0, total)
            if not self._send_create_terminal_command(run_command):
                self._create_timeline_running = False
                self._create_active_timeline_script = None
                self._set_progress("Create timeline: command submit failed", 0)
                return
            self._create_pending_compiled_timeline = []
            self._create_pending_run_command = ""
            self._append_create_terminal("[create] timeline script submitted; watch terminal output above")
        except Exception as exc:
            self._create_timeline_preparing = False
            self._create_timeline_running = False
            self._create_active_timeline_script = None
            self._set_progress(f"Create timeline failed while starting terminal: {exc}", 0)
            messagebox.showerror("Create timeline failed while starting terminal", str(exc))

    def _on_create_mode_changed(self, *_args) -> None:
        self._ensure_create_mode_matches_start_reference("mode_changed")
        # Only New Project Abstraction intentionally moves away from the completed
        # build root. Feature/refactor keep Build.complete pinned for the stack.
        if self.create_mode.get() == "new_project_abstraction":
            self._create_tree_temp_root = None
            self._create_tree_temp_signature = ""
        else:
            completed = self._completed_create_build_root_for_current_stack()
            if completed is not None:
                self._create_tree_temp_root = completed
                self.create_temp_preview_dir.set(str(completed))
        if hasattr(self, "create_timeline_check_frame"):
            self._refresh_create_timeline_checklist(reset_checked=True)
        self._refresh_create_context_variable_menu()
        self._refresh_create_catalog_entry_menu()
        self._refresh_create_token_editor(keep_current=True)
        self._refresh_create_export_button_visibility()
        self._refresh_create_parameter_slider_state()
        self._sync_global_reference_selection_from_create_config(self._current_create_config(), "mode_changed")
        self._refresh_create_stack_control_state()
        self._ensure_last_git_commit_scan_for_current_selection("mode_changed")
        self._schedule_create_preview_refresh()

    def _on_create_category_changed(self, _event=None) -> None:
        if not hasattr(self, "create_stack_box"):
            return
        if _event is not None and self._create_stack_controls_should_lock():
            self._refresh_create_stack_control_state()
            return
        category = self.create_stack_category.get()
        catalog = self._create_stack_catalog()
        values = [name for name, config in catalog.items() if config.get("category") == category]
        if not values:
            values = list(catalog.keys())
        self.create_stack_box.configure(values=values)
        if self.create_stack.get() not in values:
            self.create_stack.set(values[0])
        self._on_create_stack_changed()

    def _on_create_stack_changed(self, _event=None) -> None:
        if _event is not None and self._create_stack_controls_should_lock():
            self._refresh_create_stack_control_state()
            return
        self._create_current_run_id = hashlib.sha1(f"{time.time()}|{self.create_stack.get()}".encode()).hexdigest()[:10]
        # A selected stack owns its own Create session only for new abstraction / completed builds.
        # When a Start-tab Working Tree is active, Mapping and temp generation must stay
        # project-first and must not restore Build.complete or boilerplate target roots.
        has_start_project_reference_pre = bool(self._create_project_first_mode and self._create_project_scope_snapshot and self._create_project_source_base)
        custom_first_active = self._create_custom_first_active()
        self._create_last_successful_build = None if has_start_project_reference_pre else self._latest_successful_build_for_stack(self.create_stack.get())
        if self._create_last_successful_build:
            try:
                self._create_successful_builds_by_stack[self.create_stack.get()] = self._create_last_successful_build
                root = Path(str(self._create_last_successful_build.get("temp_preview_dir") or "")).resolve()
                if root.exists() and self.create_mode.get() != "new_project_abstraction":
                    self._create_tree_temp_root = root
                    self.create_temp_preview_dir.set(str(root))
            except Exception:
                pass
        else:
            self._create_tree_temp_root = None
            self._create_tree_temp_signature = ""
        self._ensure_create_mode_matches_start_reference("stack_changed")
        self._refresh_create_mode_options("stack_changed")
        # For a Start-tab Working Tree, Create Mapping must remain project-first.
        # Stack/category selection may change prompt boilerplate hints, but it must
        # not replace the Mapping tree or assign a boilerplate target over the real
        # project clone. Only New Abstraction without a Start project uses boilerplate preview.
        has_start_project_reference = bool(self._create_project_first_mode and self._create_project_scope_snapshot and self._create_project_source_base)
        self._create_boilerplate_preview_override = (not has_start_project_reference) and not custom_first_active
        config = self._current_create_config() if custom_first_active else self._create_stack_catalog().get(self.create_stack.get(), {})
        if config:
            if custom_first_active:
                self.create_stack_category.set(self._resolved_create_stack_category(config))
            else:
                self.create_stack_category.set(config.get("category", self.create_stack_category.get()))
            self.create_dependencies.set(str(config.get("dependencies", "")))
            # Create may write active-state fields, but it must not overwrite
            # Generator-owned target rows. In project-first mode the target path
            # and build target come from detected project evidence below; in pure
            # boilerplate/new-abstraction mode they still come from the selected
            # Create stack as active state only.
            if not self._create_project_first_mode or self._create_boilerplate_preview_override:
                self.create_target_path.set(config.get("path", self.create_target_path.get()))
                self.create_build_target.set(config.get("build_target", config.get("path_type", self.create_build_target.get())))
            # Stack selection may set boilerplate minimum versions, but it must
            # not start NVM/Gradle probes. Probes are owned by real Start/Create
            # project reads so switching catalog entries stays cheap and stable.
            if not custom_first_active:
                self._apply_boilerplate_runtime_versions(config, "stack_changed")
                self._schedule_stack_required_ecosystem_probes(config, "stack_changed")
            self._set_text_widget_lines("create_timeline_text", self._base_create_timeline_lines(config) if hasattr(self, "create_timeline_check_frame") else config.get("timeline", []))
            self._set_text_widget_lines("create_project_tree_text", config.get("tree", []))
            self._set_text_widget_lines("create_placeholder_text", config.get("placeholders", {}))
            if hasattr(self, "create_dependency_tree"):
                if self._use_project_first_tree_preview() and self._create_project_scope_snapshot and self._create_project_source_base:
                    self._load_project_first_dependency_rows(self._create_project_source_base, self._create_project_scope_snapshot)
                else:
                    self._refresh_dependency_crud_tree(force_from_stack=True)
            else:
                self._set_text_widget_lines("create_dependency_text", self._format_create_dependency_layer(config))
            if hasattr(self, "create_preview_tree"):
                self._refresh_create_tree_preview()
            if hasattr(self, "create_compiler_tree"):
                self._scan_create_compiler_rows(force=True)
            if hasattr(self, "create_timeline_check_frame"):
                self._refresh_create_timeline_checklist(reset_checked=False)
            self._refresh_create_runtime_field_visibility(config)
            # Generator targets are parent-owned. Stack changes in Create may
            # update active state and Mapping preview, but must not rewrite
            # self.targets. Generator/Prompt Builder/Export inherit from the
            # Generator target table, not the other way around.
        if custom_first_active:
            self.create_project_mode_status.set("Create mode: Custom-first — Mapping toggles active state; boilerplate is reference-only")
        elif getattr(self, "_create_boilerplate_preview_override", False):
            self.create_project_mode_status.set("Create mode: boilerplate preview — Mapping follows selected stack layout")
        elif self._create_project_first_mode:
            self.create_project_mode_status.set("Create mode: project-first — Mapping follows Start Working Tree clone, not boilerplate target")
        self._reactive_create_catalog_refresh("stack_changed")
        self._refresh_create_catalog_entry_menu()
        self._refresh_create_token_editor(keep_current=True)
        self._refresh_create_export_button_visibility()
        self._refresh_create_parameter_slider_state()
        self._sync_global_reference_selection_from_create_config(self._current_create_config(), "stack_changed")
        self._refresh_create_stack_control_state()

    def _create_mode_context(self, mode: str | None = None, config: dict | None = None) -> dict:
        """Return Create-mode specific boilerplate routing."""
        mode = str(mode or self.create_mode.get() or "new_project_abstraction").strip() or "new_project_abstraction"
        base = {
            "id": mode,
            "label": mode.replace("_", " ").title(),
            "routine": "create_new_abstraction",
            "start_requirement": "none",
            "profiles": ["Create", "ProfessionalSolutionEngineering", "ContextEngineering", "PromptEngineering"],
            "references": [
                "create_stack_reference",
                "anthropic_context_engineering_reference",
                "openai_prompt_engineering_reference",
                "structured_output_reference",
                "prompt_eval_reference",
                "prompt_versioning_reference",
                "professional_solution_engineering_reference",
            ],
            "roles": [
                "create_stack_operator",
                "create_context_build_operator",
                "prompt_architect_operator",
                "prompt_eval_operator",
                "professional_solution_engineering_operator",
            ],
            "weights": [
                "create_stack_standard",
                "context_engineering_standard",
                "prompt_engineering_2026_standard",
                "prompt_evaluation_standard",
                "professional_solution_engineering_standard",
            ],
            "prompt_essentials": [
                "Outcome first: target outcome, evidence, constraints, output contract, validation, stop condition.",
                "Keep trusted Create rules separate from user prompt and project file content.",
                "Write id-addressable manifest artifacts for prompt, mapping, dependencies, validation and export.",
            ],
            "timeline_policy": "Create a new target abstraction from the selected boilerplate; do not assume existing project state.",
        }
        if mode == "feature_for_existing_project":
            base.update({
                "routine": "develop_feature_from_successful_build_or_verified_start_tree",
                "start_requirement": "successful_timeline_build_or_start_working_dir_reference",
                "profiles": base["profiles"] + ["RepositoryManagement", "CreatePipeline", "ChangedFilesOnly"],
                "references": base["references"] + ["create_timeline_stop_progress_reference", "process_log_reference", "summary_documentation_reference"],
                "roles": base["roles"] + ["micro_task_operator", "repository_management_prompt_operator", "create_export_boundary_operator"],
                "weights": base["weights"] + ["micro_tasks_standard", "create_pipeline_production_standard", "export_traceability_standard"],
                "prompt_essentials": base["prompt_essentials"] + [
                    "Feature work must start from a successful Create timeline build or a real Start-tab working tree.",
                    "Patch only changed files and preserve generated mapping/dependency manifests.",
                    "If the base evidence is missing, downgrade to New Project Abstraction before compiling or running.",
                ],
                "timeline_policy": "Extend the latest successful timeline build; do not rebuild from empty temp state unless the stack changed.",
            })
        elif mode == "refactor_existing_stack":
            base.update({
                "routine": "refactor_verified_stack",
                "start_requirement": "successful_timeline_build_or_start_working_dir_reference",
                "profiles": base["profiles"] + ["CleanProject", "RepositoryManagement", "ChangedFilesOnly"],
                "references": base["references"] + ["clean_project_reference", "process_log_reference", "summary_documentation_reference"],
                "roles": base["roles"] + ["repository_management_prompt_operator", "create_project_mapping_operator", "create_export_boundary_operator"],
                "weights": base["weights"] + ["clean_project_standard", "documentation_traceability_standard", "export_traceability_standard"],
                "prompt_essentials": base["prompt_essentials"] + [
                    "Refactor only with verified files, manifests and tree evidence.",
                    "No broad rewrites; keep rollback and validation explicit.",
                    "If the base evidence is missing, downgrade to New Project Abstraction before compiling or running.",
                ],
                "timeline_policy": "Refactor a verified stack in place; keep target boundaries and manifests stable.",
            })
        chain_schema = self._create_chain_schema(mode, [], config or {}) if hasattr(self, "schema") else {}
        base["chain_schema"] = chain_schema
        base["chain_boilerplate_ids"] = [entry.get("id") for entry in chain_schema.get("boilerplates", []) if entry.get("id")]
        base["chain_reference_policy"] = "available chain entries are not active references; only the selected Create header Entry may add refs/roles"
        return base

    def _selected_create_chain_entry_from_schema(self, chain_schema: dict) -> dict | None:
        entry_id = self._selected_create_catalog_entry_id() if hasattr(self, "create_catalog_entry") else ""
        if not entry_id:
            return None
        for entry in chain_schema.get("boilerplates", []):
            if isinstance(entry, dict) and str(entry.get("id") or "").strip() == entry_id:
                return dict(entry)
        return None

    def _apply_create_mode_context_to_config(self, config: dict) -> dict:
        context = self._create_mode_context(self.create_mode.get(), config)
        config = dict(config)
        config["create_mode_context"] = context
        config["profiles"] = self._dedupe_create_list(list(config.get("profiles", [])) + context.get("profiles", []))
        config["references"] = self._dedupe_create_list(list(config.get("references", [])) + context.get("references", []))
        config["roles"] = self._dedupe_create_list(list(config.get("roles", [])) + context.get("roles", []))
        config["create_weight_profiles"] = self._dedupe_create_list(list(config.get("create_weight_profiles", [])) + context.get("weights", []))
        chain_schema = context.get("chain_schema") or self._create_chain_schema(context.get("id"), [], config)
        selected_chain_entry = self._selected_create_chain_entry_from_schema(chain_schema)
        if selected_chain_entry:
            config["references"] = self._dedupe_create_list(list(config.get("references", [])) + list(selected_chain_entry.get("references", [])))
            config["roles"] = self._dedupe_create_list(list(config.get("roles", [])) + list(selected_chain_entry.get("roles", [])))
        config["create_chain_schema"] = chain_schema
        config["selected_create_chain_entry"] = selected_chain_entry or None
        config["create_chain_boilerplates"] = list(chain_schema.get("boilerplates", []))
        config["create_mode_boilerplate"] = {
            "entry_mode": context.get("id"),
            "routine": context.get("routine"),
            "stack": self.create_stack.get(),
            "stack_category": config.get("category", self.create_stack_category.get()),
            "target": config.get("build_target", self.create_build_target.get()),
            "feature_update_allowed": bool(context.get("id") in {"feature_for_existing_project", "refactor_existing_stack"} and (self._active_successful_create_build_for_current_stack() or self._has_start_tab_target_match())),
            "requires_build_complete_or_start_target_match": context.get("id") in {"feature_for_existing_project", "refactor_existing_stack"},
            "export_context": "create_working_dir_from_completed_build" if self._active_successful_create_build_for_current_stack() else "start_target_match_or_new_abstraction",
            "chain_schema": chain_schema,
            "selected_chain_entry": selected_chain_entry or None,
            "mode_catalog": self._create_mode_catalog(config),
        }
        return config

    def _path_has_project_evidence(self, base: Path, max_files: int = 800) -> bool:
        if not base.exists() or not base.is_dir():
            return False
        if self._path_is_synthetic_project_root(base):
            return False
        evidence_names = {
            "package.json", "requirements.txt", "pyproject.toml", "pipfile", "poetry.lock", "uv.lock",
            "manage.py", "vite.config.js", "vite.config.ts", "next.config.js", "index.html", "settings.gradle", "settings.gradle.kts", "build.gradle", "build.gradle.kts", "pubspec.yaml", "cmakelists.txt",
        }
        source_suffixes = {".py", ".js", ".ts", ".vue", ".tsx", ".jsx", ".cs", ".yesva", ".kt", ".dart", ".cpp", ".c", ".h", ".hpp", ".md", ".json"}
        found_files = 0
        try:
            for path in base.rglob("*"):
                parts = {part.lower() for part in path.parts}
                if parts & {".git", "node_modules", "dist", "build", "__pycache__", "output", "create-export"}:
                    continue
                if not path.is_file():
                    continue
                found_files += 1
                name = path.name.lower()
                if name in evidence_names or path.suffix.lower() in source_suffixes:
                    return True
                if found_files >= max_files:
                    break
        except Exception:
            return False
        return False

    def _has_start_tab_target_match(self) -> bool:
        """Start-tab evidence only counts when it matches the current Create target."""
        if not self._has_start_tab_working_dir_reference():
            return False
        try:
            base = Path(self.output_base.get() or ".").expanduser().resolve()
        except Exception:
            return False
        target_type = str(self.create_build_target.get() or self.path_type_var.get() or "wrapper").lower().strip()
        if target_type in {"wrapper", "generated", "custom", ""}:
            return True
        try:
            rel = self._create_target_relative_path()
            if str(rel) not in {".", ""}:
                candidate = (base / rel).resolve()
                candidate.relative_to(base)
                if self._path_has_project_evidence(candidate, max_files=500):
                    return True
        except Exception:
            pass
        for target in getattr(self, "_create_detected_targets", []):
            if str(target.get("path_type") or "").lower() == target_type:
                return True
        return False

    def _has_start_tab_working_dir_reference(self) -> bool:
        """Return True only when the Start tab points at a real non-temp project-like tree."""
        try:
            base = Path(self.output_base.get() or ".").expanduser().resolve()
        except Exception:
            return False
        if not base.exists() or not base.is_dir():
            return False
        base_text = str(base).replace("\\", "/").lower()
        if self._path_is_under_system_temp(base) or self._path_is_synthetic_project_root(base):
            # Any Start-tab path under temp or Prompt Guide's own runtime is
            # synthetic for Create unless a Build.complete record promotes it.
            # Without that flag it must enter as New Project Abstraction, not
            # feature/refactor, and must never clone preview output as a Project Root.
            return False
        try:
            if self._create_project_scope_snapshot and self._create_project_source_base:
                if Path(self._create_project_source_base).resolve() == base and self._scope_has_project_evidence(self._create_project_scope_snapshot):
                    return True
        except Exception:
            pass
        return self._path_has_project_evidence(base)

    def _create_available_modes(self) -> list[str]:
        """Return modes that are valid for the current Create base evidence.

        A real Start-tab project with target match is an existing-project source.
        In that state New Project Abstraction is deliberately hidden: the user
        can plan features/refactors only. The synthetic default start-worktree
        under the system temp directory never counts as that evidence.
        """
        if self._create_unmount_blocks_start_base():
            return ["new_project_abstraction"]
        self._clear_manual_create_override_if_real_start_base("available_modes")
        has_real_start = self._has_start_tab_target_match()
        has_build = bool(self._active_successful_create_build_for_current_stack())
        has_project_abstraction = bool(getattr(self, "_create_project_first_mode", False) or getattr(self, "_create_project_scope_snapshot", None) or getattr(self, "_create_project_source_base", None))
        if has_real_start or has_build or has_project_abstraction:
            return ["feature_for_existing_project", "refactor_existing_stack"]
        return ["new_project_abstraction"]

    def _refresh_create_mode_options(self, reason: str = "create") -> None:
        if getattr(self, "_create_mode_values_refreshing", False):
            return
        self._create_mode_values_refreshing = True
        try:
            values = self._create_available_modes()
            box = getattr(self, "create_mode_box", None)
            if box is not None:
                try:
                    box.configure(values=values)
                except Exception:
                    pass
            current = self.create_mode.get() or "new_project_abstraction"
            if current not in values:
                fallback = "feature_for_existing_project" if "feature_for_existing_project" in values else values[0]
                self.create_mode.set(fallback)
                if hasattr(self, "create_terminal_text"):
                    self._append_create_terminal(f"[create-mode] {reason}: mode switched to {fallback}; current base evidence allows {', '.join(values)}")
        finally:
            self._create_mode_values_refreshing = False

    def _ensure_create_mode_matches_start_reference(self, reason: str = "create") -> None:
        self._refresh_create_mode_options(reason)
        mode = self.create_mode.get()
        has_start = self._has_start_tab_target_match()
        has_build = bool(self._active_successful_create_build_for_current_stack())
        has_project = bool(getattr(self, "_create_project_first_mode", False) or getattr(self, "_create_project_scope_snapshot", None) or getattr(self, "_create_project_source_base", None))
        manual_placeholder_block = self._create_unmount_blocks_start_base()
        if mode in {"feature_for_existing_project", "refactor_existing_stack"} and not has_start and not has_build and not has_project:
            self.create_mode.set("new_project_abstraction")
            msg = "Create mode: New Project Abstraction — no Build.complete or Start-tab target match"
            self.create_project_mode_status.set(msg)
            if hasattr(self, "create_terminal_text"):
                self._append_create_terminal(f"[create-mode] {reason}: downgraded to new_project_abstraction; no Build.complete/current-stack base or Start-tab target match")
        if mode == "new_project_abstraction" and (has_start or has_build or has_project) and not manual_placeholder_block:
            self._clear_manual_create_override_if_real_start_base(reason)
            self.create_mode.set("feature_for_existing_project")
            self.create_project_mode_status.set("Create mode: feature for existing project — existing project evidence; New Project Abstraction hidden")
        self._refresh_create_export_button_visibility() if hasattr(self, "create_terminal_text") else None

    def _create_run_mode_snapshot(self) -> str:
        return str(getattr(self, "_create_current_run_mode", "") or self.create_mode.get() or "new_project_abstraction")

    def _create_run_stack_snapshot(self) -> str:
        return str(getattr(self, "_create_current_run_stack", "") or self.create_stack.get() or "")

    def _create_run_work_dir_snapshot(self) -> Path:
        """Return the root that was actually used for the running timeline.

        This is intentionally not recomputed from the current Project Tree / Export
        tab state. A tree-source toggle after or during a run must not move the
        Build.complete pointer to a freshly materialized preview root.
        """
        for raw in (
            getattr(self, "_create_current_run_preview_root", None),
            getattr(self, "_create_terminal_workdir", None),
            getattr(self, "_create_tree_temp_root", None),
        ):
            if not raw:
                continue
            try:
                root = Path(raw).resolve()
                if root.exists():
                    return root
            except Exception:
                continue
        return self._create_terminal_work_dir()

    def _build_complete_preview_clone_root(self, record: dict) -> Path:
        """Return the stable preview-clone root for a completed Create build."""
        record_id = self._create_safe_slug(str(record.get("id") or "build"), "build")
        project_slug = self._create_safe_slug(str(record.get("project_name") or record.get("stack") or self.project_name.get() or "project"), "project")
        return (prompt_guide_runtime_root() / "create-preview" / f"{project_slug}_{record_id}_preview_clone").resolve()

    def _promote_build_complete_into_preview_clone(self, record: dict, config: dict | None = None) -> dict:
        """Clone a successful Build.complete root into a dedicated preview clone.

        A freshly created abstraction becomes a real project after Build.complete.
        From this point on Export, Prompt Builder and Feature/Refactor must read a
        project-shaped preview clone, not the transient terminal cwd or the normal
        Start Project Root. This mirrors the ProjectRoot -> Create clone handoff and
        gives the Export tree one durable Build.complete base to render.
        """
        if not isinstance(record, dict):
            return record
        if str(record.get("mode") or "") == "new_project_abstraction":
            # A New Abstraction build installs dependencies into the abstraction
            # root itself.  Do not promote Build.complete to a package-less clone.
            raw_source = str(record.get("temp_preview_dir") or "").strip()
            if raw_source:
                try:
                    source_root = Path(raw_source).expanduser().resolve()
                    if source_root.exists() and source_root.is_dir():
                        record["build_complete_source_dir"] = str(source_root)
                        record["preview_clone_dir"] = ""
                except Exception:
                    pass
            return record
        raw_source = str(record.get("temp_preview_dir") or "").strip()
        if not raw_source:
            return record
        try:
            source_root = Path(raw_source).expanduser().resolve()
        except Exception:
            return record
        if not source_root.exists() or not source_root.is_dir():
            return record
        try:
            clone_root = self._build_complete_preview_clone_root(record)
            if clone_root == source_root:
                return record
            # Never place the clone inside the source tree. A sibling below the
            # Prompt-Guide create-preview runtime avoids recursive preview loops.
            try:
                clone_root.relative_to(source_root)
                return record
            except Exception:
                pass
            export_dir = self._create_export_path().resolve()
            self._progress_callback("Build.complete Preview Clone: reading completed project", None, 0)
            scope = build_project_scope(source_root, export_dir=export_dir, progress_callback=self._progress_callback)
            manifest = clone_project_scope_to_directory(
                source_root,
                clone_root,
                scope,
                export_dir=export_dir,
                include_dependency_manifests=True,
                write_manifest=True,
                manifest_name="BUILD_COMPLETE_PREVIEW_CLONE_MANIFEST.json",
                progress_callback=self._progress_callback,
            )
            manifest["mode"] = "build_complete_preview_clone"
            manifest["build_complete_id"] = str(record.get("id") or "")
            manifest["project_name"] = str(record.get("project_name") or "")
            manifest["source_build_root"] = str(source_root)
            manifest["preview_clone_root"] = str(clone_root)
            manifest_path = clone_root / "BUILD_COMPLETE_PREVIEW_CLONE_MANIFEST.json"
            try:
                manifest_path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
            except Exception:
                pass
            record["build_complete_source_dir"] = str(source_root)
            record["preview_clone_dir"] = str(clone_root)
            record["temp_preview_dir"] = str(clone_root)
            record["preview_clone_manifest"] = manifest
            record["preview_clone_manifest_path"] = str(manifest_path)
            self._create_source_clone_manifest = manifest
            self._create_last_source_clone_signature = str(manifest.get("source_base") or source_root)
            self._create_source_loaded_signature = f"build_complete:{record.get('id') or clone_root}"
            self._create_source_mount_signature = self._create_source_loaded_signature
            try:
                copied = manifest.get("copied_file_count", manifest.get("file_count", 0))
                self.create_source_clone_status.set(f"Source clone: Build.complete preview clone mounted, {copied} file(s) → {clone_root}")
            except Exception:
                pass
            self._progress_callback("Build.complete Preview Clone: ready", 1, 1)
        except Exception as exc:
            try:
                self.create_source_clone_status.set(f"Build.complete preview clone skipped: {exc}")
            except Exception:
                pass
            self._set_progress(f"Build.complete preview clone skipped: {exc}", 0)
        return record

    def _promote_completed_build_to_feature_mode(self, record: dict) -> None:
        """After a New Abstraction build succeeds, continue from that build as Feature mode."""
        stack = str(record.get("stack") or "")
        raw_root = str(record.get("temp_preview_dir") or "")
        try:
            root = Path(raw_root).resolve()
        except Exception:
            root = None  # type: ignore[assignment]
        if root is not None and root.exists():
            self._create_tree_temp_root = root
            self._create_tree_temp_signature = self._create_tree_temp_signature_value()
            try:
                self.create_temp_preview_dir.set(str(root))
            except Exception:
                pass
        if stack and stack == self.create_stack.get():
            if self.create_mode.get() != "feature_for_existing_project":
                self.create_mode.set("feature_for_existing_project")
            try:
                self.create_stack_category.set(self._resolved_create_stack_category(record=record))
            except Exception:
                pass
            self.create_project_mode_status.set("Create mode: feature for existing project — Build.complete is primary base; Custom-first Mapping active")
        # Build.complete updates Create active state, but does not rewrite
        # Generator target rows. Generator sync remains explicit/parent-owned.
        self._refresh_create_mode_options("build_complete")
        self._refresh_create_context_variable_menu()
        self._refresh_prompt_builder_context_variable_menu()
        self._refresh_create_export_button_visibility()

    def _record_create_timeline_complete_for_current_mode(self) -> None:
        run_mode = self._create_run_mode_snapshot()
        # A successful timeline must create Build.complete whenever there is no
        # active completed base yet. Feature/Refactor runs with an existing base
        # stay repeatable mode runs and do not overwrite that base.
        if run_mode == "new_project_abstraction" or not self._active_successful_create_build_for_current_stack():
            self._record_create_timeline_build_success()
            return
        self._record_create_mode_timeline_success(run_mode)

    def _record_create_mode_timeline_success(self, run_mode: str) -> None:
        """Record repeatable Feature/Refactor timeline completion without touching Build.complete."""
        record = self._create_build_record_payload("success")
        record["kind"] = "mode_timeline_run"
        record["mode"] = run_mode
        record["status"] = f"{run_mode}_complete"
        record["complete"] = False
        record["build_complete_state_unchanged"] = True
        record["completed_build_base"] = self._active_successful_create_build_for_current_stack()
        self._create_mode_run_records = (getattr(self, "_create_mode_run_records", []) + [record])[-100:]
        try:
            out = self._create_export_path() / "CREATE_MODE_TIMELINE_RUNS.json"
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_text(json.dumps(self._create_mode_run_records, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        except Exception:
            pass
        self.create_project_mode_status.set(f"Create mode: {run_mode.replace('_', ' ')} complete — Build.complete unchanged")
        self.create_builds_status.set(f"{run_mode.replace('_', ' ').title()} run complete; Build.complete unchanged")
        self._refresh_create_export_button_visibility()

    def _create_build_record_payload(self, status: str = "success") -> dict:
        config = self._current_create_config()
        now = datetime.now().isoformat(timespec="seconds")
        temp_dir = self._create_run_work_dir_snapshot()
        run_mode = self._create_run_mode_snapshot()
        run_stack = self._create_run_stack_snapshot()
        project_identity = self._create_abstraction_project_name(config) if run_mode == "new_project_abstraction" else (self.project_name.get().strip() or run_stack or DEFAULT_PROJECT_NAME)
        return {
            "id": hashlib.sha1(f"{now}|{temp_dir}|{run_stack}|{run_mode}".encode("utf-8", errors="ignore")).hexdigest()[:12],
            "created_at": now,
            "updated_at": now,
            "status": "complete" if status == "success" else status,
            "complete": status in {"success", "complete"},
            "mode": run_mode,
            "stack": run_stack,
            "project_name": project_identity,
            "category": self._resolved_create_stack_category(config),
            "temp_preview_dir": str(temp_dir),
            "preview_target_path": str(self._create_terminal_target_path()),
            "create_working_dir": str(self._create_working_dir()),
            "create_export_dir": str(self._create_export_path()),
            "timeline": list(self._create_running_timeline_by_index.values()) or self._selected_create_timeline_lines(),
            "mapping": self._create_project_mapping_payload(config),
            "mode_context": config.get("create_mode_context", self._create_mode_context()),
            "exportable_until": "application_restart_or_close",
        }

    def _create_build_complete_manifest(self, record: dict, config: dict | None = None) -> dict:
        """Manifest written when New Project Abstraction finishes successfully.

        Feature/Refactor catalogs should depend on this project evidence instead
        of going back to the original boilerplate stack catalog.
        """
        config = config or self._current_create_config()
        try:
            mapping = self._create_project_mapping_payload(config)
        except Exception:
            mapping = {}
        try:
            dependency_layer = self._effective_dependency_layer(config)
        except Exception:
            dependency_layer = []
        try:
            target_relations = self._create_target_root_relations() if hasattr(self, "create_preview_tree") else {}
        except Exception:
            target_relations = {}
        try:
            shortcut_roots = {key: str(value) for key, value in self._create_context_roots(record).items() if key.startswith("@")}
        except Exception:
            shortcut_roots = {}
        return {
            "artifact": "CREATE_BUILD_COMPLETE_MANIFEST.json",
            "schema_version": "create-build-complete.v2-custom-first",
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "build_id": record.get("id"),
            "mode": "new_project_abstraction",
            "source_base": record.get("temp_preview_dir"),
            "create_working_dir": record.get("create_working_dir"),
            "create_export_dir": record.get("create_export_dir"),
            "project": {
                "name": record.get("project_name") or (self._create_abstraction_project_name(config) if str(record.get("mode") or "") == "new_project_abstraction" else self.project_name.get()),
                "category": self._resolved_create_stack_category(config, record),
                "target_path": config.get("path", self.create_target_path.get()),
                "path_type": config.get("path_type", self.create_build_target.get()),
                "build_target": config.get("build_target", self.create_build_target.get()),
                "file_types": config.get("file_types", []),
            },
            "dependency_layer": dependency_layer,
            "target_relations": target_relations,
            "shortcut_roots": shortcut_roots,
            "mapping": mapping,
            "timeline": record.get("timeline", []),
            "profiles": config.get("profiles", []),
            "references": config.get("references", []),
            "roles": config.get("roles", []),
            "weights": config.get("create_weight_profiles", []),
            "validation_posture": {
                "compiler_rows": getattr(self, "_create_compiler_rows", []),
                "dependency_rows": getattr(self, "_create_dependency_rows", []),
                "notes": "Feature/Refactor modes must use this manifest as project evidence and must not rebuild boilerplate stack entries.",
            },
        }

    def _write_build_complete_manifest(self, record: dict, config: dict | None = None) -> Path | None:
        manifest = record.get("build_complete_manifest")
        if not isinstance(manifest, dict):
            manifest = self._create_build_complete_manifest(record, config)
            record["build_complete_manifest"] = manifest
        locations: list[Path] = []
        try:
            root = Path(str(record.get("temp_preview_dir") or "")).resolve()
            if root.exists():
                locations.append(root / "output" / "create-export" / "CREATE_BUILD_COMPLETE_MANIFEST.json")
        except Exception:
            pass
        try:
            export_dir = self._create_export_path()
            locations.append(export_dir / "CREATE_BUILD_COMPLETE_MANIFEST.json")
        except Exception:
            pass
        first: Path | None = None
        for path in locations:
            try:
                path.parent.mkdir(parents=True, exist_ok=True)
                path.write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
                if first is None:
                    first = path
            except Exception:
                pass
        if first is not None:
            record["build_manifest_path"] = str(first)
        return first

    def _record_create_timeline_build_success(self) -> None:
        record = self._create_build_record_payload("success")
        record["kind"] = "build_complete"
        config = self._current_create_config()
        if str(record.get("mode") or "") == "new_project_abstraction":
            identity = str(record.get("project_name") or self._create_abstraction_project_name(config)).strip()
            record["project_name"] = identity
            try:
                self.project_name.set(identity)
            except Exception:
                pass
        record = self._promote_build_complete_into_preview_clone(record, config)
        record["build_complete_manifest"] = self._create_build_complete_manifest(record, config)
        self._write_build_complete_manifest(record, config)
        root = Path(str(record.get("temp_preview_dir", "")))
        if root.exists():
            resolved = root.resolve()
            self._create_successful_temp_roots.add(str(resolved))
            self._create_tree_temp_root = resolved
            self._create_tree_temp_signature = self._create_tree_temp_signature_value()
            try:
                self.create_temp_preview_dir.set(str(resolved))
            except Exception:
                pass
        existing = [item for item in self._create_successful_builds if str(item.get("temp_preview_dir")) != str(record.get("temp_preview_dir"))]
        existing.append(record)
        self._create_successful_builds = existing[-50:]
        self._create_last_successful_build = record
        stack_key = str(record.get("stack") or self.create_stack.get())
        if stack_key:
            self._create_successful_builds_by_stack[stack_key] = record
        try:
            out = self._create_export_path() / "CREATE_SUCCESSFUL_BUILDS.json"
            out.parent.mkdir(parents=True, exist_ok=True)
            out.write_text(json.dumps(self._create_successful_builds, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
        except Exception:
            pass
        self.create_builds_status.set(f"Build.complete persisted: {record['id']} — {record['temp_preview_dir']}")
        was_new_abstraction = str(record.get("mode") or "") == "new_project_abstraction"
        self._promote_completed_build_to_feature_mode(record)
        try:
            self._sync_generator_targets_from_build_complete(record, config)
            self._refresh_prompt_builder_context_variable_menu()
            self._set_progress("Generator/Prompt Builder targets synchronized from Build.complete", 1, 1)
        except Exception as exc:
            self._set_progress(f"Generator target sync skipped after Build.complete: {exc}", 0)
        try:
            self.create_stack_category.set(self._resolved_create_stack_category(config, record))
        except Exception:
            pass
        if self._active_successful_create_build_for_current_stack():
            # Build.complete makes Create Working Dir available for Export and
            # performs one automatic handoff to Create Export. This handoff is
            # selection-only/read-only; it does not reset, clone or overwrite
            # Create state, and the user may switch back afterwards.
            try:
                self._auto_select_create_working_dir_once("build_complete")
                self._refresh_project_tree_source_options()
                self._refresh_export_settings_visibility()
                self._update_project_tree_status()
                if self._use_create_working_dir_for_project_tree():
                    self._refresh_project_tree(force_scan=True, reason="build_complete_preview_clone_ready")
            except Exception:
                pass
        self._refresh_prompt_builder_context_variable_menu()
        try:
            self._schedule_prompt_builder_flow_refresh()
        except Exception:
            pass
        self._refresh_create_builds_tab()
        self._refresh_create_export_button_visibility()
        self._refresh_create_stack_control_state()

    def _refresh_create_builds_tab(self) -> None:
        tree = getattr(self, "create_builds_tree", None)
        if tree is None:
            return
        try:
            for item in tree.get_children():
                tree.delete(item)
            for record in self._create_successful_builds:
                tree.insert("", "end", iid=str(record.get("id")), values=(
                    record.get("status", ""),
                    record.get("mode", ""),
                    record.get("stack", ""),
                    record.get("temp_preview_dir", ""),
                    record.get("create_export_dir", ""),
                    record.get("updated_at", record.get("created_at", "")),
                ))
        except Exception:
            pass

    def _selected_create_build_record(self) -> dict | None:
        tree = getattr(self, "create_builds_tree", None)
        if tree is not None:
            try:
                sel = tree.selection()
                if sel:
                    wanted = str(sel[0])
                    for record in self._create_successful_builds:
                        if str(record.get("id")) == wanted:
                            return record
            except Exception:
                pass
        return self._create_last_successful_build

    def _open_selected_create_build_path(self) -> None:
        record = self._selected_create_build_record()
        if not record:
            messagebox.showinfo("No build", "No successful Create timeline build is available yet.")
            return
        path = Path(str(record.get("temp_preview_dir") or record.get("create_working_dir") or "."))
        try:
            if platform.system().lower().startswith("win"):
                os.startfile(str(path))  # type: ignore[attr-defined]
            elif platform.system().lower() == "darwin":
                _popen_subprocess_hidden(["open", str(path)])
            else:
                _popen_subprocess_hidden(["xdg-open", str(path)])
        except Exception as exc:
            messagebox.showerror("Open build failed", str(exc))

    def _create_has_mounted_state(self) -> bool:
        try:
            if self._active_successful_create_build_for_current_stack() or self._selected_create_build_record():
                return True
        except Exception:
            pass
        state_values = [
            getattr(self, "_create_source_clone_manifest", None),
            getattr(self, "_create_last_source_clone_signature", ""),
            getattr(self, "_create_source_mount_signature", ""),
            getattr(self, "_create_source_loaded_signature", ""),
            getattr(self, "_create_tree_temp_root", None),
        ]
        try:
            state_values.append(self.create_temp_preview_dir.get().strip())
        except Exception:
            pass
        return any(bool(value) for value in state_values)



    def _create_unmount_blocks_start_base(self, base: Path | None = None) -> bool:
        """Return True only for the detached placeholder Start root.

        Manual Unmount should suppress the automatic Create mount only while the
        Start tab still points at the reset/default placeholder root. It must not
        globally hide existing-project modes after the user selects or scans a
        real Project Root again.
        """
        if not bool(getattr(self, "_create_manual_new_project_override", False)):
            return False
        try:
            base_path = Path(base or self._normalize_start_working_tree()).resolve()
            base_signature = str(base_path)
        except Exception:
            base_signature = str(base or self.output_base.get() or "")
        manual_signature = str(getattr(self, "_create_manual_unmount_start_signature", "") or "")
        try:
            default_signature = str(default_start_worktree_dir().resolve())
        except Exception:
            default_signature = ""
        return bool(base_signature and (base_signature == default_signature or (manual_signature and base_signature == manual_signature)))

    def _clear_manual_create_override_if_real_start_base(self, reason: str = "start_base") -> None:
        """Re-enable normal Create mode sync when Start points at real evidence."""
        if not bool(getattr(self, "_create_manual_new_project_override", False)):
            return
        try:
            base = self._normalize_start_working_tree().resolve()
        except Exception:
            return
        if self._create_unmount_blocks_start_base(base):
            return
        try:
            has_real_base = base.exists() and base.is_dir() and not self._path_is_under_system_temp(base) and self._path_has_project_evidence(base)
        except Exception:
            has_real_base = False
        if not has_real_base and not bool(getattr(self, "_create_project_first_mode", False)):
            return
        self._create_manual_new_project_override = False
        self._create_manual_unmount_start_signature = ""
        self._create_last_scope_sync_signature = None
        try:
            self._append_create_terminal(f"[create-mode] {reason}: manual unmount override cleared; real Start project evidence is active again")
        except Exception:
            pass

    def _reset_unmount_session_defaults(self, reason: str = "manual_unmount") -> None:
        """Reset volatile project/Create session state to startup defaults.

        Unmount is a session detach operation. It must not rewrite persisted app
        settings, UI preferences or Generator-owned target rows, but it should
        clear the currently loaded project identity, Create clone/build state and
        Export Tree source so the next workflow starts from a clean default.
        """
        self._unmount_reset_in_progress = True
        try:
            for attr in ("_create_source_load_retry_after", "_create_worktree_refresh_after", "_create_preview_after"):
                pending = getattr(self, attr, None)
                if pending:
                    try:
                        self.after_cancel(pending)
                    except Exception:
                        pass
                    try:
                        setattr(self, attr, None)
                    except Exception:
                        pass
            default_root = default_start_worktree_dir()
            try:
                self.output_base.set(str(default_root))
                self._last_start_project_root_value = str(default_root.resolve())
                if str(reason or "").startswith("manual_unmount") or reason in {"create_build_unmounted"}:
                    self._create_manual_new_project_override = True
                    self._create_manual_unmount_start_signature = str(default_root.resolve())
            except Exception:
                pass
            try:
                self.project_name.set(DEFAULT_PROJECT_NAME)
            except Exception:
                pass
            try:
                self.project_tree_source_mode.set("normal_working_tree")
            except Exception:
                pass
            try:
                self._refresh_project_tree_source_options()
            except Exception:
                pass
            try:
                self.create_mode.set("new_project_abstraction")
            except Exception:
                pass
            try:
                self.create_stack_category.set(DEFAULT_CREATE_STACK_CATEGORY)
            except Exception:
                pass
            try:
                self.create_stack.set(DEFAULT_CREATE_STACK)
            except Exception:
                pass
            try:
                self.create_target_path.set(DEFAULT_CREATE_TARGET_PATH)
            except Exception:
                pass
            try:
                self.create_build_target.set(DEFAULT_CREATE_BUILD_TARGET)
            except Exception:
                pass
            for var_name, value in (
                ("create_dependencies", ""),
                ("create_working_path", ""),
                ("create_project_source_path", ""),
                ("create_temp_preview_dir", ""),
                ("create_current_run_id", ""),
            ):
                try:
                    var = getattr(self, var_name)
                    if hasattr(var, "set"):
                        var.set(value)
                except Exception:
                    pass
            self._create_successful_builds = []
            self._create_successful_builds_by_stack = {}
            self._create_last_successful_build = None
            self._create_successful_temp_roots = set()
            self._create_mode_run_records = []
            self._create_current_run_id = ""
            self._create_current_run_mode = ""
            self._create_current_run_stack = ""
            self._create_current_run_preview_root = None
            try:
                self.create_source_clone_status.set("Source clone: idle")
            except Exception:
                pass
            try:
                self.create_project_mode_status.set(f"Create mode: new project abstraction — defaults restored ({reason})")
            except Exception:
                pass
            try:
                self.create_builds_status.set("No successful Create timeline build yet.")
            except Exception:
                pass
        finally:
            self._unmount_reset_in_progress = False

    def _clear_create_mount_state(self, reason: str = "unmount", record: dict | None = None, *, remove_record: bool = True, refresh: bool = True) -> bool:
        """Detach current Create mount/build state without depending on Build.complete."""
        cleared = False
        if record and remove_record:
            rec_id = str(record.get("id") or "")
            stack = str(record.get("stack") or self.create_stack.get() or "")
            if rec_id:
                self._create_successful_builds = [item for item in getattr(self, "_create_successful_builds", []) if str(item.get("id") or "") != rec_id]
                cleared = True
            if isinstance(getattr(self, "_create_successful_builds_by_stack", None), dict) and stack:
                self._create_successful_builds_by_stack.pop(stack, None)
            if getattr(self, "_create_last_successful_build", None) is record or str(getattr(self, "_create_last_successful_build", {}).get("id", "")) == rec_id:
                self._create_last_successful_build = None
            raw_root = str(record.get("temp_preview_dir") or "")
            if raw_root:
                try:
                    self._create_successful_temp_roots.discard(str(Path(raw_root).resolve()))
                except Exception:
                    pass
        if self._create_has_mounted_state() or cleared:
            cleared = True
        self._reset_create_source_state()
        if reason in {"manual_unmount", "create_build_unmounted", "start_project_root_changed", "working_tree_changed", "working_tree_reloaded", "project_root_reload"}:
            self._invalidate_create_clone_for_next_create_tab(reason)
        if reason in {"manual_unmount", "create_build_unmounted"}:
            self._create_manual_new_project_override = True
            try:
                self._create_manual_unmount_start_signature = str(self._normalize_start_working_tree().resolve())
            except Exception:
                self._create_manual_unmount_start_signature = str(self.output_base.get() or "")
        elif reason in {"start_project_root_changed", "working_tree_changed"}:
            self._create_manual_new_project_override = False
            self._create_manual_unmount_start_signature = ""
        if reason in {"manual_unmount", "create_build_unmounted"}:
            self._reset_unmount_session_defaults(reason)
        else:
            try:
                self.create_mode.set("new_project_abstraction")
            except Exception:
                pass
        # Do not mutate Generator target rows from Create unmount/reset.
        # Unmount only clears Create mount state and active Create mode.
        try:
            self._cleanup_create_temp_tree(force=True)
        except Exception:
            pass
        self._create_tree_temp_root = None
        self._create_tree_temp_signature = ""
        try:
            self.create_temp_preview_dir.set("")
        except Exception:
            pass
        try:
            self.create_project_source_path.set("")
        except Exception:
            pass
        if reason in {"start_project_root_changed", "working_tree_changed", "manual_unmount", "create_build_unmounted"}:
            try:
                self.create_working_path.set("")
            except Exception:
                pass
        if refresh:
            try:
                self.create_project_mode_status.set(f"Create mode: new project abstraction — unmounted ({reason})")
            except Exception:
                pass
            try:
                self._invalidate_project_tree_cache(reason)
            except Exception:
                pass
            try:
                self._refresh_create_builds_tab()
            except Exception:
                pass
            try:
                self._refresh_project_tree_source_options()
            except Exception:
                pass
            try:
                self._refresh_create_export_button_visibility()
            except Exception:
                pass
            try:
                self._refresh_create_stack_control_state()
            except Exception:
                pass
            try:
                self._schedule_create_preview_refresh()
            except Exception:
                pass
        return cleared

    def _unmount_current_create_build(self) -> None:
        """Detach the current Create mount; Build.complete is optional."""
        record = self._active_successful_create_build_for_current_stack() or self._selected_create_build_record()
        if not record and not self._create_has_mounted_state():
            messagebox.showinfo("No Create build mounted", "There is no current Create mount or Build.complete record to unmount.")
            return
        self._clear_create_mount_state("manual_unmount", record, remove_record=bool(record), refresh=True)
        try:
            self._refresh_project_tree(force_scan=True, reason="create_build_unmounted")
        except Exception:
            pass
        # Project Tree refresh can derive the name from its current base; Unmount
        # must win and leave the visible session identity at default.
        try:
            self._reset_unmount_session_defaults("manual_unmount_complete")
        except Exception:
            pass
        try:
            self._refresh_project_tree_source_options()
        except Exception:
            pass

    def _can_export_create_context(self) -> bool:
        return bool(self._active_successful_create_build_for_current_stack() or self._has_start_tab_target_match())

    def _refresh_create_export_button_visibility(self) -> None:
        visible = self._can_export_create_context()
        # The Create Export button is intentionally hidden until there is either
        # a Build.complete for the current stack or a Start-tab project reference
        # that matches the selected target. This prevents exporting empty temp
        # default projects as if they were verified Create bases.
        for name, options in []:
            widget = getattr(self, name, None)
            if widget is None:
                continue
            try:
                if visible:
                    if not widget.winfo_manager():
                        widget.pack(**options)
                    widget.configure(state="normal")
                else:
                    widget.pack_forget()
            except Exception:
                pass
        build_button = getattr(self, "create_builds_export_button", None)
        if build_button is not None:
            try:
                build_button.configure(state=("normal" if getattr(self, "_create_successful_builds", []) else "disabled"))
            except Exception:
                pass

    def _create_export_base_for_record(self, record: dict | None) -> Path:
        if record and record.get("temp_preview_dir"):
            try:
                root = Path(str(record.get("temp_preview_dir"))).resolve()
                if root.exists():
                    return root
            except Exception:
                pass
        if not self._use_create_working_dir_for_project_tree():
            return self._normalize_start_working_tree().resolve()
        active = self._active_successful_create_build_for_current_stack()
        if active and active.get("temp_preview_dir"):
            try:
                root = Path(str(active.get("temp_preview_dir"))).resolve()
                if root.exists():
                    return root
            except Exception:
                pass
        if self._has_start_tab_target_match():
            try:
                base = Path(self.output_base.get() or ".").expanduser().resolve()
                rel = self._create_target_relative_path()
                if str(rel) not in {".", ""}:
                    candidate = (base / rel).resolve()
                    candidate.relative_to(base)
                    if candidate.exists():
                        return candidate
                return base
            except Exception:
                pass
        return self._create_working_dir()

    def _create_context_roots(self, build_record: dict | None = None) -> dict[str, Path]:
        record_root = None
        if build_record and build_record.get("temp_preview_dir"):
            try:
                candidate = Path(str(build_record.get("temp_preview_dir"))).resolve()
                if candidate.exists():
                    record_root = candidate
            except Exception:
                record_root = None
        root = record_root or self._completed_create_build_root_for_current_stack() or self._active_create_build_root() or self._create_temp_root()
        roots: dict[str, Path] = {
            "@root": root,
            "@wrapper": root,
            "@build_temp": root,
            "@create_working_dir": self._create_working_dir(),
            "@export_dir": self._create_export_path(),
        }
        # Prefer explicit root roles from the Create Mapping tree. If a row says
        # frontend_root/backend_root, @frontend/@backend points there. If not, the
        # shortcut still resolves to the build root so @backend/foo.py is never a
        # broken textual placeholder.
        try:
            for row in self._create_preview_tree_model():
                target = str(row.get("effective_target") or "").strip().lower()
                rel = str(row.get("path") or "").strip().replace("\\", "/").strip("/")
                role = str(row.get("role") or "")
                if not target or target == "ignored":
                    continue
                key = "@" + target
                if role.endswith("_root") or key not in roots:
                    roots[key] = (root / rel).resolve() if rel and rel != "." else root
        except Exception:
            pass
        for key in ("@frontend", "@backend", "@generated", "@assets"):
            roots.setdefault(key, root)
        return roots

    def _create_context_variable_map(self) -> dict[str, str]:
        roots = self._create_context_roots()
        result: dict[str, str] = {key: str(value) for key, value in roots.items()}
        result.update({
            "@stack": self.create_stack.get(),
            "@mode": self.create_mode.get(),
        })
        deps: list[str] = []
        try:
            for row in self._create_dependency_rows:
                pkg = str(row.get("package") or "").strip()
                if pkg and pkg not in deps:
                    deps.append(pkg)
        except Exception:
            pass
        result["@dependencies"] = ", ".join(deps) if deps else str(self.create_dependencies.get() or "")
        mode_catalog = self._create_mode_catalog(self._current_create_config())
        result["@catalog_mode"] = json.dumps(mode_catalog.get("active_catalog", {}), ensure_ascii=False)
        result["@catalog_stack"] = json.dumps(mode_catalog.get("new_project_abstraction", {}), ensure_ascii=False)
        result["@catalog_feature"] = json.dumps(mode_catalog.get("feature_for_existing_project", {}), ensure_ascii=False)
        result["@catalog_refactor"] = json.dumps(mode_catalog.get("refactor_existing_stack", {}), ensure_ascii=False)
        result["@catalog_chain"] = json.dumps(mode_catalog.get("chain_schema", {}), ensure_ascii=False)
        result["@parameter_context"] = json.dumps(mode_catalog.get("chain_schema", {}).get("parameter_context", {}), ensure_ascii=False)
        result["@parameter_boilerplates"] = json.dumps(mode_catalog.get("chain_schema", {}).get("parameter_boilerplates", []), ensure_ascii=False)
        result["@boilerplates"] = json.dumps(mode_catalog.get("active_catalog", {}).get("boilerplates") or mode_catalog.get("chain_schema", {}).get("boilerplates", []), ensure_ascii=False)
        result["@feature_boilerplates"] = json.dumps(mode_catalog.get("feature_for_existing_project", {}).get("boilerplates", []), ensure_ascii=False)
        result["@refactor_boilerplates"] = json.dumps(mode_catalog.get("refactor_existing_stack", {}).get("boilerplates", []), ensure_ascii=False)
        # Add direct file shortcuts for existing/projected files so the prompt tab
        # becomes useful: @frontend/src/App.vue or @backend/app/main.py preview to
        # the concrete path while remaining easy to type manually.
        try:
            root_info = self._create_target_root_relations()
            for row in self._create_preview_tree_model():
                if row.get("ignored"):
                    continue
                target = str(row.get("effective_target") or "").strip().lower()
                if not target or target == "ignored":
                    continue
                rel = str(row.get("path") or "").strip().replace("\\", "/").strip("/")
                if not rel or rel == ".":
                    continue
                info = root_info.get(target, {})
                root_rel = str(info.get("root_rel") or "").strip("/")
                target_root = Path(str(result.get("@" + target) or roots.get("@" + target) or roots.get("@root")))
                try:
                    suffix = Path(rel).relative_to(Path(root_rel)).as_posix() if root_rel else Path(rel).name
                except Exception:
                    suffix = Path(rel).name
                if suffix and suffix != ".":
                    result.setdefault("@" + target + "/" + suffix, str((target_root / suffix).resolve()))
        except Exception:
            pass
        return result

    def _create_target_root_relations(self) -> dict[str, dict]:
        relations: dict[str, dict] = {}
        try:
            for row in self._create_preview_tree_model():
                target = str(row.get("effective_target") or "").strip().lower()
                role = str(row.get("role") or "")
                rel = str(row.get("path") or "").strip().replace("\\", "/").strip("/")
                if target and target != "ignored" and role.endswith("_root"):
                    relations[target] = {"root_rel": rel, "role": role, "boilerplate_reference": row.get("boilerplate"), "boilerplate": row.get("boilerplate")}
            for row in self._create_preview_tree_model():
                target = str(row.get("effective_target") or "").strip().lower()
                rel = str(row.get("path") or "").strip().replace("\\", "/").strip("/")
                if target and target != "ignored" and target not in relations and rel:
                    first = rel.split("/", 1)[0]
                    relations[target] = {"root_rel": first, "role": "inferred_root", "boilerplate_reference": row.get("boilerplate"), "boilerplate": row.get("boilerplate")}
        except Exception:
            pass
        return relations

    def _resolve_create_context_token(self, token: str, build_record: dict | None = None) -> str:
        raw = str(token or "").strip()
        if not raw.startswith("@"):
            return raw
        roots = self._create_context_roots(build_record)
        match = re.match(r"^(@[A-Za-z0-9_-]+)(?:/(.*))?$", raw)
        if not match:
            return self._create_context_variable_map().get(raw, raw)
        key, suffix = match.group(1), match.group(2) or ""
        if key in roots:
            base = roots[key]
            if suffix:
                safe = Path(*[part for part in suffix.replace("\\", "/").split("/") if part and part not in {".", ".."}])
                return str((base / safe).resolve())
            return str(base)
        return self._create_context_variable_map().get(raw, raw)

    def _resolve_create_context_shortcuts(self, text: str, build_record: dict | None = None) -> str:
        if not text:
            return ""
        pattern = re.compile(r"(?<![\w.])@[A-Za-z0-9_-]+(?:/[A-Za-z0-9_.@+\-=,()[\]{} ]+)?")
        # Stop path capture at common prose separators.
        stop_chars = set('`"\'<>|')
        def clean_token(value: str) -> tuple[str, str]:
            token = value
            trailer = ""
            while token and (token[-1].isspace() or token[-1] in ",;:!?)]."):
                trailer = token[-1] + trailer
                token = token[:-1]
            # Keep only the first whitespace-separated part for path shortcuts.
            if " " in token:
                first, rest = token.split(" ", 1)
                return first, " " + rest + trailer
            return token, trailer
        def repl(match: re.Match) -> str:
            token, trailer = clean_token(match.group(0))
            resolved = self._resolve_create_context_token(token, build_record)
            return resolved + trailer
        return pattern.sub(repl, text)

    def _create_shortcut_reference_rows(self, text: str = "", build_record: dict | None = None) -> list[dict]:
        rows: list[dict] = []
        seen: set[str] = set()
        source = text or "\n".join([self.create_details_text.get("1.0", "end") if hasattr(self, "create_details_text") else ""])
        for match in re.finditer(r"(?<![\w.])@[A-Za-z0-9_-]+(?:/[A-Za-z0-9_.@+\-=,()[\]{}-]+)?", source):
            token = match.group(0).rstrip(",;:!?)].")
            if token in seen:
                continue
            seen.add(token)
            resolved = self._resolve_create_context_token(token, build_record)
            exists = False
            kind = "value"
            try:
                p = Path(resolved)
                exists = p.exists()
                kind = "dir" if p.is_dir() else ("file" if p.is_file() else "path")
            except Exception:
                pass
            rows.append({"token": token, "resolved": resolved, "exists": exists, "kind": kind})
        return rows

    def _create_project_evidence_payload(self, config: dict | None = None, build_record: dict | None = None) -> dict:
        """Project facts available to Feature/Refactor modes.

        This deliberately prefers Build.complete manifests and real Start-tab
        project evidence. Boilerplate stack data is only a New Project
        Abstraction input; Feature/Refactor plans use the already-created or
        already-scanned project facts.
        """
        config = config or {}
        record = build_record or self._active_successful_create_build_for_current_stack() or {}
        manifest = record.get("build_complete_manifest") if isinstance(record, dict) else None
        if not isinstance(manifest, dict):
            try:
                raw = record.get("build_manifest_path") if isinstance(record, dict) else ""
                if raw and Path(str(raw)).exists():
                    manifest = json.loads(Path(str(raw)).read_text(encoding="utf-8"))
            except Exception:
                manifest = None
        roots = {key: str(value) for key, value in self._create_context_roots(record if isinstance(record, dict) else None).items() if key.startswith("@")}
        dependency_layer = []
        target_relations = {}
        mapping = {}
        source = "none"
        source_base = ""
        if isinstance(manifest, dict):
            source = "build_complete_manifest"
            source_base = str(manifest.get("source_base") or record.get("temp_preview_dir") or "")
            dependency_layer = manifest.get("dependency_layer") or []
            target_relations = manifest.get("target_relations") or {}
            mapping = manifest.get("mapping") or {}
        elif self._has_start_tab_target_match():
            source = "start_tab_target_match"
            try:
                source_base = str(Path(self.output_base.get() or ".").expanduser().resolve())
            except Exception:
                source_base = str(self.output_base.get() or "")
            dependency_layer = self._effective_dependency_layer(config)
            target_relations = self._create_target_root_relations() if hasattr(self, "create_preview_tree") else {}
            try:
                mapping = self._create_project_mapping_payload(config)
            except Exception:
                mapping = {}
        else:
            dependency_layer = self._effective_dependency_layer(config)
            target_relations = self._create_target_root_relations() if hasattr(self, "create_preview_tree") else {}
        detected_targets = []
        for item in getattr(self, "_create_detected_targets", []) or []:
            if isinstance(item, dict):
                detected_targets.append({k: item.get(k) for k in ("path", "path_type", "stack", "evidence") if k in item})
        return {
            "source": source,
            "source_base": source_base,
            "has_build_complete": bool(record.get("complete") if isinstance(record, dict) else False),
            "build_id": record.get("id") if isinstance(record, dict) else "",
            "dependency_stack": dependency_layer,
            "target_relations": target_relations,
            "mapping": mapping,
            "detected_targets": detected_targets,
            "shortcut_roots": roots,
            "start_tab_target_match": self._has_start_tab_target_match(),
        }

    def _create_dependency_signal_set(self, dependency_layer: list | tuple | object, config: dict | None = None) -> set[str]:
        signals: set[str] = set()
        config = config or {}
        for value in [self.create_stack.get(), self.create_stack_category.get(), config.get("category"), config.get("path_type"), config.get("build_target")]:
            if value:
                signals.add(str(value).lower())
        for value in config.get("file_types", []) or []:
            signals.add(str(value).lower())
        for row in dependency_layer or []:
            if not isinstance(row, dict):
                continue
            for key in ("ecosystem", "manifest", "target", "validation_token", "install_token"):
                value = row.get(key)
                if value:
                    signals.add(str(value).lower())
            for key in ("dependencies", "manifest_files"):
                values = row.get(key) or []
                if isinstance(values, str):
                    values = [values]
                for value in values:
                    signals.add(str(value).lower())
            dep = row.get("package") or row.get("name")
            if dep:
                signals.add(str(dep).lower())
        try:
            for row in self._effective_dependency_rows(config):
                for key in ("ecosystem", "target", "manifest", "package"):
                    value = row.get(key)
                    if value:
                        signals.add(str(value).lower())
        except Exception:
            pass
        return signals

    def _create_plan_domains(self, evidence: dict, config: dict | None = None) -> list[str]:
        signals = self._create_dependency_signal_set(evidence.get("dependency_stack") or [], config)
        text = " ".join(sorted(signals))
        domains: list[str] = []
        def add(name: str, *needles: str) -> None:
            if any(needle in text for needle in needles) and name not in domains:
                domains.append(name)
        add("frontend_ui", "frontend", "vue", "react", "vite", "next", "svelte", "tsx", "jsx", "scss")
        add("backend_api", "backend", "fastapi", "flask", "dyesngo", "python", "api", "server")
        add("node_runtime", "node", "npm", "package.json", "typescript", "yesvascript")
        add("android_gradle", "android", "gradle", "kotlin", "yesva")
        add("flutter_app", "flutter", "dart", "pubspec")
        add("game_engine", "unity", "godot", "game", "webgl", "blender", "3d", "shader")
        add("data_ai", "data", "ai", "ml", "pandas", "notebook", "dataset")
        add("docs_content", "docs", "documentation", "markdown", "publishing", "content")
        if "frontend_ui" in domains and "backend_api" in domains and "fullstack_contract" not in domains:
            domains.insert(0, "fullstack_contract")
        if not domains:
            domains.append("generic_project")
        return domains

    def _create_chain_entry_modes(self, raw: dict) -> list[str]:
        """Resolve mode ownership for a chain boilerplate.

        Older schema files used ids such as ``feature_*`` and ``refactor_*`` but
        did not always set ``mode``/``modes``. Treating those entries as ``all``
        made the Feature and Refactor catalog look duplicated. This resolver
        keeps backward compatibility while enforcing distinct user-facing entry
        sets.
        """
        explicit = raw.get("modes") or ([] if raw.get("mode") in (None, "") else [raw.get("mode")])
        modes = [str(item).strip() for item in explicit if str(item).strip()]
        if modes:
            return modes
        entry_id = str(raw.get("id") or "").strip().lower()
        label = str(raw.get("label") or raw.get("display_name") or "").strip().lower()
        if entry_id.startswith("feature_") or label.startswith("feature:") or label.startswith("feature "):
            return ["feature_for_existing_project"]
        if entry_id.startswith("refactor_") or label.startswith("refactor:") or label.startswith("refactor "):
            return ["refactor_existing_stack"]
        return ["all"]

    def _project_credit_infoboxes(self) -> list[dict]:
        """Return editable Credits-to-Project infobox schemas."""
        rows: list[dict] = []
        for raw in self.schema.get("project_credit_infoboxes", []) if isinstance(getattr(self, "schema", {}), dict) else []:
            if not isinstance(raw, dict):
                continue
            item = dict(raw)
            item["id"] = str(item.get("id") or "").strip()
            item["label"] = str(item.get("label") or item.get("id") or "").strip()
            file_types = item.get("applies_to_file_types") or item.get("file_types") or []
            if isinstance(file_types, str):
                file_types = [file_types]
            item["applies_to_file_types"] = self._dedupe_create_list([str(value).strip() for value in file_types if str(value).strip()])
            extensions = item.get("extensions") or []
            if isinstance(extensions, str):
                extensions = [extensions]
            item["extensions"] = self._dedupe_create_list([str(value).strip() for value in extensions if str(value).strip()])
            rows.append(item)
        return rows

    def _project_credit_contract_payload(self, config: dict | None = None) -> dict:
        """Build a bounded, schema-backed contract for Credits-to-Project blocks."""
        config = config or {}
        configured_file_types = {
            str(value).strip().lower()
            for value in (config.get("file_types") or [])
            if str(value).strip()
        }
        configured_extensions = set()
        for file_type in self.schema.get("file_types", []) if isinstance(getattr(self, "schema", {}), dict) else []:
            if not isinstance(file_type, dict):
                continue
            ft_id = str(file_type.get("id") or "").strip().lower()
            if ft_id in configured_file_types:
                configured_extensions.update(str(ext).strip().lower() for ext in file_type.get("extensions", []) if str(ext).strip())
        infoboxes: list[dict] = []
        for row in self._project_credit_infoboxes():
            applies_to_file_types = {str(value).lower() for value in row.get("applies_to_file_types", [])}
            extensions = {str(value).lower() for value in row.get("extensions", [])}
            selected = not configured_file_types or bool(applies_to_file_types & configured_file_types) or bool(extensions & configured_extensions)
            if not selected:
                continue
            infoboxes.append({
                "id": row.get("id"),
                "label": row.get("label"),
                "applies_to_file_types": row.get("applies_to_file_types", []),
                "extensions": row.get("extensions", []),
                "comment_style": row.get("comment_style"),
                "insertion_policy": row.get("insertion_policy"),
                "duplicate_policy": row.get("duplicate_policy"),
                "editable_fields": row.get("editable_fields", []),
                "tokens": row.get("tokens", []),
                "template": row.get("template"),
                "validation_focus": row.get("validation_focus", []),
            })
        if not infoboxes:
            for row in self._project_credit_infoboxes():
                infoboxes.append({
                    "id": row.get("id"),
                    "label": row.get("label"),
                    "applies_to_file_types": row.get("applies_to_file_types", []),
                    "extensions": row.get("extensions", []),
                    "comment_style": row.get("comment_style"),
                    "insertion_policy": row.get("insertion_policy"),
                    "duplicate_policy": row.get("duplicate_policy"),
                    "editable_fields": row.get("editable_fields", []),
                    "tokens": row.get("tokens", []),
                    "template": row.get("template"),
                    "validation_focus": row.get("validation_focus", []),
                })
        if not infoboxes:
            return {}
        token_order: list[str] = []
        editable_fields: dict[str, dict] = {}
        for row in infoboxes:
            token_order.extend(str(token) for token in row.get("tokens", []) if str(token).strip())
            for field in row.get("editable_fields", []) if isinstance(row.get("editable_fields"), list) else []:
                if isinstance(field, dict) and field.get("id"):
                    editable_fields[str(field.get("id"))] = dict(field)
        return {
            "schema_version": "2026.project-credit-infobox.v1",
            "feature_id": "credits_to_project",
            "purpose": "Editable schema-backed copyright/meta infoboxes for generated or patched project files.",
            "target_file_types": ["js", "txt", "vue"],
            "tokens": self._dedupe_create_list(token_order),
            "editable_fields": list(editable_fields.values()),
            "infoboxes": infoboxes,
            "rules": [
                "Use the file-type specific comment syntax; never paste a JS block into .vue or .txt files.",
                "Insert only when the target file type is selected or the path extension matches the infobox schema.",
                "Update an existing Credits-to-Project block instead of duplicating it.",
                "Keep legal/copyright values user-editable; do not invent ownership or license facts.",
                "Report files skipped because type, extension or insertion point is ambiguous.",
            ],
        }

    def _format_project_credit_infobox_lines(self, config: dict | None = None) -> list[str]:
        contract = self._project_credit_contract_payload(config or {})
        if not contract:
            return []
        lines = [
            "Project credit infobox contract:",
            f"- schema: {contract.get('schema_version')} / feature={contract.get('feature_id')}",
            "- editable tokens: " + ", ".join(contract.get("tokens", []) or ["none"]),
        ]
        for box in contract.get("infoboxes", []):
            extensions = ", ".join(box.get("extensions", [])) or ", ".join(box.get("applies_to_file_types", [])) or "unknown"
            lines.append(f"- {box.get('id')}: {box.get('label')} — {extensions} / {box.get('comment_style')}")
            template = str(box.get("template") or "").strip()
            if template:
                preview = template.replace("\r", "").split("\n")[:4]
                for line in preview:
                    lines.append("  " + line)
                if len(template.splitlines()) > 4:
                    lines.append("  ...")
        return lines

    def _mode_chain_boilerplates(self, mode: str | None = None, domains: list[str] | None = None, config: dict | None = None) -> list[dict]:
        """Return schema-backed prompt boilerplates for a Create mode.

        Stack catalog entries describe project shape. These entries describe the
        reusable, chainable prompt instructions the user can combine with
        @target/path shortcuts and {$field} values. They are intentionally data
        driven so Feature and Refactor mode do not fall back to generic prose.
        """
        mode = str(mode or self.create_mode.get() or "new_project_abstraction").strip() or "new_project_abstraction"
        if mode not in {"new_project_abstraction", "feature_for_existing_project", "refactor_existing_stack"}:
            return []
        config = config or {}
        domain_set = {str(item).strip() for item in (domains or []) if str(item).strip()}
        target = str(config.get("build_target") or self.create_build_target.get() or "").strip().lower()
        path_type = str(config.get("path_type") or self.create_build_target.get() or "").strip().lower()
        # New Project Abstraction stack entries can own exactly one or more
        # chain boilerplates through create_stack_nodes.chain_boilerplate_ids.
        # This keeps Visual Studio Utils, Game Programm, PDF Programm,
        # AI prompt image editor, 3D Tool, Blender Viewer and PDF Slicer
        # as standalone stack/category-bound entries instead of one grouped
        # catch-all catalog plan.
        stack_chain_ids = {str(item).strip() for item in config.get("chain_boilerplate_ids", []) if str(item).strip()}
        stack_node_id = str(config.get("node_id") or "").strip()
        result: list[dict] = []
        for raw in self.schema.get("create_chain_boilerplates", []):
            if not isinstance(raw, dict):
                continue
            modes = self._create_chain_entry_modes(raw)
            if modes and "all" not in modes and mode not in modes:
                continue
            if mode == "new_project_abstraction" and stack_chain_ids:
                raw_id = str(raw.get("id") or "").strip()
                raw_stack_id = str(raw.get("stack_node_id") or "").strip()
                if raw_id not in stack_chain_ids and raw_stack_id != stack_node_id:
                    continue
            applies_domains = {str(item).strip() for item in raw.get("applies_to_domains", []) if str(item).strip()}
            # Generic entries are allowed as fallbacks. Domain-specific entries are
            # preferred when Build.complete/Start evidence provides signals.
            if domain_set and applies_domains and not (domain_set & applies_domains or "generic_project" in applies_domains):
                continue
            applies_targets = {str(item).strip().lower() for item in (raw.get("applies_to_targets") or raw.get("applies_to_path_types") or []) if str(item).strip()}
            if applies_targets and "any" not in applies_targets and target not in applies_targets and path_type not in applies_targets:
                continue
            fields = [dict(item) for item in raw.get("fields", []) if isinstance(item, dict)]
            tokens = self._dedupe_create_list([str(item) for item in raw.get("tokens", []) if str(item).strip()])
            result.append({
                "id": str(raw.get("id") or "").strip(),
                "label": str(raw.get("label") or raw.get("id") or "").strip(),
                "display_name": str(raw.get("display_name") or raw.get("label") or raw.get("id") or "").strip(),
                "context_hint": str(raw.get("context_hint") or raw.get("quick_context") or "").strip(),
                "group": str(raw.get("group") or raw.get("catalog_category") or raw.get("stack_category") or "").strip(),
                "category": str(raw.get("category") or raw.get("stack_category") or raw.get("group") or "").strip(),
                "stack_category": str(raw.get("stack_category") or raw.get("category") or raw.get("group") or "").strip(),
                "catalog_category": str(raw.get("catalog_category") or raw.get("category") or raw.get("group") or "").strip(),
                "stack_node_id": str(raw.get("stack_node_id") or "").strip(),
                "order": int(raw.get("order") or 999),
                "mode": mode,
                "intent": str(raw.get("intent") or "").strip(),
                "template": str(raw.get("template") or "").strip(),
                "example": str(raw.get("example") or "").strip(),
                "fields": fields,
                "tokens": tokens,
                "applies_to_domains": sorted(applies_domains),
                "applies_to_targets": sorted(applies_targets),
                "timeline_tokens": self._dedupe_create_list([str(item) for item in raw.get("timeline_tokens", []) if str(item).strip()]),
                "references": self._create_supported_ids("reference_domains", [str(item) for item in raw.get("references", [])]),
                "roles": self._create_supported_ids("operation_roles", [str(item) for item in raw.get("roles", [])]),
                "weights": self._dedupe_create_list([str(item) for item in raw.get("weights", []) if str(item).strip()]),
                "validation_focus": [str(item) for item in raw.get("validation_focus", []) if str(item).strip()],
                "rules": [str(item) for item in raw.get("rules", []) if str(item).strip()],
                "schema_family": str(raw.get("schema_family") or "").strip(),
                "specialization": str(raw.get("specialization") or "").strip(),
                "specialization_label": str(raw.get("specialization_label") or "").strip(),
                "overlay_scale": str(raw.get("overlay_scale") or "").strip(),
                "overlay_scale_id": str(raw.get("overlay_scale_id") or "").strip(),
                "overlay_contract_id": str(raw.get("overlay_contract_id") or "").strip(),
                "chain_scope": str(raw.get("chain_scope") or "").strip(),
                "selector_policy": str(raw.get("selector_policy") or "").strip(),
                "user_goal": str(raw.get("user_goal") or raw.get("user_friendly_summary") or "").strip(),
                "user_friendly_summary": str(raw.get("user_friendly_summary") or raw.get("user_goal") or "").strip(),
                "context_alignment": [str(item) for item in raw.get("context_alignment", []) if str(item).strip()],
                "context_resolution_order": [str(item) for item in raw.get("context_resolution_order", []) if str(item).strip()],
                "acceptance_criteria": [str(item) for item in raw.get("acceptance_criteria", []) if str(item).strip()],
                "output_contract": [str(item) for item in raw.get("output_contract", []) if str(item).strip()],
                "non_goals": [str(item) for item in raw.get("non_goals", []) if str(item).strip()],
                "professional_guardrails": [str(item) for item in raw.get("professional_guardrails", []) if str(item).strip()],
                "source_policy": str(raw.get("source_policy") or "").strip(),
                "ptb_schema_alignment": raw.get("ptb_schema_alignment", {}),
                "doc_structure": [str(item) for item in raw.get("doc_structure", []) if str(item).strip()],
                "update_plan_contract": raw.get("update_plan_contract", {}),
                "test_strategy": raw.get("test_strategy", {}),
                "resource_reuse_policy": raw.get("resource_reuse_policy", {}),
                "local_resource_detection": [str(item) for item in raw.get("local_resource_detection", []) if str(item).strip()],
            })
        if not result and domain_set:
            # If target/domain filtering was too strict, keep the mode usable by
            # falling back to mode-matching entries.
            return self._mode_chain_boilerplates(mode=mode, domains=[], config=config)
        return result

    def _create_chain_schema(self, mode: str | None = None, domains: list[str] | None = None, config: dict | None = None) -> dict:
        boilerplates = self._mode_chain_boilerplates(mode=mode, domains=domains, config=config)
        fields_by_id: dict[str, dict] = {}
        tokens: list[str] = []
        timeline_tokens: list[str] = []
        references: list[str] = []
        roles: list[str] = []
        for entry in boilerplates:
            for field in entry.get("fields", []):
                field_id = str(field.get("id") or "").strip()
                if field_id and field_id not in fields_by_id:
                    fields_by_id[field_id] = dict(field)
            tokens.extend(str(item) for item in entry.get("tokens", []) if str(item).strip())
            timeline_tokens.extend(str(item) for item in entry.get("timeline_tokens", []) if str(item).strip())
            references.extend(str(item) for item in entry.get("references", []) if str(item).strip())
            roles.extend(str(item) for item in entry.get("roles", []) if str(item).strip())
        parameter_profile = self._create_mode_parameter_profile()
        parameter_boilerplates = self._create_mode_parameter_boilerplates(parameter_profile)
        parameter_context = self._create_parameter_context_priority(parameter_profile)
        project_credit_contract = self._project_credit_contract_payload(config or {})
        if project_credit_contract:
            tokens.extend(str(item) for item in project_credit_contract.get("tokens", []) if str(item).strip())
        return {
            "schema_version": "2026.create.chain.v2",
            "mode": str(mode or self.create_mode.get() or "new_project_abstraction"),
            "domains": list(domains or []),
            "token_syntax": {
                "target_shortcuts": "@backend/path, @frontend/path, @wrapper/path, @assets/path",
                "field_tokens": "{$field_name} or {$field_name:OPTION|OPTION}",
                "boolean_tokens": "{$component:true|false}",
                "intensity_tokens": "{$intensity:LEICHT|MITTEL|SCHWER}",
                "credit_infobox_tokens": "{$credit_project}, {$credit_owner}, {$credit_year}, {$credit_license}, {$credit_meta_summary}",
                "documentation_test_reuse_tokens": "{$ptb_schema_profile}, {$update_scope}, {$test_goal}, {$test_framework_policy}, {$resource_reuse_scope}",
                "last_git_commit_tokens": "LAST-GIT-COMMIT erzeugt Referenz D aus einem read-only Patch-Tab-Git-Scan; Plan-Auswahl oder Export-Checkbox aktivieren die Referenz.",
                "tasks_sidecar_tokens": "TASKS.TXT is generated during Export from Mode/Routine/Stack and kept as a sidecar outside the ZIP/folder output; left CUSTOM_USER_PROMPT is merged when present.",
                "shortcut_command_tokens": "START, RESTART, REFACTOR, SKIP, EXTEND, SHRINK, FIX and STATUS are direct USER_PROMPT commands; the AI must apply their meaning exactly without expanding tool/access boundaries.",
            },
            "fields": list(fields_by_id.values()),
            "parameter_controls": parameter_profile,
            "parameter_boilerplates": parameter_boilerplates,
            "parameter_context": parameter_context,
            "tokens": self._dedupe_create_list(tokens),
            "timeline_tokens": self._dedupe_create_list(timeline_tokens),
            "references": [],
            "roles": [],
            "available_reference_hints": self._dedupe_create_list(references),
            "available_role_hints": self._dedupe_create_list(roles),
            "selected_entry_policy": "Entry refs/roles stay inactive until that Entry is selected in the Create header.",
            "project_credit_contract": project_credit_contract,
            "boilerplates": boilerplates,
            "rules": [
                "Resolve @target/path against Create Mapping before editing.",
                "Resolve {$field} values in the Prompt tab before export.",
                "Feature mode may extend verified project files; it must not reinstall stack boilerplates.",
                "Refactor mode must state intensity and preserve public behavior unless the prompt explicitly asks otherwise.",
                "Every chained entry must return changed files, validation posture and rollback notes.",
                "Feature/Refactor catalog must stay small: one entry per change type; no generated scale variants.",
                "Parameter boilerplates must be resolved before context chunks are sorted or rendered.",
                "Credits-to-Project infoboxes are schema-backed and must use the target file type's comment syntax.",
                "Software documentation is feature-only and must select exactly one PTB/WELMEC schema profile when requested.",
                "Unit-test plans reuse existing project test frameworks or return an explicit manual gap.",
                "Feature and refactor entries must identify reusable local resources before creating parallel implementations.",
                "Selecting a Last-Git-Commit plan triggers a read-only Git reference scan before the Prompt Builder compiles preview text.",
                "TASKS.TXT is an automatic Prompt Builder export hook/sidecar from Mode/Routine/Stack plus optional left-input task phases; it is not a selectable Create catalog entry.",
                "Shortcut commands are immediate USER_PROMPT CMD semantics; when sent by the user, the receiving AI must apply them exactly while still preserving scope, validation and access boundaries.",
            ],
        }

    def _format_create_chain_boilerplates(self, config: dict | None = None) -> list[str]:
        config = config or self._current_create_config()
        evidence = self._create_project_evidence_payload(config)
        domains = self._create_plan_domains(evidence, config)
        schema = self._create_chain_schema(self.create_mode.get(), domains, config)
        lines: list[str] = [
            f"- Chain schema: {schema.get('schema_version')} / mode={schema.get('mode')} / domains={', '.join(domains)}",
        ]
        for entry in schema.get("boilerplates", []):
            fields = ", ".join(str(field.get("id")) for field in entry.get("fields", []) if field.get("id")) or "none"
            lines.append(f"- {entry.get('id')}: {entry.get('label')} — fields: {fields}")
            if entry.get("user_goal"):
                lines.append(f"  user_goal: {entry.get('user_goal')}")
            if entry.get("context_alignment"):
                lines.append("  context: " + "; ".join(str(value) for value in entry.get("context_alignment", [])[:2]))
            if entry.get("acceptance_criteria"):
                lines.append("  acceptance: " + "; ".join(str(value) for value in entry.get("acceptance_criteria", [])[:3]))
            if entry.get("ptb_schema_alignment"):
                lines.append("  ptb_schema: " + str((entry.get("ptb_schema_alignment") or {}).get("selection_rule") or "schema-aligned"))
            if entry.get("test_strategy"):
                lines.append("  tests: " + str((entry.get("test_strategy") or {}).get("write_gate") or (entry.get("test_strategy") or {}).get("default") or "project-native"))
            if entry.get("resource_reuse_policy"):
                lines.append("  reuse: local resources before new resources")
            template = str(entry.get("template") or "").strip()
            if template:
                lines.append(f"  template: {template}")
        lines.extend(self._format_project_credit_infobox_lines(config))
        return lines or ["- none resolved"]

    def _format_stack_bound_modules(self, key: str, config: dict | None = None, limit: int = 4) -> list[str]:
        config = config or self._current_create_config()
        stack_id = str(config.get("node_id") or "").strip()
        if not stack_id:
            return ["- none resolved"]
        matches = [item for item in self.schema.get(key, []) if isinstance(item, dict) and (str(item.get("stack_node_id") or "").strip() == stack_id or str(item.get("stack_node_id") or "").strip().lower() in {"any", "*", "generic"})]
        if not matches:
            return ["- none resolved"]
        lines: list[str] = []
        for item in matches[:limit]:
            item_id = str(item.get("id") or "")
            label = str(item.get("label") or item_id)
            lines.append(f"- {item_id}: {label}")
            for field_name in ("user_goal", "context_alignment", "context_resolution_order", "resource_reuse_policy", "test_strategy", "steps", "rules", "acceptance_criteria", "validation_focus", "match_rules"):
                values = item.get(field_name) or []
                if isinstance(values, str):
                    values = [values]
                if values:
                    preview = "; ".join(str(value) for value in values[:3])
                    lines.append(f"  {field_name}: {preview}")
                    break
        return lines or ["- none resolved"]

