    def _ai_callback_states(self) -> list[str]:
        return ["IDLE", "PENDING", "PROGRESS", "ERROR", "FINISH"]

    def _ai_callback_design_types(self) -> list[str]:
        return ["PERCENT", "NUMMERIC", "CHRONICAL", "TIMELINE", "BARS", "RADIAL-BAR"]

    def _ai_callback_template_matrix(self) -> dict[str, dict[str, str]]:
        canvas_rule = "Design your own concise text canvas. Show measurable values; do not claim unverifiable completion."
        return {
            "PERCENT": {
                "IDLE": f"IDLE / PERCENT: {canvas_rule} Show task%=0, total%=0, waiting_for=input.",
                "PENDING": f"PENDING / PERCENT: {canvas_rule} Show task%=0, total%=queued_tasks/total_tasks*100 only when a real queue exists, plus next_start.",
                "PROGRESS": f"PROGRESS / PERCENT: {canvas_rule} Show task%=done_steps/total_steps*100, total%=done_tasks/total_tasks*100, current equation and next verifiable step.",
                "ERROR": f"ERROR / PERCENT: {canvas_rule} Show failed_at_step, completed%, remaining%, and safe_next_action.",
                "FINISH": f"FINISH / PERCENT: {canvas_rule} Show task%=100, total%=100 only after validation, plus known_gaps if any.",
            },
            "NUMMERIC": {
                "IDLE": f"IDLE / NUMERIC: {canvas_rule} Show step=0/0, task=0/0, checks=0/0, status=ready.",
                "PENDING": f"PENDING / NUMERIC: {canvas_rule} Show queued_steps=N, task_index=0, next_step=1.",
                "PROGRESS": f"PROGRESS / NUMERIC: {canvas_rule} Show step_index/total_steps, task_index/total_tasks, check_index/total_checks and next measurable unit.",
                "ERROR": f"ERROR / NUMERIC: {canvas_rule} Show failed_step_index, completed_steps, remaining_steps, retry_or_stop.",
                "FINISH": f"FINISH / NUMERIC: {canvas_rule} Show completed_steps=total_steps, completed_tasks=total_tasks, checks_passed/checks_total.",
            },
            "CHRONICAL": {
                "IDLE": f"IDLE / CHRONICAL: {canvas_rule} Show T0=ready and T1=waiting_for_task.",
                "PENDING": f"PENDING / CHRONICAL: {canvas_rule} Show T0=request_received, T1=queued, T2=next_start.",
                "PROGRESS": f"PROGRESS / CHRONICAL: {canvas_rule} Show T0..Tn with done/open, current Tn, next Tn+1 and verifiable handoff.",
                "ERROR": f"ERROR / CHRONICAL: {canvas_rule} Show timeline break at Tn, last_valid_T, safe recovery step.",
                "FINISH": f"FINISH / CHRONICAL: {canvas_rule} Show T0..Tn all closed, validation Tn+1, gaps if any.",
            },
            "TIMELINE": {
                "IDLE": f"IDLE / TIMELINE: {canvas_rule} Draw [ready]—[waiting]—[not started].",
                "PENDING": f"PENDING / TIMELINE: {canvas_rule} Draw [received]—[queued]—[next].",
                "PROGRESS": f"PROGRESS / TIMELINE: {canvas_rule} Draw [done]—[active]—[next], including step index and validation station.",
                "ERROR": f"ERROR / TIMELINE: {canvas_rule} Draw [done]—[failed]—[safe next], with error boundary.",
                "FINISH": f"FINISH / TIMELINE: {canvas_rule} Draw [done]—[validated]—[handoff], with known gaps listed separately.",
            },
            "BARS": {
                "IDLE": f"IDLE / BARS: {canvas_rule} Draw Task[----------] 0/0 and Total[----------] 0/0.",
                "PENDING": f"PENDING / BARS: {canvas_rule} Draw Queue[###-------] only from real queued units and Start[----------].",
                "PROGRESS": f"PROGRESS / BARS: {canvas_rule} Draw Task[done/total] and Total[done/total], current phase and next check.",
                "ERROR": f"ERROR / BARS: {canvas_rule} Draw Task[done|failed|open], Total[done/total], safe next action.",
                "FINISH": f"FINISH / BARS: {canvas_rule} Draw Task[##########] total/total and Total[##########] total/total after validation.",
            },
            "RADIAL-BAR": {
                "IDLE": f"IDLE / RADIAL-BAR: {canvas_rule} Describe ring(Task)=0, ring(Total)=0, center=ready.",
                "PENDING": f"PENDING / RADIAL-BAR: {canvas_rule} Describe ring(Task)=queued/total, ring(Total)=0, center=pending.",
                "PROGRESS": f"PROGRESS / RADIAL-BAR: {canvas_rule} Describe ring(Task)=done_steps/total_steps, ring(Total)=done_tasks/total_tasks, center=active step.",
                "ERROR": f"ERROR / RADIAL-BAR: {canvas_rule} Describe ring(Task)=last_valid_progress, ring(Total)=partial, center=error boundary.",
                "FINISH": f"FINISH / RADIAL-BAR: {canvas_rule} Describe ring(Task)=100%, ring(Total)=100%, center=validated handoff.",
            },
        }

    def _callback_var_value(self, attr: str, fallback: str) -> str:
        """Read a callback-related tk variable safely during early UI construction.

        Some Create/Prompt export paths are refreshed while the Prompt Builder
        widgets are not built yet. The callback contract may therefore only
        have the tk.StringVar available, or in very early startup no attribute
        at all. This helper keeps those paths deterministic and prevents Tk
        __getattr__ from surfacing missing helper/widget names as app startup
        crashes.
        """
        try:
            var = getattr(self, attr, None)
        except Exception:
            return str(fallback)
        if var is None:
            return str(fallback)
        try:
            value = var.get() if hasattr(var, "get") else var
        except Exception:
            return str(fallback)
        if value is None:
            return str(fallback)
        text = str(value).strip()
        return text if text else str(fallback)

    def _ai_callback_templates(self, design_type: str | None = None) -> dict[str, str]:
        design = str(design_type or self._callback_var_value("ai_callback_design_type", "PERCENT")).strip().upper()
        matrix = self._ai_callback_template_matrix()
        return matrix.get(design, matrix["PERCENT"])

    def _current_ai_callback_template_text(self) -> str:
        key = self._callback_var_value("ai_callback_template", "PROGRESS").strip().upper()
        templates = self._ai_callback_templates()
        return templates.get(key, templates["PROGRESS"])

    def _on_ai_callback_template_changed(self, _event=None) -> None:
        key = self._callback_var_value("ai_callback_template", "PROGRESS").strip().upper()
        design = self._callback_var_value("ai_callback_design_type", "PERCENT").strip().upper()
        template = self._current_ai_callback_template_text()
        widget = getattr(self, "ai_callback_text", None)
        if widget is not None:
            try:
                widget.delete("1.0", "end")
                widget.insert("1.0", template)
            except Exception:
                pass
        try:
            self.ai_callback_text_value.set(template)
        except Exception:
            pass
        try:
            self.ai_callback_status.set(f"AI-CALLBACK: {key} / {design}")
        except Exception:
            pass

    def _ai_response_callback_contract(self) -> dict:
        key = self._callback_var_value("ai_callback_template", "PROGRESS").strip().upper()
        design = self._callback_var_value("ai_callback_design_type", "PERCENT").strip().upper()
        widget = getattr(self, "ai_callback_text", None)
        try:
            text = widget.get("1.0", "end").strip() if widget is not None else self._callback_var_value("ai_callback_text_value", "").strip()
        except Exception:
            text = self._callback_var_value("ai_callback_text_value", "").strip()
        if not text:
            text = self._current_ai_callback_template_text()
        return {
            "field": "AI-CALLBACK",
            "template": key,
            "design_type": design,
            "text": text,
            "states": self._ai_callback_states(),
            "design_types": self._ai_callback_design_types(),
            "purpose": "Mathematical AI response design for IDLE, ERROR, PROGRESS, PENDING and FINISH; the AI must design its own text canvas. Affects response shape only, not tool rights or scope.",
        }

    def _target_expected_reference_role_ids(self, target: SaveTarget, limit: int = 6) -> tuple[list[str], list[str]]:
        target = target.normalized(self.schema)
        profiles = set(str(item) for item in (target.boilerplate_profiles or []) if str(item).strip())
        file_types = set(str(item) for item in (target.file_types or []) if str(item).strip())
        path_type = str(target.path_type or "")

        def applies(item: dict) -> bool:
            path_types = {str(value) for value in item.get("applies_to_path_types", []) if str(value).strip()}
            applies_files = {str(value) for value in item.get("applies_to_file_types", []) if str(value).strip()}
            applies_profiles = {str(value) for value in item.get("applies_to_profiles", []) if str(value).strip()}
            matched = False
            if path_types and path_type in path_types:
                matched = True
            if applies_files and file_types.intersection(applies_files):
                matched = True
            if applies_profiles and profiles.intersection(applies_profiles):
                matched = True
            return matched

        references = [str(item.get("id")) for item in self.schema.get("reference_domains", []) if isinstance(item, dict) and item.get("id") and applies(item)]
        reference_set = set(references)
        roles = []
        for item in self.schema.get("operation_roles", []):
            if not isinstance(item, dict) or not item.get("id"):
                continue
            linked_refs = {str(value) for value in item.get("reference_domains", []) if str(value).strip()}
            if applies(item) or (linked_refs and linked_refs.intersection(reference_set)):
                roles.append(str(item.get("id")))
        return self._dedupe_create_list(references)[:limit], self._dedupe_create_list(roles)[:limit]

    # ---------- Prompt Tab ----------
    def _prompt_type_values(self) -> list[str]:
        """Return all prompt type IDs from every loaded schema, with stable fallback."""
        values = list(self.schema.get("supported_prompt_text_types", []) if isinstance(getattr(self, "schema", {}), dict) else [])
        if not values:
            values = [str(item.get("id")) for item in self.schema.get("prompt_text_types", []) if isinstance(item, dict) and item.get("id")]
        defaults = [
            "operator_role",
            "mindset_layer",
            "custom_weighted_prompt",
            "codex_role",
            "webagent_role",
            "visual_reference_role",
            "documentation_role",
            "analytics_role",
            "readme_role",
            "prompt_architect_role",
            "prompt_eval_role",
            "translation_role",
            "marketing_role",
            "math_correctness_role",
            "economics_revenue_role",
            "android_role",
            "ios_role",
            "summarize_role",
            "search_fix_role",
        ]
        return sorted(dict.fromkeys([v for v in values + defaults if v]))

