    def _app_settings_path(self) -> Path:
        """Return the local, user-editable settings file for INFO/Credits state."""
        try:
            base = Path(os.environ.get("APPDATA") or os.environ.get("XDG_CONFIG_HOME") or Path.home())
            return base / "prompt-guide" / "app_settings.json"
        except Exception:
            return Path("app_settings.json")

