    def _coerce_setting_value_for_var(self, variable, value):
        if isinstance(variable, tk.BooleanVar):
            if isinstance(value, str):
                return value.strip().lower() in {"1", "true", "yes", "yes", "on"}
            return bool(value)
        if isinstance(variable, tk.IntVar):
            try:
                return int(value)
            except Exception:
                return 0
        return "" if value is None else str(value)

    def _apply_persisted_app_settings_to_vars(self) -> None:
        stored = self._app_settings_cache.get("app_settings", {}) if isinstance(getattr(self, "_app_settings_cache", {}), dict) else {}
        if not isinstance(stored, dict):
            return
        stored = self._sanitize_persisted_app_settings(stored)
        for spec in self._info_setting_specs():
            if not self._is_persistable_app_setting_spec(spec):
                continue
            var_name = str(spec.get("var") or "")
            if not var_name or var_name not in stored:
                continue
            variable = getattr(self, var_name, None)
            if variable is None or not hasattr(variable, "set"):
                continue
            value = stored[var_name]
            try:
                variable.set(self._coerce_setting_value_for_var(variable, value))
            except Exception:
                pass
        try:
            current_schema_dir = Path(self.schema_dir.get())
            resolved_schema_dir = resolve_schema_dir(current_schema_dir)
            if str(resolved_schema_dir) != str(current_schema_dir) or not any(resolved_schema_dir.rglob("*.json")):
                self.schema_dir.set(str(resolved_schema_dir))
        except Exception:
            try:
                self.schema_dir.set(str(default_schema_dir()))
            except Exception:
                pass

    def _current_app_settings_payload(self) -> dict:
        payload: dict[str, object] = {}
        for spec in self._info_setting_specs():
            if not self._is_persistable_app_setting_spec(spec):
                continue
            var_name = str(spec.get("var") or "")
            variable = getattr(self, var_name, None)
            if variable is None or not hasattr(variable, "get"):
                continue
            try:
                payload[var_name] = variable.get()
            except Exception:
                pass
        return self._sanitize_persisted_app_settings(payload)

    def _current_info_settings_payload(self) -> dict:
        defaults = self._default_info_settings()
        payload = {
            "schema_version": defaults["schema_version"],
            "updated_at": datetime.now().isoformat(timespec="seconds"),
            "ui_language": self.ui_language.get() if hasattr(self, "ui_language") else "ENGLISH",
            "show_startup_donation": bool(self.info_show_startup_donation.get()),
            "app_settings": self._current_app_settings_payload(),
        }
        for key in self._locked_info_setting_keys():
            if key in defaults:
                payload[key] = defaults[key]
        return payload

    def _sync_info_settings_to_tabs(self, reason: str = "info_settings") -> None:
        self.info_settings_status.set(f"Settings synchronized ({reason}).")
        try:
            self._on_export_setting_changed()
        except Exception:
            pass
        try:
            self._on_operator_flow_changed()
        except Exception:
            pass
        try:
            self._schedule_create_worktree_refresh(reason)
        except Exception:
            try:
                self._schedule_create_preview_refresh()
            except Exception:
                pass
        try:
            self._refresh_create_stack_control_state()
        except Exception:
            pass
        try:
            self._refresh_patch_status()
        except Exception:
            pass
        try:
            self._schedule_prompt_builder_flow_refresh()
        except Exception:
            pass

    def _on_ui_language_changed(self, _event=None) -> None:
        """Reload locale/{LANG}.json and apply UI translations immediately."""
        try:
            self._reload_ui_locale()
            self._apply_ui_locale()
            self.info_settings_status.set(self._ui_text("UI language applied. Save settings to persist it.", "UI language applied. Save settings to persist it."))
        except Exception as exc:
            try:
                self.info_settings_status.set(f"UI language change failed: {exc}")
            except Exception:
                pass

    def _save_info_settings(self, silent: bool = False) -> None:
        payload = self._current_info_settings_payload()
        self.info_project_title.set(str(payload["project_title"]))
        self.info_credit_owner.set(str(payload["credit_owner"]))
        self.info_credit_handle.set(str(payload["credit_handle"]))
        self.info_github_url.set(str(payload["github_url"]))
        self.info_paypal_url.set(str(payload["paypal_url"]))
        self.info_donation_heading.set(str(payload["donation_heading"]))
        self.info_donation_body.set(str(payload["donation_body"]))
        self.info_disclaimer_text_value.set(str(payload["disclaimer"]))
        path = self._app_settings_path()
        try:
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
            self._app_settings_cache = payload
            self._sync_info_settings_to_tabs("saved")
            self.info_settings_status.set(self._ui_text("Settings saved and synchronized across tabs: {path}", "Settings saved and synchronized across tabs: {path}").format(path=path))
            if not silent:
                messagebox.showinfo("App settings", f"Saved:\n{path}")
        except Exception as exc:
            self.info_settings_status.set(self._ui_text("Settings save failed: {error}", "Settings save failed: {error}").format(error=exc))
            if not silent:
                messagebox.showerror("App settings", str(exc))

    def _reset_info_settings(self) -> None:
        defaults = self._default_info_settings()
        self.ui_language.set(str(defaults.get("ui_language") or "ENGLISH"))
        self.info_show_startup_donation.set(bool(defaults["show_startup_donation"]))
        self.info_project_title.set(str(defaults["project_title"]))
        self.info_credit_owner.set(str(defaults["credit_owner"]))
        self.info_credit_handle.set(str(defaults["credit_handle"]))
        self.info_github_url.set(str(defaults["github_url"]))
        self.info_paypal_url.set(str(defaults["paypal_url"]))
        self.info_donation_heading.set(str(defaults["donation_heading"]))
        self.info_donation_body.set(str(defaults["donation_body"]))
        self.info_disclaimer_text_value.set(str(defaults["disclaimer"]))
        self._save_info_settings(silent=True)

    def _setting_value(self, name: str, fallback: str = "") -> str:
        value = getattr(self, name, None)
        try:
            if hasattr(value, "get"):
                return str(value.get())
        except Exception:
            return fallback
        return fallback

