    def _refresh_info_settings_overview(self) -> None:
        tree = getattr(self, "info_settings_tree", None)
        if tree is None:
            return
        try:
            for item in tree.get_children():
                tree.delete(item)
            for area, key, value in self._app_settings_overview_rows():
                tree.insert("", "end", values=(area, key, value))
        except Exception:
            pass

    def _open_external_url(self, url: str) -> None:
        target = str(url or "").strip()
        if not target:
            messagebox.showinfo("No URL", "No URL configured.")
            return
        if not re.match(r"^https?://", target, flags=re.IGNORECASE):
            messagebox.showerror("Invalid URL", "Only http/https links are opened.")
            return
        try:
            webbrowser.open_new_tab(target)
        except Exception as exc:
            messagebox.showerror("Open URL failed", str(exc))

    def _maybe_show_startup_donation_dialog(self) -> None:
        if not bool(getattr(self, "info_show_startup_donation", tk.BooleanVar(value=False)).get()):
            return
        if getattr(self, "_startup_donation_dialog_shown", False):
            return
        self._startup_donation_dialog_shown = True
        self._show_donation_dialog(startup=True)

    def _app_window_geometry(self) -> tuple[int, int, int, int]:
        """Return a stable geometry tuple for the visible application window."""
        try:
            self.update_idletasks()
            width = max(int(self.winfo_width()), 1)
            height = max(int(self.winfo_height()), 1)
            x = int(self.winfo_rootx())
            y = int(self.winfo_rooty())
            if width <= 8 or height <= 8:
                width = max(int(self.winfo_screenwidth() * 0.72), 640)
                height = max(int(self.winfo_screenheight() * 0.72), 420)
                x = max((int(self.winfo_screenwidth()) - width) // 2, 0)
                y = max((int(self.winfo_screenheight()) - height) // 2, 0)
            return x, y, width, height
        except Exception:
            return 0, 0, 800, 520

    def _center_toplevel_over_app(self, dialog: tk.Toplevel) -> None:
        """Place a modal dialog exactly center-center above the app window."""
        try:
            dialog.update_idletasks()
            app_x, app_y, app_w, app_h = self._app_window_geometry()
            dialog_w = max(int(dialog.winfo_width()), int(dialog.winfo_reqwidth()), 1)
            dialog_h = max(int(dialog.winfo_height()), int(dialog.winfo_reqheight()), 1)
            x = app_x + max((app_w - dialog_w) // 2, 0)
            y = app_y + max((app_h - dialog_h) // 2, 0)
            dialog.geometry(f"+{x}+{y}")
        except Exception:
            pass

    def _create_modal_dim_overlay(self, owner: tk.Toplevel | None = None, alpha: float = 0.46) -> tk.Toplevel | None:
        """Dim the main app window while a modal dialog is active.

        The overlay is a real top-level window sized to the app.  It is raised
        before the dialog, uses topmost only for the modal lifetime, and falls
        back to an opaque dark surface when alpha is unavailable so the dimming
        is still visibly present instead of silently disappearing.
        """
        self._destroy_modal_dim_overlay()
        try:
            overlay = tk.Toplevel(self)
            overlay.withdraw()
            overlay.overrideredirect(True)
            overlay.configure(background="#111111")
            overlay.transient(self)
            try:
                overlay.attributes("-alpha", max(0.18, min(float(alpha), 0.85)))
            except Exception:
                overlay.configure(background="#303030")

            def sync_overlay_geometry(event: object | None = None) -> None:
                try:
                    if not overlay.winfo_exists():
                        return
                    x, y, width, height = self._app_window_geometry()
                    overlay.geometry(f"{width}x{height}+{x}+{y}")
                except Exception:
                    pass

            sync_overlay_geometry()
            overlay.deiconify()
            try:
                overlay.attributes("-topmost", True)
            except Exception:
                pass
            try:
                overlay.wait_visibility()
            except Exception:
                pass
            overlay.lift()
            overlay.update_idletasks()

            def focus_owner(event: object | None = None) -> None:
                try:
                    if owner is not None and owner.winfo_exists():
                        owner.lift(overlay)
                        owner.focus_force()
                except Exception:
                    pass

            overlay.bind("<Button-1>", focus_owner)
            bind_id = self.bind("<Configure>", sync_overlay_geometry, add="+")
            self._active_modal_dim_overlay = overlay
            self._active_modal_dim_overlay_bind = bind_id
            return overlay
        except Exception:
            self._active_modal_dim_overlay = None
            self._active_modal_dim_overlay_bind = None
            return None

    def _destroy_modal_dim_overlay(self, overlay: tk.Toplevel | None = None) -> None:
        target = overlay or getattr(self, "_active_modal_dim_overlay", None)
        bind_id = getattr(self, "_active_modal_dim_overlay_bind", None)
        if bind_id:
            try:
                self.unbind("<Configure>", bind_id)
            except Exception:
                pass
        self._active_modal_dim_overlay_bind = None
        self._active_modal_dim_overlay = None
        try:
            if target is not None and target.winfo_exists():
                try:
                    target.attributes("-topmost", False)
                except Exception:
                    pass
                target.destroy()
        except Exception:
            pass

    def _show_donation_dialog(self, startup: bool = False) -> None:
        dialog = tk.Toplevel(self)
        dialog.withdraw()
        dialog.title(self._ui_text("Support development", "Support development"))
        dialog.transient(self)
        dialog.resizable(False, False)
        show_again = tk.BooleanVar(value=bool(self.info_show_startup_donation.get()))
        body = ttk.Frame(dialog, padding=16)
        body.pack(fill="both", expand=True)
        ttk.Label(body, text=self._info_donation_heading_text(), font=("Segoe UI", 14, "bold"), wraplength=460).pack(anchor="w")
        ttk.Label(
            body,
            text=self._info_donation_body_text(),
            wraplength=460,
            justify="left",
        ).pack(anchor="w", pady=(8, 8))
        ttk.Label(
            body,
            text=self._ui_text("Donation note: contributions are voluntary. The app remains fully usable without a donation.", "Donation note: contributions are voluntary. The app remains fully usable without a donation."),
            wraplength=460,
        ).pack(anchor="w", pady=(0, 8))
        ttk.Checkbutton(body, text=self._ui_text("Show on startup", "Show on startup"), variable=show_again).pack(anchor="w", pady=(0, 10))
        actions = ttk.Frame(body)
        actions.pack(fill="x")

        overlay: tk.Toplevel | None = None

        def close(save: bool = True) -> None:
            try:
                if save:
                    self.info_show_startup_donation.set(bool(show_again.get()))
                    self._save_info_settings(silent=True)
            finally:
                try:
                    dialog.grab_release()
                except Exception:
                    pass
                self._destroy_modal_dim_overlay(overlay)
                try:
                    dialog.destroy()
                except Exception:
                    pass

        ttk.Button(actions, text=self._ui_text("❤️ Donate now", "❤️ Donate now"), command=lambda: self._open_external_url(self.info_paypal_url.get())).pack(side="left")
        ttk.Button(actions, text=self._ui_text("Open INFO", "Open INFO"), command=lambda: (close(True), self.notebook.select(self.info_tab))).pack(side="left", padx=(8, 0))
        ttk.Button(actions, text=self._ui_text("Later", "Later"), command=lambda: close(True)).pack(side="right")
        dialog.protocol("WM_DELETE_WINDOW", lambda: close(True))
        try:
            dialog.update_idletasks()
            overlay = self._create_modal_dim_overlay(dialog)
            self._center_toplevel_over_app(dialog)
            dialog.deiconify()
            if overlay is not None:
                dialog.lift(overlay)
            else:
                dialog.lift(self)
            try:
                dialog.attributes("-topmost", True)
            except Exception:
                pass
            dialog.grab_set()
            dialog.focus_force()
        except Exception:
            try:
                dialog.deiconify()
                dialog.grab_set()
            except Exception:
                pass

