    def _build_settings_tab(self) -> None:
        parent = self.settings_tab
        parent.columnconfigure(0, weight=1)
        parent.rowconfigure(2, weight=1)
        ttk.Label(parent, text="Settings", font=("Segoe UI", 14, "bold")).grid(row=0, column=0, sticky="w")
        ttk.Label(
            parent,
            text=(
                "These settings write directly into the existing app variables. Changes are used across Start, Export, "
                "Create and Prompt Builder. Patch controls and structural Create controls are intentionally excluded because they are sensitive. "
                "UI language changes are persisted here; export and generated content remain English."
            ),
            wraplength=1060,
            justify="left",
        ).grid(row=1, column=0, sticky="w", pady=(6, 10))

        canvas_frame = ttk.Frame(parent)
        canvas_frame.grid(row=2, column=0, sticky="nsew")
        canvas_frame.rowconfigure(0, weight=1)
        canvas_frame.columnconfigure(0, weight=1)
        palette = getattr(self, "palette", palette_from_theme({"is_dark": False, "accent": "#3584e4"}))
        canvas = tk.Canvas(canvas_frame, highlightthickness=0, background=palette.get("field", "#ffffff"))
        scrollbar = ttk.Scrollbar(canvas_frame, orient="vertical", command=canvas.yview)
        content = ttk.Frame(canvas)
        window_id = canvas.create_window((0, 0), window=content, anchor="nw")

        def _sync_scrollregion(_event=None):
            try:
                canvas.configure(scrollregion=canvas.bbox("all"))
            except Exception:
                pass

        def _sync_width(event):
            try:
                canvas.itemconfigure(window_id, width=event.width)
            except Exception:
                pass

        content.bind("<Configure>", _sync_scrollregion)
        canvas.bind("<Configure>", _sync_width)
        canvas.configure(yscrollcommand=scrollbar.set)
        canvas.grid(row=0, column=0, sticky="nsew")
        scrollbar.grid(row=0, column=1, sticky="ns")
        self.info_settings_canvas = canvas
        self.info_settings_controls = {}

        grouped: dict[str, list[dict]] = {}
        for spec in self._info_setting_specs():
            grouped.setdefault(str(spec.get("section") or "App"), []).append(spec)

        section_order = ["App", "Export", "Operator", "Scope", "Create", "Runtime"]
        for col in range(3):
            content.columnconfigure(col, weight=1, uniform="settings_columns")
        index = 0
        for section in section_order:
            specs = grouped.get(section, [])
            if not specs:
                continue
            row = index // 3
            col = index % 3
            box = ttk.LabelFrame(content, text=section, padding=8)
            box.grid(row=row, column=col, sticky="nsew", padx=(0, 10), pady=(0, 10))
            box.columnconfigure(1, weight=1)
            for item_row, spec in enumerate(specs):
                self._render_info_setting_control(box, item_row, spec)
            index += 1

        action_row = ttk.Frame(parent)
        action_row.grid(row=3, column=0, sticky="ew", pady=(10, 0))
        ttk.Button(action_row, text="Save settings", command=self._save_info_settings).pack(side="left")
        ttk.Button(action_row, text="Synchronize now", command=lambda: self._sync_info_settings_to_tabs("manual_sync")).pack(side="left", padx=(8, 0))
        ttk.Label(parent, textvariable=self.info_settings_status, wraplength=1060).grid(row=4, column=0, sticky="w", pady=(8, 0))

    def _render_info_setting_control(self, parent: ttk.Frame, row: int, spec: dict) -> None:
        label = str(spec.get("label") or spec.get("var") or "Setting")
        var_name = str(spec.get("var") or "")
        variable = getattr(self, var_name, None)
        setting_type = str(spec.get("type") or "entry")
        ttk.Label(parent, text=label).grid(row=row, column=0, sticky="w", pady=3, padx=(0, 8))

        def changed(*_args):
            command = spec.get("command")
            try:
                if callable(command):
                    command()
            except TypeError:
                try:
                    command(None)
                except Exception:
                    pass
            except Exception:
                pass
            self.info_settings_status.set(self._ui_text("Changed: {label}. Save persists the app settings.", "Changed: {label}. Save persists the app settings.").format(label=label))

        if setting_type == "checkbox" and isinstance(variable, tk.BooleanVar):
            widget = ttk.Checkbutton(parent, variable=variable, command=changed)
            widget.grid(row=row, column=1, sticky="w", pady=3)
        elif setting_type == "select":
            values = list(spec.get("values") or [])
            widget = ttk.Combobox(parent, textvariable=variable, values=values, state="readonly", width=34)
            widget.grid(row=row, column=1, sticky="ew", pady=3)
            widget.bind("<<ComboboxSelected>>", lambda _event, _changed=changed: _changed(), add="+")
        elif setting_type == "path":
            holder = ttk.Frame(parent)
            holder.grid(row=row, column=1, sticky="ew", pady=3)
            holder.columnconfigure(0, weight=1)
            ttk.Entry(holder, textvariable=variable).grid(row=0, column=0, sticky="ew")
            browse = spec.get("browse")
            if callable(browse):
                def browse_and_sync(_browse=browse):
                    try:
                        _browse()
                    finally:
                        changed()
                ttk.Button(holder, text="Browse", command=browse_and_sync).grid(row=0, column=1, sticky="w", padx=(6, 0))
        elif setting_type == "readonly":
            widget = ttk.Entry(parent, textvariable=variable, state="readonly")
            widget.grid(row=row, column=1, sticky="ew", pady=3)
            ttk.Label(parent, text="read-only").grid(row=row, column=2, sticky="w", padx=(8, 0))
        else:
            widget = ttk.Entry(parent, textvariable=variable)
            widget.grid(row=row, column=1, sticky="ew", pady=3)
        self.info_settings_controls[var_name] = spec

